function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const S = minSide;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const easeInOutCubic = (x) => {
    const v = clamp01(x);
    return v < 0.5 ? 4 * v * v * v : 1 - Math.pow(-2 * v + 2, 3) / 2;
  };
  const lerp = (a, b, k) => a + (b - a) * k;

  const windowRamp = (val, inStart, inEnd, outStart, outEnd) => {
    if (val <= inStart || val >= outEnd) return 0;
    if (val < inEnd) return easeInOutCubic((val - inStart) / (inEnd - inStart));
    if (val > outStart) return 1 - easeInOutCubic((val - outStart) / (outEnd - outStart));
    return 1;
  };

  const roundRectPath = (x, y, w, h, r) => {
    const rad = Math.max(0, Math.min(r, w * 0.5, h * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  };

  // 1. Clean Modern Dark Aesthetic Gradient Background (Deep Moss-Black, ZERO glow, ZERO borders)
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, '#030A05');
  bgGrad.addColorStop(0.52, '#07150C');
  bgGrad.addColorStop(1, '#0C2113');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // 2. Seamless Timeline Parameters Driven by t, loopT, currentScene, sceneProgress
  const scenePos = currentScene + sceneProgress; // Continuous [0, 4)
  const loopNorm = (scenePos * sceneDuration) / duration; // [0, 1)
  const twoPi = Math.PI * 2;

  // Gentle proportional 4-beat breathing (1.0 at t=0, 5, 10, 15, 20)
  const beatPhase = 0.5 - 0.5 * Math.cos(loopNorm * twoPi * 4);
  const brainScale = 1 + 0.022 * beatPhase;

  // Analytical seamless orbital angle (2 full integer revolutions over 20s)
  const orbPeakU = 0.40;
  const orbitAngle =
    twoPi *
    (2.0 * loopNorm -
      (0.45 / twoPi) * (Math.sin(twoPi * (loopNorm - orbPeakU)) - Math.sin(-twoPi * orbPeakU)));

  // Phase Envelopes across Scene 0..3 -> t=20 === t=0
  const intakeDrive = windowRamp(loopT, 0.5, 3.2, 8.8, 12.2);
  const synapseCharge = windowRamp(loopT, 4.2, 8.2, 14.2, 18.8);
  const ledgerProcess = windowRamp(loopT, 7.2, 11.4, 15.2, 19.4);
  const peakInsight = windowRamp(loopT, 9.6, 12.0, 14.8, 17.0);

  // Palette Constants
  const colChartreuse = '#A3E635';
  const colMint = '#4ADE80';
  const colTeal = '#2DD4BF';
  const colPaleLime = '#ECFCCB';
  const colPanelFill = '#08140C';
  const colBorderMuted = 'rgba(74, 222, 128, 0.28)';
  const lw = Math.max(1.5, S * 0.0022);

  // 3. Spatial Layout Coordinates (Strict Non-Overlapping Zones)
  const brainCy = cy - 0.008 * S;
  const orbitR = 0.215 * S;
  const crownY = cy - 0.308 * S;
  const crownR = 0.032 * S;
  const pedY = cy + 0.296 * S; // Clean 0.068*S clearance below orbit ring bottom

  const cardW = 0.24 * S;
  const cardH = 0.36 * S;
  const cardTopY = cy - cardH * 0.5;
  const leftCardX = cx - 0.61 * S;
  const rightCardX = cx + 0.37 * S;

  const conduitLeftStart = cx - 0.258 * S; // Clean 0.028*S outside orbitR + orbR
  const conduitLeftEnd = leftCardX + cardW + 0.028 * S; // cx - 0.342*S
  const conduitRightStart = cx + 0.258 * S;
  const conduitRightEnd = rightCardX - 0.028 * S; // cx + 0.342*S
  const conduitY = brainCy;

  // =========================================================================
  // 4. OUTER DATA ORBIT TRACK & 8 SYNCHRONIZED DATA ORBS
  // =========================================================================
  // Subtle concentric ring rail
  ctx.strokeStyle = 'rgba(74, 222, 128, 0.20)';
  ctx.lineWidth = Math.max(1.2, S * 0.0018);
  ctx.beginPath();
  ctx.arc(cx, brainCy, orbitR, 0, twoPi);
  ctx.stroke();

  // Inner reference dash ring
  ctx.save();
  ctx.strokeStyle = 'rgba(45, 212, 191, 0.14)';
  ctx.lineWidth = Math.max(1, S * 0.0014);
  ctx.setLineDash([S * 0.006, S * 0.008]);
  ctx.beginPath();
  ctx.arc(cx, brainCy, orbitR - 0.016 * S, 0, twoPi);
  ctx.stroke();
  ctx.restore();

  // 8 Evenly Spaced Orbs on Orbit Ring (minimum chord gap > 0.16*S, never overlap!)
  for (let i = 0; i < 8; i++) {
    const a = orbitAngle + (i * twoPi) / 8;
    const ox = cx + Math.cos(a) * orbitR;
    const oy = brainCy + Math.sin(a) * orbitR;
    const orbPulse = 0.88 + 0.12 * (0.5 + 0.5 * Math.sin(loopNorm * twoPi * 4 + i * Math.PI * 0.5));
    const or = 0.0135 * S * orbPulse;

    ctx.save();
    ctx.translate(ox, oy);
    // Outer ring border around orb
    ctx.fillStyle = colPanelFill;
    ctx.strokeStyle = i % 2 === 0 ? colChartreuse : colTeal;
    ctx.lineWidth = Math.max(1.3, S * 0.0018);
    ctx.beginPath();
    ctx.arc(0, 0, or, 0, twoPi);
    ctx.fill();
    ctx.stroke();

    // Alternating geometric core inside orb (circle vs diamond)
    ctx.fillStyle = i % 2 === 0 ? colPaleLime : colMint;
    if (i % 2 === 0) {
      ctx.beginPath();
      ctx.arc(0, 0, or * 0.44, 0, twoPi);
      ctx.fill();
    } else {
      const dr = or * 0.52;
      ctx.beginPath();
      ctx.moveTo(0, -dr);
      ctx.lineTo(dr, 0);
      ctx.lineTo(0, dr);
      ctx.lineTo(-dr, 0);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();
  }

  // 4 Fixed Radial Intake/Output Guide Lanes (at ±38 deg, ±142 deg; clear of crown/pedestal/conduits)
  const radialAngles = [-38, 38, 142, -142].map((d) => (d * Math.PI) / 180);
  const radInner = 0.160 * S;
  const radOuter = 0.194 * S;
  for (let rIdx = 0; rIdx < radialAngles.length; rIdx++) {
    const ra = radialAngles[rIdx];
    const cosA = Math.cos(ra);
    const sinA = Math.sin(ra);
    ctx.strokeStyle = 'rgba(163, 230, 53, 0.22)';
    ctx.lineWidth = Math.max(1.2, S * 0.0016);
    ctx.beginPath();
    ctx.moveTo(cx + cosA * radInner, brainCy + sinA * radInner);
    ctx.lineTo(cx + cosA * radOuter, brainCy + sinA * radOuter);
    ctx.stroke();

    // Sliding transfer bead strictly inside [radInner..radOuter]
    const activePulse = clamp01(intakeDrive + peakInsight * 0.5);
    if (activePulse > 0.02) {
      const u = (loopNorm * 4 + rIdx * 0.25) % 1;
      // Inward flow while charging (loopT < 13.5), outward return flow cleanly in Scene 3
      const dirInward = loopT < 13.5 ? 1 - u : u;
      const dist = lerp(radInner + 0.004 * S, radOuter - 0.004 * S, dirInward);
      ctx.fillStyle = `rgba(236, 252, 203, ${(0.85 * activePulse).toFixed(3)})`;
      ctx.beginPath();
      ctx.arc(cx + cosA * dist, brainCy + sinA * dist, 0.0042 * S, 0, twoPi);
      ctx.fill();
    }
  }

  // =========================================================================
  // 5. TOP INSIGHT CROWN NODE (Clean Gap Above Orbit Ring)
  // =========================================================================
  const crownScale = 1 + 0.05 * peakInsight;
  ctx.save();
  ctx.translate(cx, crownY);
  ctx.scale(crownScale, crownScale);

  // Dark disk housing + muted ring
  ctx.fillStyle = colPanelFill;
  ctx.strokeStyle = 'rgba(74, 222, 128, 0.26)';
  ctx.lineWidth = lw * 0.9;
  ctx.beginPath();
  ctx.arc(0, 0, crownR, 0, twoPi);
  ctx.fill();
  ctx.stroke();

  // Active sweep ring around Crown Node
  const crownSweep = 0.20 + 0.80 * synapseCharge;
  ctx.strokeStyle = peakInsight > 0.4 ? colChartreuse : colMint;
  ctx.lineWidth = lw * 1.15;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.arc(0, 0, crownR, -Math.PI * 0.5, -Math.PI * 0.5 + twoPi * crownSweep);
  ctx.stroke();

  // Crisp 4-Point Insight Star inside Crown Node
  const starOuter = 0.015 * S * (0.85 + 0.22 * peakInsight);
  const starInner = starOuter * 0.36;
  ctx.fillStyle = peakInsight > 0.35 ? colPaleLime : colMint;
  ctx.beginPath();
  for (let p = 0; p < 8; p++) {
    const rad = p % 2 === 0 ? starOuter : starInner;
    const ang = (p * Math.PI) / 4 - Math.PI * 0.5;
    if (p === 0) ctx.moveTo(Math.cos(ang) * rad, Math.sin(ang) * rad);
    else ctx.lineTo(Math.cos(ang) * rad, Math.sin(ang) * rad);
  }
  ctx.closePath();
  ctx.fill();
  ctx.restore();

  // =========================================================================
  // 6. CENTRAL GEOMETRIC CIRCUIT BRAIN (Mirror-Symmetric Hemispheres)
  // =========================================================================
  const tracePolylinePoint = (pts, frac) => {
    const f = clamp01(frac);
    let totalLen = 0;
    const segLens = [];
    for (let i = 0; i < pts.length - 1; i++) {
      const dx = pts[i + 1][0] - pts[i][0];
      const dy = pts[i + 1][1] - pts[i][1];
      const d = Math.hypot(dx, dy);
      segLens.push(d);
      totalLen += d;
    }
    let target = f * totalLen;
    for (let i = 0; i < segLens.length; i++) {
      if (target <= segLens[i] || i === segLens.length - 1) {
        const ratio = segLens[i] > 0 ? target / segLens[i] : 0;
        return [
          lerp(pts[i][0], pts[i + 1][0], ratio),
          lerp(pts[i][1], pts[i + 1][1], ratio),
        ];
      }
      target -= segLens[i];
    }
    return pts[pts.length - 1];
  };

  // Three non-intersecting right-hemisphere circuit paths (mirrored automatically for left)
  const rightCircuits = [
    [
      [0.024 * S, -0.068 * S],
      [0.056 * S, -0.068 * S],
      [0.078 * S, -0.090 * S],
      [0.096 * S, -0.090 * S],
    ],
    [
      [0.024 * S, -0.006 * S],
      [0.068 * S, -0.006 * S],
      [0.084 * S, 0.010 * S],
      [0.108 * S, 0.010 * S],
    ],
    [
      [0.024 * S, 0.054 * S],
      [0.048 * S, 0.054 * S],
      [0.070 * S, 0.076 * S],
      [0.088 * S, 0.076 * S],
    ],
  ];

  ctx.save();
  ctx.translate(cx, brainCy);
  ctx.scale(brainScale, brainScale);

  const drawHemisphere = (side) => {
    ctx.save();
    ctx.scale(side, 1);

    // Outer lobe contour strictly bounded within x >= +0.008*S and <= 0.144*S
    const makeLobePath = () => {
      ctx.beginPath();
      ctx.moveTo(0.008 * S, -0.114 * S);
      ctx.bezierCurveTo(0.022 * S, -0.142 * S, 0.088 * S, -0.142 * S, 0.114 * S, -0.090 * S);
      ctx.bezierCurveTo(0.144 * S, -0.070 * S, 0.150 * S, -0.016 * S, 0.134 * S, 0.014 * S);
      ctx.bezierCurveTo(0.146 * S, 0.048 * S, 0.128 * S, 0.106 * S, 0.082 * S, 0.114 * S);
      ctx.bezierCurveTo(0.054 * S, 0.130 * S, 0.018 * S, 0.122 * S, 0.008 * S, 0.094 * S);
      ctx.closePath();
    };

    makeLobePath();
    const lobeGrad = ctx.createLinearGradient(0.008 * S, -0.135 * S, 0.140 * S, 0.120 * S);
    lobeGrad.addColorStop(0, '#0D2415');
    lobeGrad.addColorStop(1, '#07140C');
    ctx.fillStyle = lobeGrad;
    ctx.fill();

    // Crisp outer border illuminated cleanly with synapse charge
    ctx.strokeStyle = synapseCharge > 0.35 ? colMint : 'rgba(74, 222, 128, 0.58)';
    ctx.lineWidth = lw * 1.15;
    ctx.stroke();

    // Subtle inner cortex contour curve
    ctx.strokeStyle = 'rgba(45, 212, 191, 0.20)';
    ctx.lineWidth = Math.max(1, S * 0.0014);
    ctx.beginPath();
    ctx.moveTo(0.024 * S, -0.106 * S);
    ctx.quadraticCurveTo(0.088 * S, -0.114 * S, 0.108 * S, -0.068 * S);
    ctx.stroke();

    // Draw 3 clean internal circuit paths + sequential trim illumination + terminal synapse pads
    for (let c = 0; c < rightCircuits.length; c++) {
      const pts = rightCircuits[c];
      // Base structural trace
      ctx.strokeStyle = 'rgba(74, 222, 128, 0.25)';
      ctx.lineWidth = Math.max(1.3, S * 0.0020);
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.beginPath();
      ctx.moveTo(pts[0][0], pts[0][1]);
      for (let p = 1; p < pts.length; p++) ctx.lineTo(pts[p][0], pts[p][1]);
      ctx.stroke();

      // Staggered active synapse fill along trace
      const stagger = c * 0.16;
      const localCharge = clamp01((synapseCharge - stagger * 0.45) / (1 - stagger * 0.45));
      if (localCharge > 0.01) {
        ctx.strokeStyle = c === 1 ? colChartreuse : colMint;
        ctx.lineWidth = Math.max(1.6, S * 0.0024);
        ctx.beginPath();
        ctx.moveTo(pts[0][0], pts[0][1]);
        const endPt = tracePolylinePoint(pts, localCharge);
        // Draw full segments passed so far + interpolated partial segment
        const totalSeg = pts.length - 1;
        const scaled = localCharge * totalSeg;
        for (let seg = 0; seg < Math.floor(scaled) && seg < totalSeg; seg++) {
          ctx.lineTo(pts[seg + 1][0], pts[seg + 1][1]);
        }
        ctx.lineTo(endPt[0], endPt[1]);
        ctx.stroke();

        // Moving bright pulse bead riding along synapse trace
        const pulseU = (loopNorm * 6 + c * 0.33 + (side < 0 ? 0.15 : 0)) % 1;
        const bp = tracePolylinePoint(pts, pulseU);
        ctx.fillStyle = colPaleLime;
        ctx.beginPath();
        ctx.arc(bp[0], bp[1], 0.0036 * S, 0, twoPi);
        ctx.fill();
      }

      // Spine root node & outer terminal pad
      const rootPt = pts[0];
      const tipPt = pts[pts.length - 1];
      ctx.fillStyle = colPanelFill;
      ctx.strokeStyle = colTeal;
      ctx.lineWidth = Math.max(1.2, S * 0.0016);
      ctx.beginPath();
      ctx.arc(rootPt[0], rootPt[1], 0.0046 * S, 0, twoPi);
      ctx.fill();
      ctx.stroke();

      const padLit = localCharge > 0.85;
      ctx.fillStyle = padLit ? colChartreuse : colPanelFill;
      ctx.strokeStyle = padLit ? colPaleLime : colMint;
      ctx.lineWidth = Math.max(1.3, S * 0.0018);
      ctx.beginPath();
      ctx.arc(tipPt[0], tipPt[1], 0.0068 * S, 0, twoPi);
      ctx.fill();
      ctx.stroke();
    }
    ctx.restore();
  };

  drawHemisphere(-1);
  drawHemisphere(1);

  // Two tiny corpus callosum horizontal bridge pins inside center gap (strictly neat & non-overlapping)
  for (const by of [-0.036 * S, 0.024 * S]) {
    roundRectPath(-0.007 * S, by - 0.0025 * S, 0.014 * S, 0.005 * S, 0.002 * S);
    ctx.fillStyle = synapseCharge > 0.3 ? colChartreuse : 'rgba(74, 222, 128, 0.45)';
    ctx.fill();
  }
  ctx.restore();

  // =========================================================================
  // 7. BASE PEDESTAL PILL (Clear Gap Below Orbit Ring)
  // =========================================================================
  roundRectPath(cx - 0.135 * S, pedY, 0.270 * S, 0.014 * S, 0.007 * S);
  ctx.fillStyle = colPanelFill;
  ctx.fill();
  ctx.strokeStyle = colBorderMuted;
  ctx.lineWidth = lw * 0.85;
  ctx.stroke();

  const pedFillW = (0.270 * S - 0.016 * S) * (0.22 + 0.78 * ledgerProcess);
  roundRectPath(cx - pedFillW * 0.5, pedY + 0.004 * S, pedFillW, 0.006 * S, 0.003 * S);
  ctx.fillStyle = colMint;
  ctx.fill();

  // =========================================================================
  // 8. HORIZONTAL CONDUITS (Clean Separation Outer Side of Orbit Ring -> Cards)
  // =========================================================================
  const drawConduit = (innerX, outerX, y, outDir) => {
    const r = 0.0060 * S;
    const minX = Math.min(innerX, outerX);
    const maxX = Math.max(innerX, outerX);

    ctx.strokeStyle = colMint;
    ctx.lineWidth = Math.max(1.4, S * 0.0019);
    ctx.beginPath();
    ctx.arc(minX, y, r, 0, twoPi);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(maxX, y, r, 0, twoPi);
    ctx.stroke();

    const lx1 = minX + r + 0.004 * S;
    const lx2 = maxX - r - 0.004 * S;
    ctx.strokeStyle = 'rgba(74, 222, 128, 0.32)';
    ctx.lineWidth = Math.max(1.4, S * 0.002);
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(lx1, y);
    ctx.lineTo(lx2, y);
    ctx.stroke();

    const p = (loopNorm * 4) % 1;
    const dir = loopT < 14.5 ? outDir : -outDir;
    const px = dir > 0 ? lerp(lx1 + 0.008 * S, lx2 - 0.008 * S, p) : lerp(lx2 - 0.008 * S, lx1 + 0.008 * S, p);
    const seg = 0.009 * S;
    ctx.strokeStyle = colChartreuse;
    ctx.lineWidth = Math.max(2, S * 0.0030);
    ctx.beginPath();
    ctx.moveTo(px - seg, y);
    ctx.lineTo(px + seg, y);
    ctx.stroke();
  };

  drawConduit(conduitLeftStart, conduitLeftEnd, conduitY, -1);
  drawConduit(conduitRightStart, conduitRightEnd, conduitY, 1);

  // =========================================================================
  // 9. LEFT CARD: AI PORTFOLIO PIE / DONUT BREAKDOWN
  // =========================================================================
  roundRectPath(leftCardX, cardTopY, cardW, cardH, 0.022 * S);
  ctx.fillStyle = colPanelFill;
  ctx.fill();
  ctx.strokeStyle = colBorderMuted;
  ctx.lineWidth = Math.max(1.4, S * 0.0018);
  ctx.stroke();

  const pad = 0.024 * S;
  const lcInX = leftCardX + pad;
  const lcInW = cardW - pad * 2;
  const hdrY = cardTopY + pad;

  // Header Badge + Bars
  ctx.strokeStyle = colChartreuse;
  ctx.lineWidth = Math.max(1.3, S * 0.0018);
  ctx.beginPath();
  ctx.arc(lcInX + 0.018 * S, hdrY + 0.018 * S, 0.018 * S, 0, twoPi);
  ctx.stroke();
  ctx.fillStyle = colChartreuse;
  ctx.beginPath();
  ctx.moveTo(lcInX + 0.018 * S, hdrY + 0.018 * S);
  ctx.arc(lcInX + 0.018 * S, hdrY + 0.018 * S, 0.011 * S, -Math.PI * 0.5, Math.PI * 0.1);
  ctx.closePath();
  ctx.fill();

  roundRectPath(lcInX + 0.048 * S, hdrY + 0.007 * S, lcInW - 0.048 * S, 0.0065 * S, 0.0032 * S);
  ctx.fillStyle = colPaleLime;
  ctx.fill();
  roundRectPath(lcInX + 0.048 * S, hdrY + 0.021 * S, (lcInW - 0.048 * S) * 0.62, 0.0055 * S, 0.0028 * S);
  ctx.fillStyle = 'rgba(74, 222, 128, 0.45)';
  ctx.fill();

  // Middle Segmented Donut Chart (Zero Overlapping Slices!)
  const pieCx = leftCardX + cardW * 0.5;
  const pieCy = cardTopY + 0.165 * S;
  const pieR = 0.056 * S;
  const pieThick = 0.019 * S;

  // Recessed dark donut background track
  ctx.strokeStyle = '#040B06';
  ctx.lineWidth = pieThick;
  ctx.beginPath();
  ctx.arc(pieCx, pieCy, pieR, 0, twoPi);
  ctx.stroke();

  // 3 cleanly separated colored donut sectors expanding proportionally with ledgerProcess
  const gapAng = 0.16; // Clear dark visual gap between slices
  const s1Span = lerp(0.85, 2.38, ledgerProcess);
  const s2Span = lerp(0.62, 1.72, ledgerProcess);
  const s3Span = lerp(0.45, 1.48, ledgerProcess);
  const spans = [s1Span, s2Span, s3Span];
  const pieCols = [colChartreuse, colMint, colTeal];

  let curAng = -Math.PI * 0.5 + loopNorm * twoPi; // Subtle seamless 1-turn rotation synced to 20s
  ctx.lineCap = 'butt';
  for (let sIdx = 0; sIdx < 3; sIdx++) {
    const a0 = curAng + gapAng * 0.5;
    const a1 = a0 + spans[sIdx];
    ctx.strokeStyle = pieCols[sIdx];
    ctx.lineWidth = pieThick;
    ctx.beginPath();
    ctx.arc(pieCx, pieCy, pieR, a0, a1);
    ctx.stroke();
    curAng = a1 + gapAng * 0.5;
  }

  // Center core diamond node inside donut hole
  const coreDr = 0.015 * S * (0.85 + 0.20 * peakInsight);
  ctx.fillStyle = peakInsight > 0.35 ? colPaleLime : colMint;
  ctx.beginPath();
  ctx.moveTo(pieCx, pieCy - coreDr);
  ctx.lineTo(pieCx + coreDr, pieCy);
  ctx.lineTo(pieCx, pieCy + coreDr);
  ctx.lineTo(pieCx - coreDr, pieCy);
  ctx.closePath();
  ctx.fill();

  // Left Card Divider & 3 Equal-Spaced Legend Pills
  const divY = cardTopY + cardH - 0.072 * S;
  ctx.strokeStyle = 'rgba(74, 222, 128, 0.22)';
  ctx.lineWidth = Math.max(1, S * 0.0013);
  ctx.beginPath();
  ctx.moveTo(lcInX, divY);
  ctx.lineTo(lcInX + lcInW, divY);
  ctx.stroke();

  const legY = divY + 0.028 * S;
  const colW = lcInW / 3;
  for (let k = 0; k < 3; k++) {
    const lx = lcInX + k * colW + 0.008 * S;
    ctx.fillStyle = pieCols[k];
    ctx.beginPath();
    ctx.arc(lx, legY, 0.005 * S, 0, twoPi);
    ctx.fill();

    roundRectPath(lx + 0.010 * S, legY - 0.003 * S, colW - 0.022 * S, 0.006 * S, 0.003 * S);
    ctx.fillStyle = 'rgba(236, 252, 203, 0.55)';
    ctx.fill();
  }

  // =========================================================================
  // 10. RIGHT CARD: AUTOMATED SMART LEDGER BALANCE BARS
  // =========================================================================
  roundRectPath(rightCardX, cardTopY, cardW, cardH, 0.022 * S);
  ctx.fillStyle = colPanelFill;
  ctx.fill();
  ctx.strokeStyle = colBorderMuted;
  ctx.lineWidth = Math.max(1.4, S * 0.0018);
  ctx.stroke();

  const rcInX = rightCardX + pad;
  // Header Square Ledger Badge + Bars
  roundRectPath(rcInX, hdrY, 0.036 * S, 0.036 * S, 0.009 * S);
  ctx.fillStyle = '#040B06';
  ctx.fill();
  ctx.strokeStyle = colMint;
  ctx.lineWidth = Math.max(1.3, S * 0.0018);
  ctx.stroke();
  for (let lb = 0; lb < 3; lb++) {
    roundRectPath(rcInX + 0.008 * S, hdrY + 0.009 * S + lb * 0.0075 * S, 0.020 * S, 0.0038 * S, 0.0019 * S);
    ctx.fillStyle = lb === 0 ? colChartreuse : colTeal;
    ctx.fill();
  }

  roundRectPath(rcInX + 0.048 * S, hdrY + 0.007 * S, lcInW - 0.048 * S, 0.0065 * S, 0.0032 * S);
  ctx.fillStyle = colPaleLime;
  ctx.fill();
  roundRectPath(rcInX + 0.048 * S, hdrY + 0.021 * S, (lcInW - 0.048 * S) * 0.62, 0.0055 * S, 0.0028 * S);
  ctx.fillStyle = 'rgba(45, 212, 191, 0.45)';
  ctx.fill();

  // Middle 3 Balance Verification Rows (Staggered clean verification fills)
  const rowCols = [colChartreuse, colMint, colTeal];
  for (let r = 0; r < 3; r++) {
    const ry = cardTopY + 0.095 * S + r * 0.056 * S;
    const rh = 0.040 * S;
    roundRectPath(rcInX, ry, lcInW, rh, 0.011 * S);
    ctx.fillStyle = '#040B06';
    ctx.fill();
    ctx.strokeStyle = 'rgba(74, 222, 128, 0.16)';
    ctx.lineWidth = Math.max(1, S * 0.0012);
    ctx.stroke();

    const rowStagger = clamp01((ledgerProcess - r * 0.18) / (1 - r * 0.18));
    const fillRatio = 0.22 + 0.78 * rowStagger;
    const verified = rowStagger >= 0.85;

    // Status Circle Left
    const dotCx = rcInX + 0.018 * S;
    const dotCy = ry + rh * 0.5;
    ctx.fillStyle = verified ? rowCols[r] : colPanelFill;
    ctx.strokeStyle = verified ? colPaleLime : 'rgba(74, 222, 128, 0.40)';
    ctx.lineWidth = Math.max(1.2, S * 0.0016);
    ctx.beginPath();
    ctx.arc(dotCx, dotCy, 0.009 * S, 0, twoPi);
    ctx.fill();
    ctx.stroke();

    // Inner checkmark stroke when verified
    if (verified) {
      ctx.strokeStyle = '#040B06';
      ctx.lineWidth = Math.max(1.4, S * 0.0019);
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.beginPath();
      ctx.moveTo(dotCx - 0.004 * S, dotCy + 0.0005 * S);
      ctx.lineTo(dotCx - 0.001 * S, dotCy + 0.0038 * S);
      ctx.lineTo(dotCx + 0.0045 * S, dotCy - 0.0035 * S);
      ctx.stroke();
    }

    // Balance Bar Track + Active Bar Fill
    const barTrackX = rcInX + 0.036 * S;
    const barTrackW = lcInW - 0.048 * S;
    const barY = ry + rh * 0.5 - 0.006 * S;
    roundRectPath(barTrackX, barY, barTrackW, 0.012 * S, 0.006 * S);
    ctx.fillStyle = '#0A1C10';
    ctx.fill();

    roundRectPath(barTrackX, barY, Math.max(0.014 * S, barTrackW * fillRatio), 0.012 * S, 0.006 * S);
    ctx.fillStyle = rowCols[r];
    ctx.fill();
  }

  // Right Card Divider & Master Sync Progress Capsule
  ctx.strokeStyle = 'rgba(74, 222, 128, 0.22)';
  ctx.lineWidth = Math.max(1, S * 0.0013);
  ctx.beginPath();
  ctx.moveTo(rcInX, divY);
  ctx.lineTo(rcInX + lcInW, divY);
  ctx.stroke();

  roundRectPath(rcInX, divY + 0.022 * S, lcInW, 0.016 * S, 0.008 * S);
  ctx.fillStyle = '#040B06';
  ctx.fill();
  roundRectPath(rcInX, divY + 0.022 * S, Math.max(0.020 * S, lcInW * (0.20 + 0.80 * ledgerProcess)), 0.016 * S, 0.008 * S);
  ctx.fillStyle = peakInsight > 0.3 ? colChartreuse : colMint;
  ctx.fill();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const S = minSide;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const easeInOutCubic = (x) => {
    const v = clamp01(x);
    return v < 0.5 ? 4 * v * v * v : 1 - Math.pow(-2 * v + 2, 3) / 2;
  };
  const easeOutCubic = (x) => {
    const v = clamp01(x);
    return 1 - Math.pow(1 - v, 3);
  };
  const easeInOutSine = (x) => {
    const v = clamp01(x);
    return -(Math.cos(Math.PI * v) - 1) * 0.5;
  };
  const lerp = (a, b, k) => a + (b - a) * k;

  const windowRamp = (val, inStart, inEnd, outStart, outEnd) => {
    if (val <= inStart || val >= outEnd) return 0;
    if (val < inEnd) return easeInOutCubic((val - inStart) / (inEnd - inStart));
    if (val > outStart) return 1 - easeInOutCubic((val - outStart) / (outEnd - outStart));
    return 1;
  };

  const roundRectPath = (x, y, w, h, r) => {
    const rad = Math.max(0, Math.min(r, w * 0.5, h * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  };

  // 1. Clean Modern Dark Aesthetic Gradient Background (Deep Burgundy-Charcoal, ZERO glow, ZERO borders)
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, '#0E0409');
  bgGrad.addColorStop(0.52, '#1A0812');
  bgGrad.addColorStop(1, '#260D1B');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // 2. Seamless Timeline Parameters from t, loopT, currentScene, sceneProgress
  const scenePos = currentScene + sceneProgress; // Continuous [0, 4)
  const loopNorm = (scenePos * sceneDuration) / duration; // [0, 1)
  const twoPi = Math.PI * 2;
  const ambientBeat = 0.5 - 0.5 * Math.cos(loopNorm * twoPi * 4);
  const wavePhase = loopNorm * twoPi * 8;

  // Funnel intake surge: gentle idle 0.25 at loop boundary, rising cleanly through Scene 0-1
  const intakeBoost = windowRamp(loopT, 0.2, 3.2, 11.5, 16.5);
  const intakeActivity = 0.25 + 0.75 * intakeBoost;

  // Analytical seamless rotor angle (5 integer revolutions with peak velocity during Scene 1)
  const peakU = 0.375;
  const filterRotorAngle =
    twoPi *
    (5.0 * loopNorm -
      (1.8 / twoPi) * (Math.sin(twoPi * (loopNorm - peakU)) - Math.sin(-twoPi * peakU)));

  // Lower tank fill level: 0.18 baseline at t=0 -> climbs in Scene 1 & 2 -> peaks at 0.86 -> drains smoothly in Scene 3 back to 0.18
  let fillLevel = 0.18;
  if (loopT < 3.0) {
    fillLevel = 0.18 + 0.04 * easeInOutCubic(loopT / 3.0);
  } else if (loopT < 12.2) {
    fillLevel = 0.22 + 0.64 * easeInOutCubic((loopT - 3.0) / 9.2);
  } else if (loopT < 14.8) {
    fillLevel = 0.86;
  } else if (loopT < 19.4) {
    fillLevel = 0.86 - 0.68 * easeInOutCubic((loopT - 14.8) / 4.6);
  } else {
    fillLevel = 0.18;
  }

  // Drain valve opening cleanly during Scene 3 release
  const valveOpen = windowRamp(loopT, 14.4, 15.6, 18.8, 19.7);

  // Metric illumination envelope synchronized with profit level
  const metricNorm = clamp01((fillLevel - 0.18) / (0.86 - 0.18));
  const peakCelebrate = windowRamp(loopT, 10.5, 12.2, 14.6, 16.2);

  // 3. Spatial Layout Coordinates (Strict Non-Overlapping Zones)
  const lw = Math.max(1.5, S * 0.0022);
  const funnelTopY = cy - 0.195 * S;
  const funnelRimH = 0.024 * S;
  const funnelRimW = 0.30 * S;
  const chamberTopY = funnelTopY + funnelRimH;
  const chamberTopHalfW = 0.128 * S;
  const chamberBotY = cy - 0.015 * S;
  const chamberBotHalfW = 0.032 * S;

  const nozzleTopY = chamberBotY;
  const nozzleBotY = cy + 0.040 * S; // Clear 0.025*S air gap above lower vessel

  const tankX = cx - 0.12 * S;
  const tankY = cy + 0.065 * S;
  const tankW = 0.24 * S;
  const tankH = 0.188 * S;
  const tankR = 0.026 * S;
  const tankBotY = tankY + tankH;

  const drainEndY = tankBotY + 0.028 * S;
  const pedY = cy + 0.306 * S; // Clean 0.025*S gap below drain spout

  // Side micro-scales flanking collector (centered vertically with collector tank)
  const sideScaleW = 0.018 * S;
  const leftScaleX = tankX - 0.022 * S - sideScaleW;
  const rightScaleX = tankX + tankW + 0.022 * S;

  // Flanking Dashboard Cards
  const cardW = 0.25 * S;
  const cardH = 0.35 * S;
  const cardTopY = cy - cardH * 0.5;
  const leftCardX = cx - 0.59 * S;
  const rightCardX = cx + 0.34 * S;

  // Horizontal Conduit coordinates (strict air gaps on both inner and outer ends)
  const conduitLeftStart = leftCardX + cardW + 0.028 * S; // cx - 0.312*S
  const conduitLeftEnd = cx - 0.185 * S;
  const conduitRightStart = cx + 0.185 * S;
  const conduitRightEnd = rightCardX - 0.028 * S; // cx + 0.312*S
  const conduitY = cy + 0.02 * S;

  // Palette Constants
  const colMagenta = '#EC4899';
  const colNeonPink = '#F472B6';
  const colDeepBerry = '#9D174D';
  const colPeach = '#FDBA74';
  const colCream = '#FCE7F3';
  const colBorderMuted = 'rgba(244, 114, 182, 0.28)';
  const colPanelFill = '#14060E';

  // Helper: 4 crisp micro-icons for Intake Lanes
  const drawLaneIcon = (kind, x, y, r, alpha) => {
    if (alpha <= 0.01 || r <= 0.5) return;
    ctx.save();
    ctx.translate(x, y);
    ctx.globalAlpha = alpha;
    if (kind === 0) {
      // Price / Discount Tag
      ctx.fillStyle = '#2A0E1D';
      ctx.strokeStyle = colNeonPink;
      ctx.lineWidth = Math.max(1.2, S * 0.002);
      ctx.beginPath();
      ctx.moveTo(-r * 0.85, -r * 0.55);
      ctx.lineTo(r * 0.25, -r * 0.55);
      ctx.lineTo(r * 0.92, 0);
      ctx.lineTo(r * 0.25, r * 0.55);
      ctx.lineTo(-r * 0.85, r * 0.55);
      ctx.closePath();
      ctx.fill();
      ctx.stroke();

      ctx.fillStyle = colPeach;
      ctx.beginPath();
      ctx.arc(-r * 0.42, 0, r * 0.17, 0, twoPi);
      ctx.fill();
    } else if (kind === 1) {
      // E-Commerce Parcel Box
      ctx.fillStyle = '#2A0E1D';
      ctx.strokeStyle = colPeach;
      ctx.lineWidth = Math.max(1.2, S * 0.002);
      roundRectPath(-r * 0.72, -r * 0.72, r * 1.44, r * 1.44, r * 0.25);
      ctx.fill();
      ctx.stroke();

      ctx.fillStyle = colMagenta;
      roundRectPath(-r * 0.22, -r * 0.72, r * 0.44, r * 0.48, r * 0.06);
      ctx.fill();
    } else if (kind === 2) {
      // Shopping Tote Bag
      ctx.fillStyle = '#2A0E1D';
      ctx.strokeStyle = colNeonPink;
      ctx.lineWidth = Math.max(1.2, S * 0.002);
      ctx.beginPath();
      ctx.arc(0, -r * 0.36, r * 0.34, Math.PI, 0, false);
      ctx.stroke();

      roundRectPath(-r * 0.72, -r * 0.32, r * 1.44, r * 1.05, r * 0.2);
      ctx.fill();
      ctx.stroke();

      ctx.fillStyle = colCream;
      ctx.beginPath();
      ctx.arc(-r * 0.28, -r * 0.1, r * 0.09, 0, twoPi);
      ctx.arc(r * 0.28, -r * 0.1, r * 0.09, 0, twoPi);
      ctx.fill();
    } else {
      // Click / Demand Diamond Spark
      ctx.fillStyle = '#2A0E1D';
      ctx.strokeStyle = colCream;
      ctx.lineWidth = Math.max(1.2, S * 0.002);
      ctx.beginPath();
      ctx.moveTo(0, -r * 0.9);
      ctx.lineTo(r * 0.72, 0);
      ctx.lineTo(0, r * 0.9);
      ctx.lineTo(-r * 0.72, 0);
      ctx.closePath();
      ctx.fill();
      ctx.stroke();

      ctx.fillStyle = colPeach;
      ctx.beginPath();
      ctx.arc(0, 0, r * 0.22, 0, twoPi);
      ctx.fill();
    }
    ctx.restore();
  };

  // =========================================================================
  // 4. TOP CONVERGING INTAKE LANES & MICRO-ICONS (Strict Separated Corridors)
  // =========================================================================
  const laneTopX = [-0.145 * S, -0.048 * S, 0.048 * S, 0.145 * S];
  const laneBotX = [-0.082 * S, -0.027 * S, 0.027 * S, 0.082 * S];
  const laneStartY = cy - 0.365 * S;
  const laneEndY = funnelTopY - 0.004 * S;

  for (let i = 0; i < 4; i++) {
    const sx = cx + laneTopX[i];
    const ex = cx + laneBotX[i];
    const cpY1 = lerp(laneStartY, laneEndY, 0.45);
    const cpY2 = lerp(laneStartY, laneEndY, 0.75);

    // Subtle track guide line
    ctx.save();
    ctx.strokeStyle = 'rgba(244, 114, 182, 0.18)';
    ctx.lineWidth = Math.max(1, S * 0.0014);
    ctx.setLineDash([S * 0.005, S * 0.006]);
    ctx.beginPath();
    ctx.moveTo(sx, laneStartY);
    ctx.bezierCurveTo(sx, cpY1, ex, cpY2, ex, laneEndY);
    ctx.stroke();
    ctx.restore();

    // Flowing micro-icon descending along lane (6 integer cycles over 20s -> seamless at loopT=0 & 20)
    const phase = (loopNorm * 6 + i * 0.25) % 1;
    const pEase = phase;
    const inv = 1 - pEase;
    const ix =
      inv * inv * inv * sx +
      3 * inv * inv * pEase * sx +
      3 * inv * pEase * pEase * ex +
      pEase * pEase * pEase * ex;
    const iy =
      inv * inv * inv * laneStartY +
      3 * inv * inv * pEase * cpY1 +
      3 * inv * pEase * pEase * cpY2 +
      pEase * pEase * pEase * laneEndY;

    const fadeIn = easeOutCubic(clamp01(phase / 0.18));
    const absorbOut = 1 - easeInOutCubic(clamp01((phase - 0.80) / 0.20));
    const iconScale = (0.78 + 0.22 * intakeActivity) * fadeIn * (0.35 + 0.65 * absorbOut);
    const iconAlpha = clamp01(fadeIn * absorbOut * (0.45 + 0.55 * intakeActivity));
    drawLaneIcon(i, ix, iy, 0.019 * S * iconScale, iconAlpha);
  }

  // =========================================================================
  // 5. HERO FUNNEL BODY (Conical Chamber + Clipped Internal Swirl & Rotor)
  // =========================================================================
  const drawFunnelChamberPath = (inset) => {
    const ty = chamberTopY + inset;
    const by = chamberBotY - inset * 0.35;
    const tw = chamberTopHalfW - inset;
    const bw = chamberBotHalfW - inset * 0.5;
    ctx.beginPath();
    ctx.moveTo(cx - tw, ty);
    ctx.lineTo(cx + tw, ty);
    ctx.bezierCurveTo(
      cx + tw * 0.88,
      lerp(ty, by, 0.55),
      cx + bw * 1.15,
      lerp(ty, by, 0.72),
      cx + bw,
      by
    );
    ctx.lineTo(cx - bw, by);
    ctx.bezierCurveTo(
      cx - bw * 1.15,
      lerp(ty, by, 0.72),
      cx - tw * 0.88,
      lerp(ty, by, 0.55),
      cx - tw,
      ty
    );
    ctx.closePath();
  };

  // Dark translucent glass fill of funnel
  drawFunnelChamberPath(0);
  const funnelBgGrad = ctx.createLinearGradient(cx - chamberTopHalfW, chamberTopY, cx + chamberTopHalfW, chamberBotY);
  funnelBgGrad.addColorStop(0, '#1C0914');
  funnelBgGrad.addColorStop(0.5, '#12050C');
  funnelBgGrad.addColorStop(1, '#240B19');
  ctx.fillStyle = funnelBgGrad;
  ctx.fill();

  // Clip interior of funnel for liquid vortex & agitator blades
  ctx.save();
  drawFunnelChamberPath(S * 0.0028);
  ctx.clip();

  // Funnel internal swirling profit essence pool in lower half of cone
  const poolBaseY = lerp(chamberTopY, chamberBotY, 0.56 - 0.12 * intakeActivity);
  ctx.beginPath();
  ctx.moveTo(cx - chamberTopHalfW, chamberBotY + S * 0.01);
  for (let xOff = -chamberTopHalfW; xOff <= chamberTopHalfW + 0.001; xOff += 0.012 * S) {
    const wy =
      poolBaseY +
      Math.sin((xOff / S) * 34 + wavePhase) * (0.0045 * S) +
      Math.cos((xOff / S) * 20 - wavePhase * 0.5) * (0.0025 * S);
    ctx.lineTo(cx + xOff, wy);
  }
  ctx.lineTo(cx + chamberTopHalfW, chamberBotY + S * 0.01);
  ctx.closePath();
  const coneLiqGrad = ctx.createLinearGradient(cx, poolBaseY, cx, chamberBotY);
  coneLiqGrad.addColorStop(0, 'rgba(244, 114, 182, 0.72)');
  coneLiqGrad.addColorStop(0.55, 'rgba(236, 72, 153, 0.88)');
  coneLiqGrad.addColorStop(1, '#9D174D');
  ctx.fillStyle = coneLiqGrad;
  ctx.fill();

  // Specular highlights along left inner funnel bevel
  ctx.strokeStyle = 'rgba(252, 231, 243, 0.22)';
  ctx.lineWidth = Math.max(1.5, S * 0.003);
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(cx - chamberTopHalfW * 0.82, chamberTopY + 0.012 * S);
  ctx.quadraticCurveTo(
    cx - chamberTopHalfW * 0.62,
    lerp(chamberTopY, chamberBotY, 0.45),
    cx - chamberBotHalfW * 0.76,
    chamberBotY - 0.014 * S
  );
  ctx.stroke();
  ctx.restore();

  // Funnel outer wall sharp crisp outline
  drawFunnelChamberPath(0);
  ctx.strokeStyle = colNeonPink;
  ctx.lineWidth = lw;
  ctx.stroke();

  // Concentric Mechanical Filter Hub + 4 Curved Rotor Blades inside chamber
  const rotorY = cy - 0.105 * S;
  const rotorR = 0.042 * S; // Clear inside ~0.09*S chamber half-width
  ctx.save();
  ctx.translate(cx, rotorY);

  // Stationary outer guide ring around rotor
  ctx.strokeStyle = 'rgba(253, 186, 116, 0.35)';
  ctx.lineWidth = Math.max(1.2, S * 0.0018);
  ctx.beginPath();
  ctx.arc(0, 0, rotorR * 1.16, 0, twoPi);
  ctx.stroke();

  // Rotating 4 precision vanes
  ctx.rotate(filterRotorAngle);
  for (let b = 0; b < 4; b++) {
    ctx.save();
    ctx.rotate((b * twoPi) / 4);
    ctx.fillStyle = b % 2 === 0 ? colPeach : colCream;
    ctx.beginPath();
    ctx.moveTo(0, -0.004 * S);
    ctx.quadraticCurveTo(rotorR * 0.55, -0.012 * S, rotorR, 0);
    ctx.quadraticCurveTo(rotorR * 0.55, 0.007 * S, 0, 0.004 * S);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }
  // Center hub bearing
  ctx.fillStyle = colPanelFill;
  ctx.strokeStyle = colPeach;
  ctx.lineWidth = lw;
  ctx.beginPath();
  ctx.arc(0, 0, 0.012 * S, 0, twoPi);
  ctx.fill();
  ctx.stroke();

  ctx.fillStyle = colMagenta;
  ctx.beginPath();
  ctx.arc(0, 0, 0.005 * S, 0, twoPi);
  ctx.fill();
  ctx.restore();

  // Top Metallic Intake Collar Rim (drawn cleanly atop funnel mouth)
  const rimGrad = ctx.createLinearGradient(cx - funnelRimW * 0.5, funnelTopY, cx + funnelRimW * 0.5, funnelTopY);
  rimGrad.addColorStop(0, '#9D174D');
  rimGrad.addColorStop(0.5, '#F472B6');
  rimGrad.addColorStop(1, '#9D174D');
  roundRectPath(cx - funnelRimW * 0.5, funnelTopY, funnelRimW, funnelRimH, funnelRimH * 0.5);
  ctx.fillStyle = colPanelFill;
  ctx.fill();
  ctx.strokeStyle = rimGrad;
  ctx.lineWidth = lw * 1.1;
  ctx.stroke();

  // Active intake bar inside collar
  const intakeBarW = (funnelRimW - 0.04 * S) * (0.45 + 0.55 * intakeActivity);
  roundRectPath(cx - intakeBarW * 0.5, funnelTopY + funnelRimH * 0.34, intakeBarW, funnelRimH * 0.32, funnelRimH * 0.16);
  ctx.fillStyle = colPeach;
  ctx.fill();

  // =========================================================================
  // 6. THROAT DROPPER NECK & CONTROL GATE VALVE + FALLING DROPLETS
  // =========================================================================
  const neckW = chamberBotHalfW * 2;
  const neckH = nozzleBotY - nozzleTopY;
  roundRectPath(cx - neckW * 0.42, nozzleTopY, neckW * 0.84, neckH, S * 0.008);
  ctx.fillStyle = '#180811';
  ctx.fill();
  ctx.strokeStyle = colMagenta;
  ctx.lineWidth = lw;
  ctx.stroke();

  // Inner nozzle drip channel
  const channelW = 0.016 * S;
  ctx.fillStyle = 'rgba(236, 72, 153, 0.55)';
  roundRectPath(cx - channelW * 0.5, nozzleTopY + 0.003 * S, channelW, neckH - 0.006 * S, channelW * 0.4);
  ctx.fill();

  // Mechanical gate valve collar around throat midpoint
  const valveY = lerp(nozzleTopY, nozzleBotY, 0.46);
  const valveGateGap = lerp(0.004 * S, 0.016 * S, clamp01(intakeActivity + 0.2));
  ctx.fillStyle = colPeach;
  roundRectPath(cx - neckW * 0.55, valveY - 0.0045 * S, neckW * 0.55 - valveGateGap * 0.5, 0.009 * S, 0.004 * S);
  ctx.fill();
  roundRectPath(cx + valveGateGap * 0.5, valveY - 0.0045 * S, neckW * 0.55 - valveGateGap * 0.5, 0.009 * S, 0.004 * S);
  ctx.fill();

  // Falling glowing droplets through open air gap (nozzleBotY -> tank liquid surface)
  const liqSurfaceY = tankBotY - tankH * fillLevel;
  const dropCount = 3;
  for (let d = 0; d < dropCount; d++) {
    const dp = (loopNorm * 8 + d / dropCount) % 1;
    // Accelerating drop trajectory cleanly stopped inside vessel liquid surface
    const fallEase = dp * dp;
    const dropY = lerp(nozzleBotY + 0.004 * S, liqSurfaceY, fallEase);
    const dropScale = clamp01(dp < 0.15 ? dp / 0.15 : dp > 0.88 ? (1 - dp) / 0.12 : 1);
    const dropAlpha = dropScale * clamp01(0.55 + 0.45 * intakeActivity);
    if (dropAlpha > 0.02 && dropY <= liqSurfaceY + 0.004 * S) {
      const dr = 0.0068 * S * dropScale;
      ctx.save();
      ctx.globalAlpha = dropAlpha;
      ctx.fillStyle = d % 2 === 0 ? colNeonPink : colPeach;
      ctx.beginPath();
      ctx.moveTo(cx, dropY - dr * 1.45);
      ctx.quadraticCurveTo(cx + dr * 1.15, dropY + dr * 0.2, cx, dropY + dr);
      ctx.quadraticCurveTo(cx - dr * 1.15, dropY + dr * 0.2, cx, dropY - dr * 1.45);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }
  }

  // =========================================================================
  // 7. LOWER PROFIT COLLECTOR VESSEL (Clipped Fluid Wave + Bubbles + Specular)
  // =========================================================================
  roundRectPath(tankX, tankY, tankW, tankH, tankR);
  ctx.fillStyle = colPanelFill;
  ctx.fill();

  // Top vessel port collar (crisp entry lip right at tankY)
  roundRectPath(cx - 0.036 * S, tankY - 0.005 * S, 0.072 * S, 0.010 * S, 0.005 * S);
  ctx.fillStyle = '#2A0E1D';
  ctx.fill();
  ctx.strokeStyle = colNeonPink;
  ctx.lineWidth = lw;
  ctx.stroke();

  // Clip interior of collector vessel
  ctx.save();
  roundRectPath(tankX + S * 0.003, tankY + S * 0.003, tankW - S * 0.006, tankH - S * 0.006, tankR - S * 0.003);
  ctx.clip();

  // Multi-harmonic sinusoidal fluid column
  ctx.beginPath();
  ctx.moveTo(tankX, tankBotY + S * 0.01);
  for (let px = 0; px <= tankW + 1; px += Math.max(3, tankW * 0.04)) {
    const nx = px / tankW;
    const ripple =
      Math.sin(nx * Math.PI * 3 + wavePhase) * (0.0055 * S) +
      Math.cos(nx * Math.PI * 5 - wavePhase * 1.0) * (0.0028 * S);
    ctx.lineTo(tankX + px, liqSurfaceY + ripple);
  }
  ctx.lineTo(tankX + tankW, tankBotY + S * 0.01);
  ctx.closePath();

  const liqGrad = ctx.createLinearGradient(cx, liqSurfaceY, cx, tankBotY);
  liqGrad.addColorStop(0, colPeach);
  liqGrad.addColorStop(0.28, colNeonPink);
  liqGrad.addColorStop(0.7, colMagenta);
  liqGrad.addColorStop(1, colDeepBerry);
  ctx.fillStyle = liqGrad;
  ctx.fill();

  // Crisp meniscus highlight ribbon along liquid top
  ctx.strokeStyle = colCream;
  ctx.lineWidth = Math.max(1.2, S * 0.002);
  ctx.beginPath();
  for (let px = 0; px <= tankW + 1; px += Math.max(3, tankW * 0.04)) {
    const nx = px / tankW;
    const ripple =
      Math.sin(nx * Math.PI * 3 + wavePhase) * (0.0055 * S) +
      Math.cos(nx * Math.PI * 5 - wavePhase * 1.0) * (0.0028 * S);
    if (px === 0) ctx.moveTo(tankX + px, liqSurfaceY + ripple);
    else ctx.lineTo(tankX + px, liqSurfaceY + ripple);
  }
  ctx.stroke();

  // Rising bubbles strictly inside the liquid column
  const bubbleSeeds = [
    { xRatio: 0.22, speed: 4, phase: 0.0, rad: 0.0055 },
    { xRatio: 0.48, speed: 6, phase: 0.3, rad: 0.0042 },
    { xRatio: 0.67, speed: 5, phase: 0.55, rad: 0.0062 },
    { xRatio: 0.35, speed: 7, phase: 0.78, rad: 0.0038 },
    { xRatio: 0.80, speed: 4, phase: 0.15, rad: 0.0048 },
  ];
  for (let i = 0; i < bubbleSeeds.length; i++) {
    const bs = bubbleSeeds[i];
    const bp = (loopNorm * bs.speed + bs.phase) % 1;
    const by = lerp(tankBotY - 0.010 * S, liqSurfaceY + 0.012 * S, bp);
    if (by > liqSurfaceY + 0.008 * S) {
      const bx = tankX + tankW * bs.xRatio + Math.sin(bp * twoPi + i) * 0.006 * S;
      const bAlpha = Math.sin(bp * Math.PI) * 0.65;
      ctx.fillStyle = `rgba(252, 231, 243, ${bAlpha.toFixed(3)})`;
      ctx.beginPath();
      ctx.arc(bx, by, bs.rad * S, 0, twoPi);
      ctx.fill();
    }
  }

  // Left inner specular stripe
  ctx.fillStyle = 'rgba(255, 255, 255, 0.14)';
  roundRectPath(tankX + 0.014 * S, tankY + 0.018 * S, 0.010 * S, tankH - 0.036 * S, 0.005 * S);
  ctx.fill();
  ctx.restore();

  // Vessel Outer Sharp Frame
  roundRectPath(tankX, tankY, tankW, tankH, tankR);
  ctx.strokeStyle = colNeonPink;
  ctx.lineWidth = lw;
  ctx.stroke();

  // Clean Horizontal Tick Marks inside Vessel glass edge
  for (let tick = 1; tick <= 3; tick++) {
    const ty = tankBotY - (tankH * tick) / 4;
    ctx.strokeStyle = 'rgba(252, 231, 243, 0.25)';
    ctx.lineWidth = Math.max(1, S * 0.0014);
    ctx.beginPath();
    ctx.moveTo(tankX + 0.006 * S, ty);
    ctx.lineTo(tankX + 0.022 * S, ty);
    ctx.moveTo(tankX + tankW - 0.022 * S, ty);
    ctx.lineTo(tankX + tankW - 0.006 * S, ty);
    ctx.stroke();
  }

  // Bottom Drain Spout Assembly & Release Stream (Scene 3)
  roundRectPath(cx - 0.028 * S, tankBotY, 0.056 * S, 0.018 * S, 0.006 * S);
  ctx.fillStyle = '#1D0914';
  ctx.fill();
  ctx.strokeStyle = colMagenta;
  ctx.lineWidth = lw;
  ctx.stroke();

  if (valveOpen > 0.02) {
    const spoutStreamH = (drainEndY - (tankBotY + 0.018 * S)) * valveOpen;
    roundRectPath(cx - 0.007 * S, tankBotY + 0.018 * S, 0.014 * S, spoutStreamH, 0.005 * S);
    ctx.fillStyle = `rgba(253, 186, 116, ${(0.85 * valveOpen).toFixed(3)})`;
    ctx.fill();
  }

  // Clean Base Pedestal Pill (strict air gap below drain spout)
  roundRectPath(cx - 0.135 * S, pedY, 0.270 * S, 0.014 * S, 0.007 * S);
  ctx.fillStyle = '#14060E';
  ctx.fill();
  ctx.strokeStyle = colBorderMuted;
  ctx.lineWidth = lw * 0.85;
  ctx.stroke();

  const pedFillW = (0.270 * S - 0.016 * S) * (0.25 + 0.75 * metricNorm);
  roundRectPath(cx - pedFillW * 0.5, pedY + 0.004 * S, pedFillW, 0.006 * S, 0.003 * S);
  ctx.fillStyle = colNeonPink;
  ctx.fill();

  // =========================================================================
  // 8. SYMMETRIC SIDE VERTICAL SCALES (Flow Rate Left, Conversion % Right)
  // =========================================================================
  const drawSideMeter = (mx, ratio, fillStart, fillEnd) => {
    roundRectPath(mx, tankY + 0.01 * S, sideScaleW, tankH - 0.02 * S, sideScaleW * 0.5);
    ctx.fillStyle = colPanelFill;
    ctx.fill();
    ctx.strokeStyle = colBorderMuted;
    ctx.lineWidth = Math.max(1.2, S * 0.0016);
    ctx.stroke();

    const innerH = tankH - 0.032 * S;
    const fh = innerH * clamp01(ratio);
    if (fh > 1) {
      const fy = tankY + tankH - 0.016 * S - fh;
      const g = ctx.createLinearGradient(mx, fy + fh, mx, fy);
      g.addColorStop(0, fillStart);
      g.addColorStop(1, fillEnd);
      roundRectPath(mx + 0.004 * S, fy, sideScaleW - 0.008 * S, fh, (sideScaleW - 0.008 * S) * 0.5);
      ctx.fillStyle = g;
      ctx.fill();
    }
  };

  drawSideMeter(leftScaleX, 0.20 + 0.76 * intakeActivity, colDeepBerry, colNeonPink);
  drawSideMeter(rightScaleX, fillLevel, colMagenta, colPeach);

  // =========================================================================
  // 9. HORIZONTAL CONDUITS (Clean Separation & Synchronized Pulses)
  // =========================================================================
  const drawConduit = (x1, x2, y, pulseDir) => {
    const r = 0.0065 * S;
    // Left and right open terminal circles
    ctx.strokeStyle = colNeonPink;
    ctx.lineWidth = Math.max(1.5, S * 0.002);
    ctx.beginPath();
    ctx.arc(x1, y, r, 0, twoPi);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(x2, y, r, 0, twoPi);
    ctx.stroke();

    // Inner track line (doesn't pierce circles!)
    const lx1 = x1 + r + 0.004 * S;
    const lx2 = x2 - r - 0.004 * S;
    ctx.strokeStyle = 'rgba(244, 114, 182, 0.35)';
    ctx.lineWidth = Math.max(1.5, S * 0.0022);
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(lx1, y);
    ctx.lineTo(lx2, y);
    ctx.stroke();

    // Animated pulse capsule gliding cleanly inside [lx1..lx2]
    const p = (loopNorm * 4) % 1;
    const pos = pulseDir > 0 ? lerp(lx1 + 0.010 * S, lx2 - 0.010 * S, p) : lerp(lx2 - 0.010 * S, lx1 + 0.010 * S, p);
    const segHalf = 0.011 * S;
    ctx.strokeStyle = colPeach;
    ctx.lineWidth = Math.max(2, S * 0.0032);
    ctx.beginPath();
    ctx.moveTo(pos - segHalf, y);
    ctx.lineTo(pos + segHalf, y);
    ctx.stroke();
  };

  drawConduit(conduitLeftStart, conduitLeftEnd, conduitY, 1);
  drawConduit(conduitRightStart, conduitRightEnd, conduitY, 1);

  // =========================================================================
  // 10. FLANKING CARDS (Left: Funnel Stage Bars, Right: Conversion Gauge)
  // =========================================================================
  // Left Card
  roundRectPath(leftCardX, cardTopY, cardW, cardH, 0.022 * S);
  ctx.fillStyle = colPanelFill;
  ctx.fill();
  ctx.strokeStyle = colBorderMuted;
  ctx.lineWidth = Math.max(1.4, S * 0.0018);
  ctx.stroke();

  // Left Card Header
  const lcPad = 0.026 * S;
  const lcInX = leftCardX + lcPad;
  const lcInW = cardW - lcPad * 2;
  const lcHdrY = cardTopY + lcPad;
  // Circular funnel emblem badge
  ctx.strokeStyle = colNeonPink;
  ctx.lineWidth = Math.max(1.4, S * 0.002);
  ctx.beginPath();
  ctx.arc(lcInX + 0.020 * S, lcHdrY + 0.020 * S, 0.020 * S, 0, twoPi);
  ctx.stroke();
  ctx.fillStyle = colPeach;
  ctx.beginPath();
  ctx.moveTo(lcInX + 0.011 * S, lcHdrY + 0.013 * S);
  ctx.lineTo(lcInX + 0.029 * S, lcHdrY + 0.013 * S);
  ctx.lineTo(lcInX + 0.022 * S, lcHdrY + 0.022 * S);
  ctx.lineTo(lcInX + 0.022 * S, lcHdrY + 0.029 * S);
  ctx.lineTo(lcInX + 0.018 * S, lcHdrY + 0.029 * S);
  ctx.lineTo(lcInX + 0.018 * S, lcHdrY + 0.022 * S);
  ctx.closePath();
  ctx.fill();

  // Two aligned pill header lines
  roundRectPath(lcInX + 0.054 * S, lcHdrY + 0.008 * S, lcInW - 0.054 * S, 0.007 * S, 0.0035 * S);
  ctx.fillStyle = colCream;
  ctx.fill();
  roundRectPath(lcInX + 0.054 * S, lcHdrY + 0.024 * S, (lcInW - 0.054 * S) * 0.65, 0.006 * S, 0.003 * S);
  ctx.fillStyle = 'rgba(244, 114, 182, 0.45)';
  ctx.fill();

  // Left Card Middle: 3 Centered Tier Funnel Bars inside recessed dark tracks
  const tierWidths = [1.0, 0.74, 0.48];
  const tierFills = [
    0.35 + 0.65 * intakeActivity,
    0.22 + 0.78 * clamp01(intakeActivity * 0.6 + metricNorm * 0.4),
    0.16 + 0.84 * metricNorm,
  ];
  const tierColors = [colNeonPink, colMagenta, colPeach];
  for (let i = 0; i < 3; i++) {
    const ty = cardTopY + 0.105 * S + i * 0.052 * S;
    const tw = lcInW * tierWidths[i];
    const tx = leftCardX + (cardW - tw) * 0.5;
    roundRectPath(tx, ty, tw, 0.032 * S, 0.010 * S);
    ctx.fillStyle = '#0B0307';
    ctx.fill();
    ctx.strokeStyle = 'rgba(244, 114, 182, 0.16)';
    ctx.lineWidth = Math.max(1, S * 0.0012);
    ctx.stroke();

    const fw = Math.max(0.018 * S, (tw - 0.008 * S) * tierFills[i]);
    const fx = leftCardX + (cardW - fw) * 0.5;
    roundRectPath(fx, ty + 0.004 * S, fw, 0.024 * S, 0.007 * S);
    ctx.fillStyle = tierColors[i];
    ctx.fill();
  }

  // Left Card Divider & Footer Progress Capsule
  const lcDivY = cardTopY + cardH - 0.072 * S;
  ctx.strokeStyle = 'rgba(244, 114, 182, 0.22)';
  ctx.lineWidth = Math.max(1, S * 0.0013);
  ctx.beginPath();
  ctx.moveTo(lcInX, lcDivY);
  ctx.lineTo(lcInX + lcInW, lcDivY);
  ctx.stroke();

  roundRectPath(lcInX, lcDivY + 0.022 * S, lcInW, 0.016 * S, 0.008 * S);
  ctx.fillStyle = '#0B0307';
  ctx.fill();
  roundRectPath(lcInX, lcDivY + 0.022 * S, Math.max(0.020 * S, lcInW * (0.2 + 0.78 * metricNorm)), 0.016 * S, 0.008 * S);
  ctx.fillStyle = colNeonPink;
  ctx.fill();

  // Right Card
  roundRectPath(rightCardX, cardTopY, cardW, cardH, 0.022 * S);
  ctx.fillStyle = colPanelFill;
  ctx.fill();
  ctx.strokeStyle = colBorderMuted;
  ctx.lineWidth = Math.max(1.4, S * 0.0018);
  ctx.stroke();

  const rcInX = rightCardX + lcPad;
  const rcCx = rightCardX + cardW * 0.5;
  const ringCy = cardTopY + 0.115 * S;
  const ringR = 0.064 * S;

  // Radial Conversion Ring Track
  ctx.strokeStyle = '#0B0307';
  ctx.lineWidth = 0.014 * S;
  ctx.beginPath();
  ctx.arc(rcCx, ringCy, ringR, 0, twoPi);
  ctx.stroke();

  // Active Conversion Arc (0.18 -> 0.92 sweep)
  const arcRatio = 0.18 + 0.74 * metricNorm;
  const arcStart = -Math.PI * 0.5;
  const arcEnd = arcStart + twoPi * arcRatio;
  const arcGrad = ctx.createLinearGradient(rcCx - ringR, ringCy, rcCx + ringR, ringCy);
  arcGrad.addColorStop(0, colMagenta);
  arcGrad.addColorStop(0.5, colNeonPink);
  arcGrad.addColorStop(1, colPeach);
  ctx.strokeStyle = arcGrad;
  ctx.lineWidth = 0.014 * S;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.arc(rcCx, ringCy, ringR, arcStart, arcEnd);
  ctx.stroke();

  // Terminal pearl bead at arc tip
  ctx.fillStyle = colCream;
  ctx.beginPath();
  ctx.arc(rcCx + Math.cos(arcEnd) * ringR, ringCy + Math.sin(arcEnd) * ringR, 0.006 * S, 0, twoPi);
  ctx.fill();

  // Center Upward Growth Arrow Vector inside Ring
  const arrowScale = 0.90 + 0.14 * peakCelebrate + 0.04 * ambientBeat;
  ctx.save();
  ctx.translate(rcCx, ringCy);
  ctx.scale(arrowScale, arrowScale);
  ctx.fillStyle = metricNorm > 0.65 ? colPeach : colNeonPink;
  ctx.beginPath();
  ctx.moveTo(0, -0.026 * S);
  ctx.lineTo(0.021 * S, -0.002 * S);
  ctx.lineTo(0.008 * S, -0.002 * S);
  ctx.lineTo(0.008 * S, 0.024 * S);
  ctx.lineTo(-0.008 * S, 0.024 * S);
  ctx.lineTo(-0.008 * S, -0.002 * S);
  ctx.lineTo(-0.021 * S, -0.002 * S);
  ctx.closePath();
  ctx.fill();
  ctx.restore();

  // Right Card Divider & 4-Step Milestone Track
  ctx.strokeStyle = 'rgba(244, 114, 182, 0.22)';
  ctx.lineWidth = Math.max(1, S * 0.0013);
  ctx.beginPath();
  ctx.moveTo(rcInX, lcDivY);
  ctx.lineTo(rcInX + lcInW, lcDivY);
  ctx.stroke();

  const stepY = lcDivY + 0.030 * S;
  const stepSpan = lcInW - 0.032 * S;
  const stepStart = rcInX + 0.016 * S;
  const dotR = 0.009 * S;

  // Connecting spine behind/between milestone dots (broken cleanly around circles)
  for (let k = 0; k < 3; k++) {
    const xA = stepStart + (k * stepSpan) / 3 + dotR + 0.002 * S;
    const xB = stepStart + ((k + 1) * stepSpan) / 3 - dotR - 0.002 * S;
    const segActive = metricNorm >= (k + 1) * 0.25 ? 1 : 0;
    ctx.strokeStyle = segActive ? colPeach : 'rgba(244, 114, 182, 0.25)';
    ctx.lineWidth = Math.max(1.5, S * 0.0025);
    ctx.beginPath();
    ctx.moveTo(xA, stepY);
    ctx.lineTo(xB, stepY);
    ctx.stroke();
  }

  for (let k = 0; k < 4; k++) {
    const dx = stepStart + (k * stepSpan) / 3;
    const threshold = k * 0.25 + 0.04;
    const lit = metricNorm >= threshold;
    ctx.fillStyle = lit ? (k === 3 ? colPeach : colNeonPink) : colPanelFill;
    ctx.strokeStyle = lit ? colCream : 'rgba(244, 114, 182, 0.42)';
    ctx.lineWidth = Math.max(1.4, S * 0.002);
    ctx.beginPath();
    ctx.arc(dx, stepY, dotR, 0, twoPi);
    ctx.fill();
    ctx.stroke();
  }
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const S = minSide;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const easeInOutCubic = (x) => {
    const v = clamp01(x);
    return v < 0.5 ? 4 * v * v * v : 1 - Math.pow(-2 * v + 2, 3) / 2;
  };
  const easeOutCubic = (x) => {
    const v = clamp01(x);
    return 1 - Math.pow(1 - v, 3);
  };
  const easeInOutSine = (x) => {
    const v = clamp01(x);
    return -(Math.cos(Math.PI * v) - 1) * 0.5;
  };
  const lerp = (a, b, k) => a + (b - a) * k;

  const roundRectPath = (x, y, w, h, r) => {
    const rad = Math.max(0, Math.min(r, w * 0.5, h * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  };

  // 1. Clean Modern Dark Aesthetic Gradient Background (Deep Olive-Obsidian, Zero Glow, Zero Borders)
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, '#0D1108');
  bgGrad.addColorStop(0.5, '#161C0E');
  bgGrad.addColorStop(1, '#202814');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // 2. Global Seamless Motion Parameters Driven by t, loopT, currentScene, sceneProgress
  const loopNorm = loopT / duration;

  // Forward continuous clockwork: each 5s scene = 1 full minute turn & 1/4 hour turn
  const sceneEase = easeInOutSine(sceneProgress);
  const minuteAngle = (currentScene + sceneEase) * Math.PI * 2;
  const hourAngle = ((currentScene + sceneEase) / sceneCount) * Math.PI * 2;

  // Meshed internal gears: exact integer cycles (Gear A = +2 turns, Gear B = -3 turns over 20s)
  const gearAAngle = loopNorm * Math.PI * 2 * 2;
  const gearBAngle = -loopNorm * Math.PI * 2 * 3 + Math.PI / 8;

  // Quarter progression (0 -> 1.0 across t = 0..16.2s, smoothly eases back 1.0 -> 0 across 16.5..20s)
  let quarterTotal = 0;
  let bellPulse = 0;
  let conduitFlow = 0.35;

  if (currentScene < 3) {
    quarterTotal = (currentScene + easeInOutCubic(sceneProgress)) / 3.3;
    // Gentle quarter milestone chime peak near end of each quarter
    bellPulse = Math.pow(Math.max(0, Math.sin(sceneProgress * Math.PI)), 2) * 0.65;
    conduitFlow = 0.45 + 0.45 * Math.sin(sceneProgress * Math.PI);
  } else {
    // Scene 3 (15-20s): Completes final quarter to 1.0 by p=0.25, chimes cleanly, then smoothly resets to 0
    if (sceneProgress < 0.28) {
      const finK = easeInOutCubic(sceneProgress / 0.28);
      quarterTotal = lerp(3 / 3.3, 1.0, finK);
      bellPulse = Math.sin((sceneProgress / 0.28) * Math.PI);
      conduitFlow = 0.92;
    } else {
      const resK = easeInOutCubic((sceneProgress - 0.28) / 0.70);
      quarterTotal = lerp(1.0, 0.0, resK);
      bellPulse = 0;
      conduitFlow = lerp(0.92, 0.35, resK);
    }
  }

  // 3. Grounding Pedestal Pill Beneath Clock Feet
  ctx.save();
  const pedW = 0.38 * S;
  const pedH = 0.018 * S;
  const pedY = cy + 0.304 * S;
  roundRectPath(cx - pedW * 0.5, pedY, pedW, pedH, pedH * 0.5);
  ctx.fillStyle = '#090C06';
  ctx.fill();
  ctx.lineWidth = Math.max(1, 0.0022 * S);
  ctx.strokeStyle = '#4B5723';
  ctx.stroke();
  ctx.restore();

  // 4. Precision Conduit Buses (Strictly Clear of Clock Outer Ring [+/-0.252*S] & Cards [+/-0.445*S])
  const drawConduit = (xStart, xEnd, active) => {
    ctx.save();
    const yRail = cy;
    const termR = 0.0075 * S;
    const railH = 0.009 * S;
    const padX = 0.011 * S;

    roundRectPath(xStart, yRail - railH * 0.5, xEnd - xStart, railH, railH * 0.5);
    ctx.fillStyle = '#11160B';
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.002 * S);
    ctx.strokeStyle = '#4B5723';
    ctx.stroke();

    [xStart, xEnd].forEach((tx) => {
      ctx.beginPath();
      ctx.arc(tx, yRail, termR, 0, Math.PI * 2);
      ctx.fillStyle = '#1C2412';
      ctx.fill();
      ctx.lineWidth = Math.max(1, 0.0024 * S);
      ctx.strokeStyle = active > 0.4 ? '#FBBF24' : '#657530';
      ctx.stroke();
    });

    const innerStart = xStart + padX;
    const innerEnd = xEnd - padX;
    const span = innerEnd - innerStart;
    if (span > 0 && active > 0.02) {
      ctx.save();
      roundRectPath(innerStart, yRail - railH * 0.42, span, railH * 0.84, railH * 0.42);
      ctx.clip();

      const pktW = 0.020 * S;
      const cycles = 4;
      for (let i = 0; i < 2; i++) {
        const ph = (loopNorm * cycles + i * 0.5) % 1;
        const px = innerStart - pktW + ph * (span + pktW);
        ctx.globalAlpha = clamp01(active * Math.sin(ph * Math.PI) * 1.2);
        roundRectPath(px, yRail - railH * 0.34, pktW, railH * 0.68, railH * 0.34);
        ctx.fillStyle = '#FBBF24';
        ctx.fill();
      }
      ctx.restore();
    }
    ctx.restore();
  };

  drawConduit(cx - 0.425 * S, cx - 0.308 * S, conduitFlow);
  drawConduit(cx + 0.308 * S, cx + 0.425 * S, conduitFlow);

  // 5. Left Telemetry Card — Q1-Q4 Quarterly Revenue Bars
  const drawLeftCard = () => {
    const cardW = 0.24 * S;
    const cardH = 0.34 * S;
    const cardX = cx - 0.565 * S - cardW * 0.5;
    const cardY = cy - cardH * 0.5;
    const cardR = 0.024 * S;

    ctx.save();
    roundRectPath(cardX, cardY, cardW, cardH, cardR);
    const cardGrad = ctx.createLinearGradient(cardX, cardY, cardX, cardY + cardH);
    cardGrad.addColorStop(0, '#1D2411');
    cardGrad.addColorStop(1, '#10140A');
    ctx.fillStyle = cardGrad;
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.003 * S);
    ctx.strokeStyle = '#566528';
    ctx.stroke();

    // Header row: Saffron Target Dot + Clean Header Bars
    const bCx = cardX + 0.048 * S;
    const bCy = cardY + 0.050 * S;
    ctx.beginPath();
    ctx.arc(bCx, bCy, 0.022 * S, 0, Math.PI * 2);
    ctx.fillStyle = '#452806';
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.0026 * S);
    ctx.strokeStyle = '#F59E0B';
    ctx.stroke();

    // Mini clock glyph inside header badge
    ctx.beginPath();
    ctx.moveTo(bCx, bCy);
    ctx.lineTo(bCx, bCy - 0.011 * S);
    ctx.moveTo(bCx, bCy);
    ctx.lineTo(bCx + 0.008 * S, bCy + 0.004 * S);
    ctx.lineWidth = Math.max(1, 0.0028 * S);
    ctx.lineCap = 'round';
    ctx.strokeStyle = '#FEF3C7';
    ctx.stroke();

    roundRectPath(cardX + 0.088 * S, bCy - 0.010 * S, 0.104 * S, 0.009 * S, 0.0045 * S);
    ctx.fillStyle = '#FDE68A';
    ctx.fill();
    roundRectPath(cardX + 0.088 * S, bCy + 0.006 * S, 0.068 * S, 0.007 * S, 0.0035 * S);
    ctx.fillStyle = '#6B7D32';
    ctx.fill();

    // 4 Quarterly Target Bars (Q1..Q4)
    const chLeft = cardX + 0.032 * S;
    const chW = cardW - 0.064 * S;
    const chBot = cardY + 0.246 * S;
    const maxBH = 0.136 * S;
    const bGap = 0.015 * S;
    const bW = (chW - bGap * 3) / 4;
    const targets = [0.52, 0.68, 0.84, 1.0];

    roundRectPath(chLeft, chBot + 0.008 * S, chW, 0.004 * S, 0.002 * S);
    ctx.fillStyle = '#3C471D';
    ctx.fill();

    for (let q = 0; q < 4; q++) {
      const bx = chLeft + q * (bW + bGap);
      roundRectPath(bx, chBot - maxBH, bW, maxBH, bW * 0.34);
      ctx.fillStyle = '#0B0E06';
      ctx.fill();

      const qFill = clamp01(quarterTotal * 4 - q);
      const bh = Math.max(bW, maxBH * (0.14 + (targets[q] - 0.14) * qFill));
      roundRectPath(bx, chBot - bh, bW, bh, bW * 0.34);
      const bGrad = ctx.createLinearGradient(bx, chBot - bh, bx, chBot);
      bGrad.addColorStop(0, '#FBBF24');
      bGrad.addColorStop(1, '#EA580C');
      ctx.fillStyle = bGrad;
      ctx.fill();
    }

    // Bottom Efficiency Progress Track
    const tX = cardX + 0.030 * S;
    const tY = cardY + 0.286 * S;
    const tW = cardW - 0.060 * S;
    const tH = 0.014 * S;
    roundRectPath(tX, tY, tW, tH, tH * 0.5);
    ctx.fillStyle = '#0B0E06';
    ctx.fill();
    roundRectPath(tX, tY, Math.max(tH, tW * clamp01(0.12 + 0.88 * quarterTotal)), tH, tH * 0.5);
    ctx.fillStyle = '#F59E0B';
    ctx.fill();

    ctx.restore();
  };

  drawLeftCard();

  // 6. Right Telemetry Card — Annual Target Ring & 4 Quarter Milestone Dots
  const drawRightCard = () => {
    const cardW = 0.24 * S;
    const cardH = 0.34 * S;
    const cardX = cx + 0.565 * S - cardW * 0.5;
    const cardY = cy - cardH * 0.5;
    const cardR = 0.024 * S;

    ctx.save();
    roundRectPath(cardX, cardY, cardW, cardH, cardR);
    const cardGrad = ctx.createLinearGradient(cardX, cardY, cardX, cardY + cardH);
    cardGrad.addColorStop(0, '#1D2411');
    cardGrad.addColorStop(1, '#10140A');
    ctx.fillStyle = cardGrad;
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.003 * S);
    ctx.strokeStyle = '#566528';
    ctx.stroke();

    // Top Half: Circular Target Ring
    const rCx = cardX + cardW * 0.5;
    const rCy = cardY + 0.104 * S;
    const rRad = 0.058 * S;
    const rLW = 0.013 * S;
    const fillVal = clamp01(0.10 + 0.90 * quarterTotal);
    const startA = -Math.PI * 0.5;
    const endA = startA + Math.PI * 2 * fillVal;

    ctx.beginPath();
    ctx.arc(rCx, rCy, rRad, 0, Math.PI * 2);
    ctx.lineWidth = rLW;
    ctx.strokeStyle = '#0B0E06';
    ctx.stroke();

    const rGrad = ctx.createLinearGradient(rCx - rRad, rCy - rRad, rCx + rRad, rCy + rRad);
    rGrad.addColorStop(0, '#EA580C');
    rGrad.addColorStop(0.5, '#F59E0B');
    rGrad.addColorStop(1, '#FEF3C7');

    ctx.beginPath();
    ctx.arc(rCx, rCy, rRad, startA, endA);
    ctx.lineWidth = rLW;
    ctx.lineCap = 'round';
    ctx.strokeStyle = rGrad;
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(rCx + Math.cos(endA) * rRad, rCy + Math.sin(endA) * rRad, 0.0085 * S, 0, Math.PI * 2);
    ctx.fillStyle = '#FEF3C7';
    ctx.fill();

    // Crisp Diamond Target Badge Inside Ring
    ctx.save();
    ctx.translate(rCx, rCy);
    const dS = 0.020 * S;
    ctx.beginPath();
    ctx.moveTo(0, -dS);
    ctx.lineTo(dS * 0.85, 0);
    ctx.lineTo(0, dS);
    ctx.lineTo(-dS * 0.85, 0);
    ctx.closePath();
    ctx.fillStyle = quarterTotal > 0.7 ? '#FBBF24' : '#3C471D';
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.0024 * S);
    ctx.strokeStyle = '#FEF3C7';
    ctx.stroke();
    ctx.restore();

    // Divider
    const divY = cardY + 0.190 * S;
    roundRectPath(cardX + 0.036 * S, divY, cardW - 0.072 * S, 0.0025 * S, 0.00125 * S);
    ctx.fillStyle = '#4B5723';
    ctx.fill();

    // Bottom Half: 4 Quarter Milestone Nodes (Q1 - Q2 - Q3 - Q4)
    const nodeY = cardY + 0.256 * S;
    const nodeSpan = cardW - 0.080 * S;
    const nStartX = cardX + 0.040 * S;

    // Connecting baseline bar behind dots (drawn first, clean alignment)
    roundRectPath(nStartX, nodeY - 0.0025 * S, nodeSpan, 0.005 * S, 0.0025 * S);
    ctx.fillStyle = '#0B0E06';
    ctx.fill();

    roundRectPath(nStartX, nodeY - 0.0025 * S, nodeSpan * clamp01(quarterTotal), 0.005 * S, 0.0025 * S);
    ctx.fillStyle = '#F59E0B';
    ctx.fill();

    for (let q = 0; q < 4; q++) {
      const nx = nStartX + (q / 3) * nodeSpan;
      const reached = quarterTotal >= (q + 0.85) / 4;
      ctx.beginPath();
      ctx.arc(nx, nodeY, 0.011 * S, 0, Math.PI * 2);
      ctx.fillStyle = reached ? '#F59E0B' : '#161C0E';
      ctx.fill();
      ctx.lineWidth = Math.max(1, 0.0025 * S);
      ctx.strokeStyle = reached ? '#FEF3C7' : '#566528';
      ctx.stroke();
    }

    ctx.restore();
  };

  drawRightCard();

  // 7. Hero Centerpiece — Precision Revenue Clockwork & Target Bells
  const outerR = 0.252 * S;
  const dialR = 0.194 * S;

  // A. Twin Support Feet (Strictly angled bottom-left & bottom-right clear of pedestal at cy + 0.304*S)
  [Math.PI * 0.26, Math.PI * 0.74].forEach((ang) => {
    const f1 = outerR - 0.004 * S;
    const f2 = outerR + 0.036 * S;
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(cx + Math.cos(ang) * f1, cy + Math.sin(ang) * f1);
    ctx.lineTo(cx + Math.cos(ang) * f2, cy + Math.sin(ang) * f2);
    ctx.lineWidth = Math.max(1, 0.016 * S);
    ctx.lineCap = 'round';
    ctx.strokeStyle = '#D97706';
    ctx.stroke();

    ctx.lineWidth = Math.max(1, 0.007 * S);
    ctx.strokeStyle = '#FEF3C7';
    ctx.stroke();
    ctx.restore();
  });

  // B. Twin Target Bells & Smooth Acoustic Wave Arcs (-135 deg & -45 deg, No Jittery Shaking!)
  [-Math.PI * 0.75, -Math.PI * 0.25].forEach((bAng) => {
    const stemDist1 = outerR - 0.002 * S;
    const stemDist2 = outerR + 0.020 * S + bellPulse * 0.006 * S;
    const bellCenterDist = stemDist2 + 0.008 * S;

    // Connecting mount neck
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(cx + Math.cos(bAng) * stemDist1, cy + Math.sin(bAng) * stemDist1);
    ctx.lineTo(cx + Math.cos(bAng) * stemDist2, cy + Math.sin(bAng) * stemDist2);
    ctx.lineWidth = Math.max(1, 0.012 * S);
    ctx.lineCap = 'round';
    ctx.strokeStyle = '#785011';
    ctx.stroke();

    // Bell dome facing cleanly outward along bAng
    const bx = cx + Math.cos(bAng) * bellCenterDist;
    const by = cy + Math.sin(bAng) * bellCenterDist;
    ctx.save();
    ctx.translate(bx, by);
    ctx.rotate(bAng + Math.PI * 0.5);

    const bellR = 0.048 * S;
    ctx.beginPath();
    ctx.arc(0, 0, bellR, Math.PI, 0, false);
    ctx.closePath();
    const bGrad = ctx.createLinearGradient(-bellR, -bellR, bellR, 0);
    bGrad.addColorStop(0, '#FBBF24');
    bGrad.addColorStop(1, '#EA580C');
    ctx.fillStyle = bGrad;
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.0028 * S);
    ctx.strokeStyle = '#FEF3C7';
    ctx.stroke();
    ctx.restore();

    // Crisp Concentric Acoustic Wave Arcs When Chime Triggers (Strictly clear of bell & canvas top edge)
    if (bellPulse > 0.05) {
      for (let w = 0; w < 2; w++) {
        const wr = bellR + (0.018 + w * 0.018 + bellPulse * 0.014) * S;
        ctx.save();
        ctx.globalAlpha = clamp01(bellPulse * (0.8 - w * 0.25));
        ctx.beginPath();
        ctx.arc(bx, by, wr, bAng - 0.52, bAng + 0.52);
        ctx.lineWidth = Math.max(1, 0.003 * S);
        ctx.lineCap = 'round';
        ctx.strokeStyle = '#FDE68A';
        ctx.stroke();
        ctx.restore();
      }
    }

    ctx.restore();
  });

  // C. Main Clockwork Outer Bezel Ring & Quarter Progress Track
  ctx.save();
  ctx.beginPath();
  ctx.arc(cx, cy, outerR, 0, Math.PI * 2);
  const bezelGrad = ctx.createLinearGradient(cx - outerR, cy - outerR, cx + outerR, cy + outerR);
  bezelGrad.addColorStop(0, '#2B3417');
  bezelGrad.addColorStop(1, '#14190A');
  ctx.fillStyle = bezelGrad;
  ctx.fill();
  ctx.lineWidth = Math.max(1, 0.004 * S);
  ctx.strokeStyle = '#F59E0B';
  ctx.stroke();

  // Quarter Progress Track in Bezel Margin (r = 0.223*S)
  const progR = 0.223 * S;
  const progLW = 0.012 * S;
  ctx.beginPath();
  ctx.arc(cx, cy, progR, 0, Math.PI * 2);
  ctx.lineWidth = progLW;
  ctx.strokeStyle = '#0D1107';
  ctx.stroke();

  if (quarterTotal > 0.005) {
    const startA = -Math.PI * 0.5;
    const endA = startA + Math.PI * 2 * clamp01(quarterTotal);
    const pGrad = ctx.createLinearGradient(cx - progR, cy - progR, cx + progR, cy + progR);
    pGrad.addColorStop(0, '#EA580C');
    pGrad.addColorStop(0.5, '#F59E0B');
    pGrad.addColorStop(1, '#FEF3C7');
    ctx.beginPath();
    ctx.arc(cx, cy, progR, startA, endA);
    ctx.lineWidth = progLW;
    ctx.lineCap = 'round';
    ctx.strokeStyle = pGrad;
    ctx.stroke();
  }

  // 4 Quarter Milestone Nodes on Bezel (12, 3, 6, 9 o'clock)
  for (let q = 0; q < 4; q++) {
    const qa = -Math.PI * 0.5 + (q * Math.PI) / 2;
    const qx = cx + Math.cos(qa) * progR;
    const qy = cy + Math.sin(qa) * progR;
    const lit = quarterTotal >= q / 4 + 0.02;
    ctx.beginPath();
    ctx.arc(qx, qy, 0.0075 * S, 0, Math.PI * 2);
    ctx.fillStyle = lit ? '#FEF3C7' : '#2E3818';
    ctx.fill();
  }

  // D. Interior Dial Face (Clipped Cleanly Inside dialR)
  ctx.save();
  ctx.beginPath();
  ctx.arc(cx, cy, dialR, 0, Math.PI * 2);
  ctx.fillStyle = '#090C05';
  ctx.fill();
  ctx.clip();

  // Recessed Mechanical Gear Sub-Window (Center r = 0.108*S)
  const gearWinR = 0.108 * S;
  ctx.save();
  ctx.beginPath();
  ctx.arc(cx, cy, gearWinR, 0, Math.PI * 2);
  ctx.fillStyle = '#12180A';
  ctx.fill();
  ctx.clip();

  // Meshed Gear Drawer Helper
  const drawGear = (gx, gy, pitchR, teeth, rotAngle, fillCol, strokeCol) => {
    ctx.save();
    ctx.translate(gx, gy);
    ctx.rotate(rotAngle);
    const outerTR = pitchR + 0.009 * S;
    const innerTR = pitchR - 0.007 * S;
    const stepA = (Math.PI * 2) / teeth;

    ctx.beginPath();
    for (let i = 0; i < teeth; i++) {
      const a0 = i * stepA;
      const a1 = a0 + stepA * 0.22;
      const a2 = a0 + stepA * 0.34;
      const a3 = a0 + stepA * 0.66;
      const a4 = a0 + stepA * 0.78;
      if (i === 0) ctx.moveTo(Math.cos(a0) * innerTR, Math.sin(a0) * innerTR);
      ctx.lineTo(Math.cos(a1) * innerTR, Math.sin(a1) * innerTR);
      ctx.lineTo(Math.cos(a2) * outerTR, Math.sin(a2) * outerTR);
      ctx.lineTo(Math.cos(a3) * outerTR, Math.sin(a3) * outerTR);
      ctx.lineTo(Math.cos(a4) * innerTR, Math.sin(a4) * innerTR);
    }
    ctx.closePath();
    ctx.fillStyle = fillCol;
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.0018 * S);
    ctx.strokeStyle = strokeCol;
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(0, 0, innerTR * 0.45, 0, Math.PI * 2);
    ctx.fillStyle = '#090C05';
    ctx.fill();
    ctx.restore();
  };

  // Gear A (12 teeth, r=0.042*S) & Gear B (8 teeth, r=0.028*S) meshed at exact pitch distance 0.070*S!
  drawGear(cx - 0.028 * S, cy + 0.022 * S, 0.042 * S, 12, gearAAngle, '#333D19', '#8A7026');
  drawGear(cx + 0.031 * S, cy - 0.016 * S, 0.028 * S, 8, gearBAngle, '#4A3810', '#D97706');

  ctx.restore(); // End gear window clip

  ctx.beginPath();
  ctx.arc(cx, cy, gearWinR, 0, Math.PI * 2);
  ctx.lineWidth = Math.max(1, 0.0024 * S);
  ctx.strokeStyle = '#3C471D';
  ctx.stroke();

  // 12 Crisp Radial Hour Ticks Strictly Outside Gear Window (r in [0.152*S, 0.178*S])
  for (let h = 0; h < 12; h++) {
    const ha = -Math.PI * 0.5 + (h / 12) * Math.PI * 2;
    const isMajor = h % 3 === 0;
    const r1 = (isMajor ? 0.148 : 0.158) * S;
    const r2 = 0.178 * S;
    ctx.beginPath();
    ctx.moveTo(cx + Math.cos(ha) * r1, cy + Math.sin(ha) * r1);
    ctx.lineTo(cx + Math.cos(ha) * r2, cy + Math.sin(ha) * r2);
    ctx.lineWidth = Math.max(1, (isMajor ? 0.004 : 0.0024) * S);
    ctx.lineCap = 'round';
    ctx.strokeStyle = isMajor ? '#FDE68A' : '#5E6E2B';
    ctx.stroke();
  }

  // Hour Hand (Smooth Continuous Forward Rotation)
  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate(hourAngle);
  roundRectPath(-0.0055 * S, -0.098 * S, 0.011 * S, 0.106 * S, 0.0055 * S);
  ctx.fillStyle = '#FB923C';
  ctx.fill();
  ctx.restore();

  // Minute Hand (Smooth Continuous Forward Rotation)
  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate(minuteAngle);
  roundRectPath(-0.0038 * S, -0.140 * S, 0.0076 * S, 0.150 * S, 0.0038 * S);
  ctx.fillStyle = '#FEF3C7';
  ctx.fill();
  ctx.restore();

  // Central Precision Axis Cap
  ctx.beginPath();
  ctx.arc(cx, cy, 0.015 * S, 0, Math.PI * 2);
  ctx.fillStyle = '#F59E0B';
  ctx.fill();
  ctx.lineWidth = Math.max(1, 0.0026 * S);
  ctx.strokeStyle = '#FEF3C7';
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(cx, cy, 0.0055 * S, 0, Math.PI * 2);
  ctx.fillStyle = '#090C05';
  ctx.fill();

  ctx.restore(); // End dial face clip

  // Dial Crisp Rim Stroke
  ctx.beginPath();
  ctx.arc(cx, cy, dialR, 0, Math.PI * 2);
  ctx.lineWidth = Math.max(1, 0.003 * S);
  ctx.strokeStyle = '#6B7D32';
  ctx.stroke();

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const S = minSide;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const easeInOutCubic = (x) => {
    const v = clamp01(x);
    return v < 0.5 ? 4 * v * v * v : 1 - Math.pow(-2 * v + 2, 3) / 2;
  };
  const easeOutCubic = (x) => {
    const v = clamp01(x);
    return 1 - Math.pow(1 - v, 3);
  };
  const easeInOutSine = (x) => {
    const v = clamp01(x);
    return -(Math.cos(Math.PI * v) - 1) * 0.5;
  };
  const lerp = (a, b, k) => a + (b - a) * k;

  const roundRectPath = (x, y, w, h, r) => {
    const rad = Math.max(0, Math.min(r, w * 0.5, h * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  };

  const drawDollarSign = (x, y, size, color, lw) => {
    ctx.save();
    ctx.translate(x, y);
    ctx.strokeStyle = color;
    ctx.lineWidth = lw;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.beginPath();
    ctx.moveTo(0, -size * 1.12);
    ctx.lineTo(0, size * 1.12);
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(size * 0.65, -size * 0.48);
    ctx.bezierCurveTo(size * 0.62, -size * 0.90, -size * 0.68, -size * 0.90, -size * 0.65, -size * 0.35);
    ctx.bezierCurveTo(-size * 0.62, 0, size * 0.65, 0, size * 0.65, size * 0.38);
    ctx.bezierCurveTo(size * 0.65, size * 0.90, -size * 0.65, size * 0.90, -size * 0.68, size * 0.48);
    ctx.stroke();
    ctx.restore();
  };

  // 1. Clean Modern Dark Aesthetic Gradient Background (Midnight Aubergine, Zero Glow, Zero Borders)
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, '#0B0617');
  bgGrad.addColorStop(0.5, '#150B2B');
  bgGrad.addColorStop(1, '#201142');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // 2. Global Seamless Motion Parameters Driven by t, loopT, currentScene, sceneProgress
  const loopNorm = loopT / duration;
  const wavePhase = loopNorm * Math.PI * 2 * 6;
  const turbineAngle = loopNorm * Math.PI * 2 * 4; // Exact 4 smooth revolutions over 20s

  let nozzleTilt = 0; // 0 = idle horizontal, 1 = tilted pouring
  let pourStream = 0;
  let mainFill = 0.28;
  let bucketFills = [0.22, 0.22, 0.22]; // Cash, Reinvest, Reserve
  let distFlow = 0.20;
  let yieldRing = 0.24;
  let conduitFlow = 0.25;
  let payoutVerified = 0;

  if (currentScene === 0) {
    // Scene 0 (0-5s): Nozzle tilts smoothly & pours capital into Primary Reservoir Tank
    nozzleTilt = easeInOutCubic(sceneProgress / 0.26);
    pourStream = easeOutCubic((sceneProgress - 0.16) / 0.18);
    mainFill = lerp(0.28, 0.84, easeInOutCubic((sceneProgress - 0.18) / 0.78));
    bucketFills = [0.22, 0.22, 0.22];
    distFlow = 0.20 + 0.15 * easeInOutSine(sceneProgress);
    yieldRing = lerp(0.24, 0.44, easeInOutSine(sceneProgress));
    conduitFlow = 0.25 + 0.40 * easeInOutSine(sceneProgress);
  } else if (currentScene === 1) {
    // Scene 1 (5-10s): Pour finishes smoothly; turbine channels yield into 3 Dividend Vessels
    nozzleTilt = 1 - easeInOutCubic((sceneProgress - 0.58) / 0.34);
    pourStream = 1 - easeInOutCubic((sceneProgress - 0.45) / 0.25);
    const drainMain = easeInOutCubic((sceneProgress - 0.25) / 0.72);
    mainFill = lerp(0.84, 0.58, drainMain);
    bucketFills[0] = lerp(0.22, 0.76, easeInOutCubic((sceneProgress - 0.10) / 0.75));
    bucketFills[1] = lerp(0.22, 0.84, easeInOutCubic((sceneProgress - 0.22) / 0.72));
    bucketFills[2] = lerp(0.22, 0.72, easeInOutCubic((sceneProgress - 0.34) / 0.64));
    distFlow = lerp(0.35, 0.95, easeInOutSine(sceneProgress));
    yieldRing = lerp(0.44, 0.84, easeInOutSine(sceneProgress));
    conduitFlow = 0.85;
  } else if (currentScene === 2) {
    // Scene 2 (10-15s): Sustained full ecosystem yield & payout verification
    nozzleTilt = 0;
    pourStream = 0;
    mainFill = 0.58 + 0.02 * Math.sin(sceneProgress * Math.PI * 2);
    bucketFills[0] = lerp(0.76, 0.86, easeInOutSine(sceneProgress));
    bucketFills[1] = lerp(0.84, 0.92, easeInOutSine(sceneProgress));
    bucketFills[2] = lerp(0.72, 0.82, easeInOutSine(sceneProgress));
    distFlow = 0.85 + 0.15 * Math.sin(sceneProgress * Math.PI);
    yieldRing = lerp(0.84, 0.96, easeInOutCubic(sceneProgress / 0.65));
    conduitFlow = 0.92;
    payoutVerified = easeInOutCubic((sceneProgress - 0.12) / 0.48);
  } else {
    // Scene 3 (15-20s): Controlled drainage & smooth reset to exact t = 0 baseline
    const rk = easeInOutCubic(sceneProgress / 0.88);
    nozzleTilt = 0;
    pourStream = 0;
    mainFill = lerp(0.58, 0.28, rk);
    bucketFills[0] = lerp(0.86, 0.22, rk);
    bucketFills[1] = lerp(0.92, 0.22, rk);
    bucketFills[2] = lerp(0.82, 0.22, rk);
    distFlow = lerp(0.85, 0.20, rk);
    yieldRing = lerp(0.96, 0.24, rk);
    conduitFlow = lerp(0.92, 0.25, rk);
    payoutVerified = 1 - easeInOutCubic(sceneProgress / 0.35);
  }

  // 3. Grounding Pedestal Pill Beneath Lower Vessels
  ctx.save();
  const pedW = 0.48 * S;
  const pedH = 0.018 * S;
  const pedY = cy + 0.304 * S;
  roundRectPath(cx - pedW * 0.5, pedY, pedW, pedH, pedH * 0.5);
  ctx.fillStyle = '#070410';
  ctx.fill();
  ctx.lineWidth = Math.max(1, 0.0022 * S);
  ctx.strokeStyle = '#4C2889';
  ctx.stroke();
  ctx.restore();

  // 4. Precision Conduit Buses (Strictly Clear of Center Vessels [+/-0.230*S] and Cards [+/-0.440*S])
  const drawConduit = (xStart, xEnd, active) => {
    ctx.save();
    const yRail = cy;
    const termR = 0.0075 * S;
    const railH = 0.009 * S;
    const padX = 0.011 * S;

    roundRectPath(xStart, yRail - railH * 0.5, xEnd - xStart, railH, railH * 0.5);
    ctx.fillStyle = '#0E0720';
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.002 * S);
    ctx.strokeStyle = '#4C2889';
    ctx.stroke();

    [xStart, xEnd].forEach((tx) => {
      ctx.beginPath();
      ctx.arc(tx, yRail, termR, 0, Math.PI * 2);
      ctx.fillStyle = '#1B0E3B';
      ctx.fill();
      ctx.lineWidth = Math.max(1, 0.0024 * S);
      ctx.strokeStyle = active > 0.4 ? '#A78BFA' : '#5B339E';
      ctx.stroke();
    });

    const innerStart = xStart + padX;
    const innerEnd = xEnd - padX;
    const span = innerEnd - innerStart;
    if (span > 0 && active > 0.02) {
      ctx.save();
      roundRectPath(innerStart, yRail - railH * 0.42, span, railH * 0.84, railH * 0.42);
      ctx.clip();

      const pktW = 0.020 * S;
      const cycles = 4;
      for (let i = 0; i < 2; i++) {
        const ph = (loopNorm * cycles + i * 0.5) % 1;
        const px = innerStart - pktW + ph * (span + pktW);
        ctx.globalAlpha = clamp01(active * Math.sin(ph * Math.PI) * 1.2);
        roundRectPath(px, yRail - railH * 0.34, pktW, railH * 0.68, railH * 0.34);
        ctx.fillStyle = '#DDD6FE';
        ctx.fill();
      }
      ctx.restore();
    }
    ctx.restore();
  };

  drawConduit(cx - 0.422 * S, cx - 0.265 * S, conduitFlow);
  drawConduit(cx + 0.265 * S, cx + 0.422 * S, conduitFlow);

  // 5. Left Telemetry Card — 3-Bucket Dividend Allocation Equalizer
  const drawLeftCard = () => {
    const cardW = 0.24 * S;
    const cardH = 0.34 * S;
    const cardX = cx - 0.56 * S - cardW * 0.5;
    const cardY = cy - cardH * 0.5;
    const cardR = 0.024 * S;

    ctx.save();
    roundRectPath(cardX, cardY, cardW, cardH, cardR);
    const cardGrad = ctx.createLinearGradient(cardX, cardY, cardX, cardY + cardH);
    cardGrad.addColorStop(0, '#221244');
    cardGrad.addColorStop(1, '#110826');
    ctx.fillStyle = cardGrad;
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.003 * S);
    ctx.strokeStyle = '#5B339E';
    ctx.stroke();

    // Header row: circular Lavender '$' badge + clean header bars
    const badgeR = 0.024 * S;
    const badgeCx = cardX + 0.050 * S;
    const badgeCy = cardY + 0.052 * S;

    ctx.beginPath();
    ctx.arc(badgeCx, badgeCy, badgeR, 0, Math.PI * 2);
    ctx.fillStyle = '#3B1D73';
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.0026 * S);
    ctx.strokeStyle = '#A78BFA';
    ctx.stroke();
    drawDollarSign(badgeCx, badgeCy, badgeR * 0.48, '#F5F3FF', Math.max(1, 0.0036 * S));

    roundRectPath(cardX + 0.090 * S, badgeCy - 0.011 * S, 0.104 * S, 0.009 * S, 0.0045 * S);
    ctx.fillStyle = '#DDD6FE';
    ctx.fill();
    roundRectPath(cardX + 0.090 * S, badgeCy + 0.005 * S, 0.068 * S, 0.007 * S, 0.0035 * S);
    ctx.fillStyle = '#6D43B5';
    ctx.fill();

    // Middle: 3 Vertical Allocation Bars Synced With 3 Dividend Vessels
    const chLeft = cardX + 0.036 * S;
    const chW = cardW - 0.072 * S;
    const chBot = cardY + 0.246 * S;
    const maxBH = 0.132 * S;
    const bGap = 0.020 * S;
    const bW = (chW - bGap * 2) / 3;
    const barCols = ['#C4B5FD', '#A78BFA', '#8B5CF6'];

    roundRectPath(chLeft, chBot + 0.008 * S, chW, 0.004 * S, 0.002 * S);
    ctx.fillStyle = '#4C2889';
    ctx.fill();

    for (let i = 0; i < 3; i++) {
      const bx = chLeft + i * (bW + bGap);
      roundRectPath(bx, chBot - maxBH, bW, maxBH, bW * 0.32);
      ctx.fillStyle = '#0B0617';
      ctx.fill();

      const bh = Math.max(bW, maxBH * clamp01(bucketFills[i]));
      roundRectPath(bx, chBot - bh, bW, bh, bW * 0.32);
      const bGrad = ctx.createLinearGradient(bx, chBot - bh, bx, chBot);
      bGrad.addColorStop(0, '#EDE9FE');
      bGrad.addColorStop(1, barCols[i]);
      ctx.fillStyle = bGrad;
      ctx.fill();
    }

    // Bottom horizontal summary bar
    const trackX = cardX + 0.030 * S;
    const trackY = cardY + 0.286 * S;
    const trackW = cardW - 0.060 * S;
    const trackH = 0.014 * S;
    roundRectPath(trackX, trackY, trackW, trackH, trackH * 0.5);
    ctx.fillStyle = '#0B0617';
    ctx.fill();
    roundRectPath(trackX, trackY, Math.max(trackH, trackW * clamp01(yieldRing)), trackH, trackH * 0.5);
    ctx.fillStyle = '#A78BFA';
    ctx.fill();

    ctx.restore();
  };

  drawLeftCard();

  // 6. Right Telemetry Card — Yield Ring Gauge & Verified Payout Status
  const drawRightCard = () => {
    const cardW = 0.24 * S;
    const cardH = 0.34 * S;
    const cardX = cx + 0.56 * S - cardW * 0.5;
    const cardY = cy - cardH * 0.5;
    const cardR = 0.024 * S;

    ctx.save();
    roundRectPath(cardX, cardY, cardW, cardH, cardR);
    const cardGrad = ctx.createLinearGradient(cardX, cardY, cardX, cardY + cardH);
    cardGrad.addColorStop(0, '#221244');
    cardGrad.addColorStop(1, '#110826');
    ctx.fillStyle = cardGrad;
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.003 * S);
    ctx.strokeStyle = '#5B339E';
    ctx.stroke();

    // Top Half: Yield Ring Gauge
    const rCx = cardX + cardW * 0.5;
    const rCy = cardY + 0.104 * S;
    const rRad = 0.058 * S;
    const rLW = 0.013 * S;
    const startA = -Math.PI * 0.5;
    const endA = startA + Math.PI * 2 * clamp01(yieldRing);

    ctx.beginPath();
    ctx.arc(rCx, rCy, rRad, 0, Math.PI * 2);
    ctx.lineWidth = rLW;
    ctx.strokeStyle = '#0B0617';
    ctx.stroke();

    const rGrad = ctx.createLinearGradient(rCx - rRad, rCy - rRad, rCx + rRad, rCy + rRad);
    rGrad.addColorStop(0, '#7C3AED');
    rGrad.addColorStop(0.5, '#A78BFA');
    rGrad.addColorStop(1, '#F5F3FF');

    ctx.beginPath();
    ctx.arc(rCx, rCy, rRad, startA, endA);
    ctx.lineWidth = rLW;
    ctx.lineCap = 'round';
    ctx.strokeStyle = rGrad;
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(rCx + Math.cos(endA) * rRad, rCy + Math.sin(endA) * rRad, 0.0085 * S, 0, Math.PI * 2);
    ctx.fillStyle = '#FFFFFF';
    ctx.fill();

    // Clean percentage / downward yield arrow inside ring
    ctx.save();
    ctx.translate(rCx, rCy);
    ctx.strokeStyle = '#DDD6FE';
    ctx.lineWidth = Math.max(1, 0.004 * S);
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    const arr = 0.020 * S;
    ctx.beginPath();
    ctx.moveTo(0, arr * 0.78);
    ctx.lineTo(0, -arr * 0.78);
    ctx.moveTo(-arr * 0.60, -arr * 0.16);
    ctx.lineTo(0, -arr * 0.78);
    ctx.lineTo(arr * 0.60, -arr * 0.16);
    ctx.stroke();
    ctx.restore();

    // Divider
    const divY = cardY + 0.190 * S;
    roundRectPath(cardX + 0.036 * S, divY, cardW - 0.072 * S, 0.0025 * S, 0.00125 * S);
    ctx.fillStyle = '#4C2889';
    ctx.fill();

    // Bottom Half: Payout Verification Pill & Animated Checkmark
    const pCx = cardX + cardW * 0.5;
    const pCy = cardY + 0.256 * S;
    const pRad = 0.038 * S;

    ctx.beginPath();
    ctx.arc(pCx, pCy, pRad, 0, Math.PI * 2);
    ctx.fillStyle = payoutVerified > 0.2 ? '#4C1D95' : '#160B33';
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.003 * S);
    ctx.strokeStyle = payoutVerified > 0.2 ? '#DDD6FE' : '#5B339E';
    ctx.stroke();

    if (payoutVerified > 0.01) {
      const p1 = { x: pCx - pRad * 0.42, y: pCy + pRad * 0.04 };
      const p2 = { x: pCx - pRad * 0.08, y: pCy + pRad * 0.36 };
      const p3 = { x: pCx + pRad * 0.46, y: pCy - pRad * 0.26 };

      const l1 = Math.hypot(p2.x - p1.x, p2.y - p1.y);
      const l2 = Math.hypot(p3.x - p2.x, p3.y - p2.y);
      const drawL = (l1 + l2) * clamp01(payoutVerified);

      ctx.beginPath();
      ctx.moveTo(p1.x, p1.y);
      if (drawL <= l1) {
        const k = drawL / l1;
        ctx.lineTo(lerp(p1.x, p2.x, k), lerp(p1.y, p2.y, k));
      } else {
        ctx.lineTo(p2.x, p2.y);
        const k = (drawL - l1) / l2;
        ctx.lineTo(lerp(p2.x, p3.x, k), lerp(p2.y, p3.y, k));
      }
      ctx.lineWidth = Math.max(1, 0.0048 * S);
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.strokeStyle = '#F5F3FF';
      ctx.stroke();
    } else {
      ctx.beginPath();
      ctx.arc(pCx, pCy, 0.008 * S, 0, Math.PI * 2);
      ctx.fillStyle = '#6D43B5';
      ctx.fill();
    }

    ctx.restore();
  };

  drawRightCard();

  // 7. Hero Centerpiece — Tilting Pour Nozzle + Primary Tank + Micro-Turbine + 3 Dividend Vessels

  // Helper to draw a sleek crystal vessel with dual-layer liquid waves
  const drawVessel = (vx, vy, vw, vh, fillRatio, topColor, botColor, crestColor, hasStream, streamStartX, streamStartY) => {
    const vr = 0.016 * S;
    const left = vx - vw * 0.5;
    const top = vy - vh * 0.5;

    ctx.save();
    roundRectPath(left, top, vw, vh, vr);
    ctx.fillStyle = '#0D071E';
    ctx.fill();
    ctx.clip();

    const baseLiqY = top + vh * (1 - clamp01(fillRatio));
    const amp = (0.0045 + (hasStream ? 0.0035 * pourStream : 0)) * S;
    const getWY = (px) => {
      const nx = (px - left) / vw;
      return baseLiqY + Math.sin(nx * Math.PI * 2.4 + wavePhase) * amp;
    };

    // Pouring stream entering tank from above
    if (hasStream && pourStream > 0.01) {
      const sTop = top;
      const sBot = getWY(streamStartX) + 0.008 * S;
      const sW = 0.016 * S * pourStream;
      if (sBot > sTop) {
        ctx.beginPath();
        const stSteps = 14;
        for (let i = 0; i <= stSteps; i++) {
          const k = i / stSteps;
          const sy = lerp(sTop, sBot, k);
          const sx = lerp(streamStartX, cx, k * 0.8);
          const sway = Math.sin(k * Math.PI * 3 - wavePhase * 1.4) * 0.0024 * S * pourStream;
          const hw = sW * (0.55 - 0.14 * Math.sin(k * Math.PI * 0.5));
          if (i === 0) ctx.moveTo(sx - hw + sway, sy);
          else ctx.lineTo(sx - hw + sway, sy);
        }
        for (let i = stSteps; i >= 0; i--) {
          const k = i / stSteps;
          const sy = lerp(sTop, sBot, k);
          const sx = lerp(streamStartX, cx, k * 0.8);
          const sway = Math.sin(k * Math.PI * 3 - wavePhase * 1.4) * 0.0024 * S * pourStream;
          const hw = sW * (0.55 - 0.14 * Math.sin(k * Math.PI * 0.5));
          ctx.lineTo(sx + hw + sway, sy);
        }
        ctx.closePath();
        ctx.fillStyle = '#DDD6FE';
        ctx.fill();
      }
    }

    // Back wave
    const steps = 22;
    ctx.beginPath();
    ctx.moveTo(left, top + vh);
    for (let i = 0; i <= steps; i++) {
      const px = left + (i / steps) * vw;
      const py = baseLiqY - 0.003 * S + Math.sin(((px - left) / vw) * Math.PI * 2.4 - wavePhase + 1.3) * (amp * 0.8);
      ctx.lineTo(px, py);
    }
    ctx.lineTo(left + vw, top + vh);
    ctx.closePath();
    ctx.fillStyle = '#4C1D95';
    ctx.fill();

    // Front wave
    ctx.beginPath();
    ctx.moveTo(left, top + vh);
    for (let i = 0; i <= steps; i++) {
      const px = left + (i / steps) * vw;
      ctx.lineTo(px, getWY(px));
    }
    ctx.lineTo(left + vw, top + vh);
    ctx.closePath();
    const lGrad = ctx.createLinearGradient(vx, baseLiqY, vx, top + vh);
    lGrad.addColorStop(0, topColor);
    lGrad.addColorStop(1, botColor);
    ctx.fillStyle = lGrad;
    ctx.fill();

    // Crest highlight
    ctx.beginPath();
    for (let i = 0; i <= steps; i++) {
      const px = left + (i / steps) * vw;
      const py = getWY(px);
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.lineWidth = Math.max(1, 0.0032 * S);
    ctx.strokeStyle = crestColor;
    ctx.stroke();

    // Subtle rising pearl bubbles strictly below surface
    for (let b = 0; b < 4; b++) {
      const bProg = (loopNorm * 3 + b * 0.25) % 1;
      const bx = left + vw * (0.24 + b * 0.17);
      const topLim = getWY(bx) + 0.012 * S;
      const botLim = top + vh - 0.010 * S;
      if (botLim > topLim) {
        const by = lerp(botLim, topLim, bProg);
        ctx.save();
        ctx.globalAlpha = Math.sin(bProg * Math.PI) * 0.68;
        ctx.beginPath();
        ctx.arc(bx, by, 0.0026 * S, 0, Math.PI * 2);
        ctx.fillStyle = '#F5F3FF';
        ctx.fill();
        ctx.restore();
      }
    }

    // Specular highlight strip on left wall
    ctx.save();
    ctx.globalAlpha = 0.10;
    roundRectPath(left + 0.008 * S, top + 0.012 * S, 0.006 * S, vh - 0.024 * S, 0.003 * S);
    ctx.fillStyle = '#F5F3FF';
    ctx.fill();
    ctx.restore();

    ctx.restore();

    // Crisp outer glass bezel
    roundRectPath(left, top, vw, vh, vr);
    ctx.lineWidth = Math.max(1, 0.0032 * S);
    ctx.strokeStyle = '#8B5CF6';
    ctx.stroke();
  };

  // A. Tilting Source Capital Nozzle (Strictly above Primary Tank cy - 0.1025*S)
  const nozPivotX = cx + 0.145 * S;
  const nozPivotY = cy - 0.205 * S;
  const tiltRad = -nozzleTilt * 0.44;
  // Compute spout tip world position cleanly for the falling stream
  const spoutLocalX = -0.088 * S;
  const spoutLocalY = 0.014 * S;
  const spoutWorldX = nozPivotX + spoutLocalX * Math.cos(tiltRad) - spoutLocalY * Math.sin(tiltRad);
  const spoutWorldY = nozPivotY + spoutLocalX * Math.sin(tiltRad) + spoutLocalY * Math.cos(tiltRad);

  // Curved falling capital stream strictly between spoutWorldY and Primary Tank top (cy - 0.1025*S)
  const tankTopY = cy - 0.1025 * S;
  if (pourStream > 0.01) {
    ctx.save();
    const sW = 0.016 * S * pourStream;
    const steps = 14;
    ctx.beginPath();
    for (let i = 0; i <= steps; i++) {
      const k = i / steps;
      const sx = lerp(spoutWorldX, cx + 0.015 * S, k);
      const sy = lerp(spoutWorldY, tankTopY, k * k * 0.55 + k * 0.45);
      const hw = sW * (0.48 + 0.08 * Math.sin(k * Math.PI));
      if (i === 0) ctx.moveTo(sx - hw, sy);
      else ctx.lineTo(sx - hw, sy);
    }
    for (let i = steps; i >= 0; i--) {
      const k = i / steps;
      const sx = lerp(spoutWorldX, cx + 0.015 * S, k);
      const sy = lerp(spoutWorldY, tankTopY, k * k * 0.55 + k * 0.45);
      const hw = sW * (0.48 + 0.08 * Math.sin(k * Math.PI));
      ctx.lineTo(sx + hw, sy);
    }
    ctx.closePath();
    const stGrad = ctx.createLinearGradient(spoutWorldX, spoutWorldY, cx, tankTopY);
    stGrad.addColorStop(0, '#F5F3FF');
    stGrad.addColorStop(1, '#C4B5FD');
    ctx.fillStyle = stGrad;
    ctx.fill();
    ctx.restore();
  }

  // Draw Tilting Nozzle Body Over Stream Origin
  ctx.save();
  ctx.translate(nozPivotX, nozPivotY);
  ctx.rotate(tiltRad);

  // Main reservoir capsule of nozzle
  roundRectPath(-0.048 * S, -0.026 * S, 0.096 * S, 0.052 * S, 0.016 * S);
  const nozGrad = ctx.createLinearGradient(-0.048 * S, -0.026 * S, 0.048 * S, 0.026 * S);
  nozGrad.addColorStop(0, '#6D28D9');
  nozGrad.addColorStop(1, '#4C1D95');
  ctx.fillStyle = nozGrad;
  ctx.fill();
  ctx.lineWidth = Math.max(1, 0.003 * S);
  ctx.strokeStyle = '#C4B5FD';
  ctx.stroke();

  // Tapered pouring spout extending cleanly left
  ctx.beginPath();
  ctx.moveTo(-0.044 * S, -0.012 * S);
  ctx.lineTo(-0.090 * S, 0.008 * S);
  ctx.lineTo(-0.090 * S, 0.020 * S);
  ctx.lineTo(-0.044 * S, 0.018 * S);
  ctx.closePath();
  ctx.fillStyle = '#7C3AED';
  ctx.fill();
  ctx.lineWidth = Math.max(1, 0.0025 * S);
  ctx.strokeStyle = '#DDD6FE';
  ctx.stroke();

  // Center indicator dot on nozzle
  ctx.beginPath();
  ctx.arc(0, 0, 0.010 * S, 0, Math.PI * 2);
  ctx.fillStyle = '#DDD6FE';
  ctx.fill();
  ctx.restore();

  // B. Primary Upper Reservoir Tank
  drawVessel(
    cx,
    cy - 0.025 * S,
    0.220 * S,
    0.155 * S,
    mainFill,
    '#A78BFA',
    '#6D28D9',
    '#F5F3FF',
    pourStream > 0.01,
    cx + 0.015 * S,
    tankTopY
  );

  // C. Distribution Bus + Center Spinning Micro-Turbine Rotor (Strictly clear between Primary Tank & 3 Lower Vessels!)
  const turbY = cy + 0.092 * S;
  const turbR = 0.026 * S;
  const busLeftX = cx - 0.164 * S;
  const busRightX = cx + 0.164 * S;

  // Clean horizontal distribution rails on left & right of turbine (clear 0.012*S gap from turbine ring)
  [-1, 1].forEach((side) => {
    const rx1 = cx + side * (turbR + 0.012 * S);
    const rx2 = cx + side * 0.164 * S;
    const tx = Math.min(rx1, rx2);
    const tw = Math.abs(rx2 - rx1);
    const th = 0.008 * S;

    roundRectPath(tx, turbY - th * 0.5, tw, th, th * 0.5);
    ctx.fillStyle = '#14092E';
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.0018 * S);
    ctx.strokeStyle = '#6D28D9';
    ctx.stroke();

    // Clipped dividend packet gliding along distribution rail
    if (distFlow > 0.02) {
      ctx.save();
      roundRectPath(tx + 0.004 * S, turbY - th * 0.4, Math.max(0, tw - 0.008 * S), th * 0.8, th * 0.4);
      ctx.clip();
      const ph = (loopNorm * 4 + (side > 0 ? 0.5 : 0)) % 1;
      const pktW = 0.018 * S;
      const px = side > 0 ? lerp(tx - pktW, tx + tw, ph) : lerp(tx + tw, tx - pktW, ph);
      ctx.globalAlpha = clamp01(distFlow * Math.sin(ph * Math.PI) * 1.2);
      roundRectPath(px, turbY - th * 0.34, pktW, th * 0.68, th * 0.34);
      ctx.fillStyle = '#DDD6FE';
      ctx.fill();
      ctx.restore();
    }

    // Small terminal drop indicator dot cleanly above Left & Right vessels (cy + 0.118*S -> 0.026*S above vessels!)
    ctx.beginPath();
    ctx.arc(cx + side * 0.164 * S, turbY + 0.024 * S, 0.005 * S, 0, Math.PI * 2);
    ctx.fillStyle = distFlow > 0.45 ? '#DDD6FE' : '#5B339E';
    ctx.fill();
  });

  // Micro-Turbine Housing & Rotating 6-Blade Rotor
  ctx.save();
  ctx.translate(cx, turbY);
  ctx.beginPath();
  ctx.arc(0, 0, turbR, 0, Math.PI * 2);
  ctx.fillStyle = '#120829';
  ctx.fill();
  ctx.lineWidth = Math.max(1, 0.0028 * S);
  ctx.strokeStyle = '#A78BFA';
  ctx.stroke();

  ctx.save();
  ctx.rotate(turbineAngle);
  for (let b = 0; b < 6; b++) {
    ctx.save();
    ctx.rotate((b * Math.PI * 2) / 6);
    roundRectPath(-0.0028 * S, -turbR * 0.72, 0.0056 * S, turbR * 0.56, 0.0028 * S);
    ctx.fillStyle = b % 2 === 0 ? '#DDD6FE' : '#8B5CF6';
    ctx.fill();
    ctx.restore();
  }
  ctx.restore();

  ctx.beginPath();
  ctx.arc(0, 0, 0.0065 * S, 0, Math.PI * 2);
  ctx.fillStyle = '#F5F3FF';
  ctx.fill();
  ctx.restore();

  // D. Three Lower Dividend Vessels (Cash, Reinvest, Reserve — Evenly Spaced)
  const vesselY = cy + 0.205 * S;
  const vesselW = 0.132 * S;
  const vesselH = 0.122 * S;
  const vesselOffsets = [-0.164 * S, 0, 0.164 * S];
  const vesselPalettes = [
    ['#C4B5FD', '#7C3AED', '#F5F3FF'],
    ['#A78BFA', '#6D28D9', '#EDE9FE'],
    ['#8B5CF6', '#5B21B6', '#DDD6FE'],
  ];

  for (let v = 0; v < 3; v++) {
    drawVessel(
      cx + vesselOffsets[v],
      vesselY,
      vesselW,
      vesselH,
      bucketFills[v],
      vesselPalettes[v][0],
      vesselPalettes[v][1],
      vesselPalettes[v][2],
      false,
      0,
      0
    );
  }
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const S = minSide;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const easeInOutCubic = (x) => {
    const v = clamp01(x);
    return v < 0.5 ? 4 * v * v * v : 1 - Math.pow(-2 * v + 2, 3) / 2;
  };
  const easeOutCubic = (x) => {
    const v = clamp01(x);
    return 1 - Math.pow(1 - v, 3);
  };
  const easeInOutSine = (x) => {
    const v = clamp01(x);
    return -(Math.cos(Math.PI * v) - 1) * 0.5;
  };
  const lerp = (a, b, k) => a + (b - a) * k;

  const hexToRgb = (hex) => {
    const h = hex.replace('#', '');
    return [
      parseInt(h.slice(0, 2), 16),
      parseInt(h.slice(2, 4), 16),
      parseInt(h.slice(4, 6), 16),
    ];
  };
  const lerpColor = (c1, c2, k) => {
    const tK = clamp01(k);
    const a = hexToRgb(c1);
    const b = hexToRgb(c2);
    const r = Math.round(lerp(a[0], b[0], tK));
    const g = Math.round(lerp(a[1], b[1], tK));
    const bl = Math.round(lerp(a[2], b[2], tK));
    return `rgb(${r},${g},${bl})`;
  };

  const getThermalColor = (lvl) => {
    if (lvl <= 0.5) return lerpColor('#38BDF8', '#FBBF24', lvl * 2);
    return lerpColor('#FBBF24', '#F43F5E', (lvl - 0.5) * 2);
  };

  const roundRectPath = (x, y, w, h, r) => {
    const rad = Math.max(0, Math.min(r, w * 0.5, h * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  };

  // 1. Clean Modern Dark Aesthetic Gradient Background (Matte Graphite, Zero Glow, Zero Borders)
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, '#0D0F14');
  bgGrad.addColorStop(0.5, '#151923');
  bgGrad.addColorStop(1, '#1E2433');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // 2. Global Seamless Motion Parameters Driven by t, loopT, currentScene, sceneProgress
  const loopNorm = loopT / duration;
  const wavePhase = loopNorm * Math.PI * 2 * 6;

  let thermalLevel = 0.26; // 0..1 across stem
  let valveLift = 0; // 0..1 top relief cap slight rise
  let vaporProgress = 0; // 0..1 pressure release arcs in Scene 2
  let stabilityScore = 0.55;
  let purchasingPower = 0.78;
  let conduitFlow = 0.30;

  if (currentScene === 0) {
    // Scene 0 (0-5s): Cool Cyan baseline warms steadily toward Saffron inflation zone
    const k = easeInOutCubic(sceneProgress);
    thermalLevel = lerp(0.26, 0.58, k);
    valveLift = 0;
    vaporProgress = 0;
    stabilityScore = lerp(0.55, 0.72, easeInOutSine(sceneProgress));
    purchasingPower = lerp(0.78, 0.54, k);
    conduitFlow = 0.30 + 0.40 * easeInOutSine(sceneProgress);
  } else if (currentScene === 1) {
    // Scene 1 (5-10s): Inflation overheat surge up to 88% Crimson peak
    const k = easeInOutCubic(sceneProgress / 0.85);
    thermalLevel = lerp(0.58, 0.88, k);
    valveLift = easeInOutCubic((sceneProgress - 0.75) / 0.25) * 0.45;
    vaporProgress = 0;
    stabilityScore = lerp(0.72, 0.26, k);
    purchasingPower = lerp(0.54, 0.24, k);
    conduitFlow = 0.85;
  } else if (currentScene === 2) {
    // Scene 2 (10-15s): Pressure-relief valve opens & stabilizes temperature into optimal 54% balance
    const k = easeInOutCubic(sceneProgress / 0.72);
    thermalLevel = lerp(0.88, 0.50, k);
    valveLift = lerp(0.45, 1.0, easeOutCubic(sceneProgress / 0.22)) * (1 - easeInOutCubic((sceneProgress - 0.75) / 0.25));
    vaporProgress = clamp01((sceneProgress - 0.06) / 0.82);
    stabilityScore = lerp(0.26, 0.96, easeInOutCubic(sceneProgress / 0.78));
    purchasingPower = lerp(0.24, 0.86, easeInOutCubic(sceneProgress / 0.78));
    conduitFlow = 0.92;
  } else {
    // Scene 3 (15-20s): Controlled cooling back to exact t = 0 baseline
    const k = easeInOutCubic(sceneProgress / 0.88);
    thermalLevel = lerp(0.50, 0.26, k);
    valveLift = 0;
    vaporProgress = 0;
    stabilityScore = lerp(0.96, 0.55, k);
    purchasingPower = lerp(0.86, 0.78, k);
    conduitFlow = lerp(0.92, 0.30, k);
  }

  const activeCol = getThermalColor(thermalLevel);

  // 3. Grounding Pedestal Pill Beneath Thermometer Bulb (Strictly Separated)
  ctx.save();
  const pedW = 0.36 * S;
  const pedH = 0.018 * S;
  const pedY = cy + 0.314 * S;
  roundRectPath(cx - pedW * 0.5, pedY, pedW, pedH, pedH * 0.5);
  ctx.fillStyle = '#0A0C11';
  ctx.fill();
  ctx.lineWidth = Math.max(1, 0.0022 * S);
  ctx.strokeStyle = '#334155';
  ctx.stroke();
  ctx.restore();

  // 4. Precision Conduit Buses (Strictly Clear of Badge [cx+0.222*S], Scales [cx-0.095*S], and Cards [+/-0.44*S])
  const drawConduit = (xStart, xEnd, active) => {
    ctx.save();
    const yRail = cy;
    const termR = 0.0075 * S;
    const railH = 0.009 * S;
    const padX = 0.011 * S;

    roundRectPath(xStart, yRail - railH * 0.5, xEnd - xStart, railH, railH * 0.5);
    ctx.fillStyle = '#0B0E14';
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.002 * S);
    ctx.strokeStyle = '#334155';
    ctx.stroke();

    [xStart, xEnd].forEach((tx) => {
      ctx.beginPath();
      ctx.arc(tx, yRail, termR, 0, Math.PI * 2);
      ctx.fillStyle = '#181E2B';
      ctx.fill();
      ctx.lineWidth = Math.max(1, 0.0024 * S);
      ctx.strokeStyle = active > 0.4 ? activeCol : '#475569';
      ctx.stroke();
    });

    const innerStart = xStart + padX;
    const innerEnd = xEnd - padX;
    const span = innerEnd - innerStart;
    if (span > 0 && active > 0.02) {
      ctx.save();
      roundRectPath(innerStart, yRail - railH * 0.42, span, railH * 0.84, railH * 0.42);
      ctx.clip();

      const pktW = 0.020 * S;
      const cycles = 4;
      for (let i = 0; i < 2; i++) {
        const ph = (loopNorm * cycles + i * 0.5) % 1;
        const px = innerStart - pktW + ph * (span + pktW);
        ctx.globalAlpha = clamp01(active * Math.sin(ph * Math.PI) * 1.2);
        roundRectPath(px, yRail - railH * 0.34, pktW, railH * 0.68, railH * 0.34);
        ctx.fillStyle = activeCol;
        ctx.fill();
      }
      ctx.restore();
    }
    ctx.restore();
  };

  drawConduit(cx - 0.422 * S, cx - 0.268 * S, conduitFlow);
  drawConduit(cx + 0.268 * S, cx + 0.422 * S, conduitFlow);

  // 5. Left Telemetry Card — Thermal Zone Index & Purchasing Power Bar
  const drawLeftCard = () => {
    const cardW = 0.24 * S;
    const cardH = 0.34 * S;
    const cardX = cx - 0.56 * S - cardW * 0.5;
    const cardY = cy - cardH * 0.5;
    const cardR = 0.024 * S;

    ctx.save();
    roundRectPath(cardX, cardY, cardW, cardH, cardR);
    const cardGrad = ctx.createLinearGradient(cardX, cardY, cardX, cardY + cardH);
    cardGrad.addColorStop(0, '#1D2331');
    cardGrad.addColorStop(1, '#10141D');
    ctx.fillStyle = cardGrad;
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.003 * S);
    ctx.strokeStyle = '#334155';
    ctx.stroke();

    // Top Half: 3-Zone Vertical Thermal Scale (Overheat / Optimal / Cool) + Smooth Cursor
    const barX = cardX + 0.038 * S;
    const barW = 0.024 * S;
    const zoneTop = cardY + 0.036 * S;
    const zoneTotalH = 0.140 * S;
    const zoneGap = 0.008 * S;
    const segH = (zoneTotalH - zoneGap * 2) / 3;
    const zoneCols = ['#F43F5E', '#FBBF24', '#38BDF8'];

    for (let z = 0; z < 3; z++) {
      const zy = zoneTop + z * (segH + zoneGap);
      roundRectPath(barX, zy, barW, segH, barW * 0.4);
      ctx.fillStyle = zoneCols[z];
      ctx.fill();
    }

    // Horizontal indicator tracks & sliding pointer aligned cleanly right of vertical zones
    const cursorY = lerp(zoneTop + zoneTotalH - 0.008 * S, zoneTop + 0.008 * S, clamp01(thermalLevel));
    const ptrX = barX + barW + 0.016 * S;
    const trackW = cardW - 0.114 * S;

    // 3 Reference level bars
    for (let r = 0; r < 3; r++) {
      const ry = zoneTop + r * (segH + zoneGap) + segH * 0.5 - 0.003 * S;
      roundRectPath(ptrX + 0.020 * S, ry, trackW - 0.020 * S, 0.006 * S, 0.003 * S);
      ctx.fillStyle = '#262F42';
      ctx.fill();
    }

    // Active pointer pill + arrow
    ctx.beginPath();
    ctx.moveTo(ptrX, cursorY);
    ctx.lineTo(ptrX + 0.012 * S, cursorY - 0.008 * S);
    ctx.lineTo(ptrX + 0.012 * S, cursorY + 0.008 * S);
    ctx.closePath();
    ctx.fillStyle = activeCol;
    ctx.fill();

    roundRectPath(ptrX + 0.018 * S, cursorY - 0.006 * S, trackW - 0.018 * S, 0.012 * S, 0.006 * S);
    ctx.fillStyle = activeCol;
    ctx.fill();

    // Divider
    const divY = cardY + 0.200 * S;
    roundRectPath(cardX + 0.036 * S, divY, cardW - 0.072 * S, 0.0025 * S, 0.00125 * S);
    ctx.fillStyle = '#2B3548';
    ctx.fill();

    // Bottom Half: Purchasing Power Bar (Inversely Tracks Inflation Pressure)
    const pBarX = cardX + 0.032 * S;
    const pBarW = cardW - 0.064 * S;
    const pBarY = cardY + 0.236 * S;
    const pBarH = 0.018 * S;

    // Small decorative header bars above Purchasing Power meter
    roundRectPath(pBarX, pBarY, pBarW * 0.55, 0.008 * S, 0.004 * S);
    ctx.fillStyle = '#94A3B8';
    ctx.fill();

    const meterY = pBarY + 0.024 * S;
    roundRectPath(pBarX, meterY, pBarW, pBarH, pBarH * 0.5);
    ctx.fillStyle = '#0A0D14';
    ctx.fill();

    const pCol = lerpColor('#F43F5E', '#34D399', purchasingPower);
    roundRectPath(pBarX, meterY, Math.max(pBarH, pBarW * clamp01(purchasingPower)), pBarH, pBarH * 0.5);
    ctx.fillStyle = pCol;
    ctx.fill();

    ctx.restore();
  };

  drawLeftCard();

  // 6. Right Telemetry Card — Economic Equilibrium Gauge & Thermal Waveform
  const drawRightCard = () => {
    const cardW = 0.24 * S;
    const cardH = 0.34 * S;
    const cardX = cx + 0.56 * S - cardW * 0.5;
    const cardY = cy - cardH * 0.5;
    const cardR = 0.024 * S;

    ctx.save();
    roundRectPath(cardX, cardY, cardW, cardH, cardR);
    const cardGrad = ctx.createLinearGradient(cardX, cardY, cardX, cardY + cardH);
    cardGrad.addColorStop(0, '#1D2331');
    cardGrad.addColorStop(1, '#10141D');
    ctx.fillStyle = cardGrad;
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.003 * S);
    ctx.strokeStyle = '#334155';
    ctx.stroke();

    // Top Half: Circular Equilibrium Score Ring
    const rCx = cardX + cardW * 0.5;
    const rCy = cardY + 0.098 * S;
    const rRad = 0.056 * S;
    const rLW = 0.012 * S;

    ctx.beginPath();
    ctx.arc(rCx, rCy, rRad, 0, Math.PI * 2);
    ctx.lineWidth = rLW;
    ctx.strokeStyle = '#0A0D14';
    ctx.stroke();

    const eqCol = lerpColor('#F43F5E', '#34D399', stabilityScore);
    const startA = -Math.PI * 0.5;
    const endA = startA + Math.PI * 2 * clamp01(stabilityScore);
    ctx.beginPath();
    ctx.arc(rCx, rCy, rRad, startA, endA);
    ctx.lineWidth = rLW;
    ctx.lineCap = 'round';
    ctx.strokeStyle = eqCol;
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(rCx + Math.cos(endA) * rRad, rCy + Math.sin(endA) * rRad, 0.008 * S, 0, Math.PI * 2);
    ctx.fillStyle = '#F8FAFC';
    ctx.fill();

    // Equilibrium '=' Balance Symbol Inside Ring
    ctx.save();
    ctx.translate(rCx, rCy);
    roundRectPath(-0.016 * S, -0.009 * S, 0.032 * S, 0.006 * S, 0.003 * S);
    ctx.fillStyle = eqCol;
    ctx.fill();
    roundRectPath(-0.016 * S, 0.003 * S, 0.032 * S, 0.006 * S, 0.003 * S);
    ctx.fill();
    ctx.restore();

    // Divider
    const divY = cardY + 0.178 * S;
    roundRectPath(cardX + 0.036 * S, divY, cardW - 0.072 * S, 0.0025 * S, 0.00125 * S);
    ctx.fillStyle = '#2B3548';
    ctx.fill();

    // Bottom Half: Clipped Economic Pressure Waveform Monitor
    const wBoxX = cardX + 0.026 * S;
    const wBoxY = cardY + 0.200 * S;
    const wBoxW = cardW - 0.052 * S;
    const wBoxH = 0.110 * S;

    ctx.save();
    roundRectPath(wBoxX, wBoxY, wBoxW, wBoxH, 0.014 * S);
    ctx.fillStyle = '#0A0D14';
    ctx.fill();
    ctx.clip();

    // Center axis baseline
    ctx.strokeStyle = '#1E2738';
    ctx.lineWidth = Math.max(1, 0.0016 * S);
    ctx.beginPath();
    ctx.moveTo(wBoxX + 0.008 * S, wBoxY + wBoxH * 0.5);
    ctx.lineTo(wBoxX + wBoxW - 0.008 * S, wBoxY + wBoxH * 0.5);
    ctx.stroke();

    const amp = (0.012 + 0.024 * clamp01((thermalLevel - 0.2) / 0.7)) * S;
    const steps = 28;
    ctx.beginPath();
    for (let i = 0; i <= steps; i++) {
      const u = i / steps;
      const wx = lerp(wBoxX + 0.010 * S, wBoxX + wBoxW - 0.010 * S, u);
      const env = Math.sin(u * Math.PI);
      const wy = wBoxY + wBoxH * 0.5 + Math.sin(u * Math.PI * 4 - wavePhase) * amp * env;
      if (i === 0) ctx.moveTo(wx, wy);
      else ctx.lineTo(wx, wy);
    }
    ctx.lineWidth = Math.max(1, 0.0034 * S);
    ctx.lineCap = 'round';
    ctx.strokeStyle = activeCol;
    ctx.stroke();

    ctx.restore();
    ctx.restore();
  };

  drawRightCard();

  // 7. Hero Centerpiece — Seamless Unified Analytical Thermometer
  const bulbCy = cy + 0.175 * S;
  const stemTopY = cy - 0.200 * S;
  const rOut = 0.102 * S;
  const halfWOut = 0.056 * S;
  const rIn = 0.074 * S;
  const halfWIn = 0.036 * S;

  const traceThermometerPath = (halfW, rBulb) => {
    const dy = Math.sqrt(rBulb * rBulb - halfW * halfW);
    const angRight = Math.atan2(-dy, halfW);
    const angLeft = Math.atan2(-dy, -halfW);

    ctx.beginPath();
    ctx.arc(cx, stemTopY, halfW, Math.PI, 0, false);
    ctx.lineTo(cx + halfW, bulbCy - dy);
    ctx.arc(cx, bulbCy, rBulb, angRight, angLeft, false);
    ctx.lineTo(cx - halfW, stemTopY);
    ctx.closePath();
  };

  // A. Exterior Precision Calibration Scale Ticks (Strictly left of stem outer border at cx - 0.056*S)
  ctx.save();
  const tickCount = 9;
  const scaleTop = cy - 0.185 * S;
  const scaleBot = cy + 0.065 * S;
  for (let i = 0; i < tickCount; i++) {
    const frac = 1 - i / (tickCount - 1); // 1 at top, 0 at bottom
    const ty = lerp(scaleBot, scaleTop, frac);
    const isMajor = i % 2 === 0;
    const tLen = (isMajor ? 0.026 : 0.015) * S;
    const txRight = cx - halfWOut - 0.014 * S;
    const isLit = thermalLevel >= frac - 0.04;

    ctx.beginPath();
    ctx.moveTo(txRight - tLen, ty);
    ctx.lineTo(txRight, ty);
    ctx.lineWidth = Math.max(1, (isMajor ? 0.0032 : 0.0022) * S);
    ctx.lineCap = 'round';
    ctx.strokeStyle = isLit ? getThermalColor(frac) : '#3B4861';
    ctx.stroke();
  }
  ctx.restore();

  // B. Top Pressure-Relief Cap & Rising Geometric Vapor Rings (Scene 2)
  const capW = 0.068 * S;
  const capH = 0.014 * S;
  const capTopY = stemTopY - halfWOut - capH - 0.006 * S - valveLift * 0.014 * S;
  roundRectPath(cx - capW * 0.5, capTopY, capW, capH, capH * 0.45);
  ctx.fillStyle = '#475569';
  ctx.fill();
  ctx.lineWidth = Math.max(1, 0.0022 * S);
  ctx.strokeStyle = valveLift > 0.15 ? '#FBBF24' : '#94A3B8';
  ctx.stroke();

  // Expanding clean vapor arc rings above cap during Scene 2 pressure release
  if (vaporProgress > 0.02 && vaporProgress < 0.98) {
    for (let v = 0; v < 2; v++) {
      const vp = clamp01((vaporProgress - v * 0.22) / 0.72);
      if (vp > 0.01 && vp < 0.99) {
        const vy = capTopY - 0.016 * S - vp * 0.068 * S;
        const vw = (0.022 + vp * 0.036) * S;
        ctx.save();
        ctx.globalAlpha = Math.sin(vp * Math.PI) * 0.75;
        ctx.beginPath();
        ctx.moveTo(cx - vw, vy + 0.006 * S);
        ctx.quadraticCurveTo(cx, vy - 0.008 * S, cx + vw, vy + 0.006 * S);
        ctx.lineWidth = Math.max(1, 0.0032 * S);
        ctx.lineCap = 'round';
        ctx.strokeStyle = '#94A3B8';
        ctx.stroke();
        ctx.restore();
      }
    }
  }

  // C. Outer Thermometer Slate-Silver Body
  ctx.save();
  traceThermometerPath(halfWOut, rOut);
  const bodyGrad = ctx.createLinearGradient(cx - rOut, cy, cx + rOut, cy);
  bodyGrad.addColorStop(0, '#334155');
  bodyGrad.addColorStop(0.5, '#475569');
  bodyGrad.addColorStop(1, '#1E293B');
  ctx.fillStyle = bodyGrad;
  ctx.fill();
  ctx.lineWidth = Math.max(1, 0.0038 * S);
  ctx.strokeStyle = '#94A3B8';
  ctx.stroke();

  // D. Inner Glass Chamber (Clipped Seamlessly)
  ctx.save();
  traceThermometerPath(halfWIn, rIn);
  ctx.fillStyle = '#0B0E15';
  ctx.fill();
  ctx.clip();

  const meniscusY = lerp(cy + 0.075 * S, cy - 0.185 * S, clamp01(thermalLevel));
  const chamberBot = bulbCy + rIn + 0.01 * S;
  const chamberTop = stemTopY - halfWIn;
  const waveAmp = 0.0045 * S;

  // Full vertical thermal spectrum gradient inside liquid chamber
  const liqGrad = ctx.createLinearGradient(cx, chamberBot, cx, cy - 0.185 * S);
  liqGrad.addColorStop(0, '#0284C7');
  liqGrad.addColorStop(0.28, '#38BDF8');
  liqGrad.addColorStop(0.60, '#FBBF24');
  liqGrad.addColorStop(1, '#F43F5E');

  const getWaveY = (px) => {
    const nx = (px - (cx - halfWIn)) / (halfWIn * 2);
    return meniscusY + Math.sin(nx * Math.PI * 2.5 + wavePhase) * waveAmp;
  };

  // Back liquid wave
  const wSteps = 22;
  ctx.beginPath();
  ctx.moveTo(cx - rIn, chamberBot);
  for (let i = 0; i <= wSteps; i++) {
    const px = lerp(cx - halfWIn, cx + halfWIn, i / wSteps);
    const py = meniscusY - 0.003 * S + Math.sin((i / wSteps) * Math.PI * 2.5 - wavePhase + 1.2) * (waveAmp * 0.75);
    ctx.lineTo(px, py);
  }
  ctx.lineTo(cx + rIn, chamberBot);
  ctx.closePath();
  ctx.fillStyle = 'rgba(255, 255, 255, 0.14)';
  ctx.fill();

  // Main front thermal liquid body (covers bulb + stem cleanly up to wave crest)
  ctx.beginPath();
  ctx.moveTo(cx - rIn - 0.01 * S, chamberBot);
  ctx.lineTo(cx - rIn - 0.01 * S, meniscusY);
  for (let i = 0; i <= wSteps; i++) {
    const px = lerp(cx - halfWIn, cx + halfWIn, i / wSteps);
    ctx.lineTo(px, getWaveY(px));
  }
  ctx.lineTo(cx + rIn + 0.01 * S, meniscusY);
  ctx.lineTo(cx + rIn + 0.01 * S, chamberBot);
  ctx.closePath();
  ctx.fillStyle = liqGrad;
  ctx.fill();

  // Crisp bright crest line at meniscus
  ctx.beginPath();
  for (let i = 0; i <= wSteps; i++) {
    const px = lerp(cx - halfWIn, cx + halfWIn, i / wSteps);
    const py = getWaveY(px);
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.lineWidth = Math.max(1, 0.0034 * S);
  ctx.strokeStyle = '#F8FAFC';
  ctx.stroke();

  // Rising micro-bubbles inside liquid bulb & column (strictly below meniscusY)
  for (let b = 0; b < 6; b++) {
    const cycles = (b % 2) + 2;
    const bProg = (loopNorm * cycles + b * 0.17) % 1;
    const bx = cx + ((b - 2.5) / 3) * (halfWIn * 0.65);
    const topLim = getWaveY(bx) + 0.014 * S;
    const botLim = bulbCy + rIn * 0.65;
    if (botLim > topLim) {
      const by = lerp(botLim, topLim, bProg);
      ctx.save();
      ctx.globalAlpha = Math.sin(bProg * Math.PI) * 0.68;
      ctx.beginPath();
      ctx.arc(bx, by, (0.003 + (b % 2) * 0.0014) * S, 0, Math.PI * 2);
      ctx.fillStyle = '#F8FAFC';
      ctx.fill();
      ctx.restore();
    }
  }

  // Subtle vertical specular glass highlight along left interior
  ctx.save();
  ctx.globalAlpha = 0.12;
  roundRectPath(cx - halfWIn + 0.007 * S, chamberTop + 0.025 * S, 0.007 * S, (bulbCy - chamberTop) * 0.85, 0.0035 * S);
  ctx.fillStyle = '#F8FAFC';
  ctx.fill();
  ctx.restore();

  ctx.restore(); // End inner chamber clip

  // Inner chamber crisp rim border
  traceThermometerPath(halfWIn, rIn);
  ctx.lineWidth = Math.max(1, 0.0024 * S);
  ctx.strokeStyle = '#64748B';
  ctx.stroke();
  ctx.restore();

  // 8. Floating Reactive Callout Badge Right of Stem (Strictly Clear of Stem, Bulb & Right Conduit!)
  const badgeY = Math.max(cy - 0.175 * S, Math.min(cy + 0.045 * S, meniscusY));
  const badgeX = cx + 0.175 * S;
  const badgeW = 0.092 * S;
  const badgeH = 0.068 * S;

  ctx.save();
  // Detached pointer chevron between stem (+0.056*S) and badge (+0.129*S)
  ctx.beginPath();
  ctx.moveTo(cx + 0.094 * S, badgeY);
  ctx.lineTo(cx + 0.112 * S, badgeY - 0.011 * S);
  ctx.lineTo(cx + 0.112 * S, badgeY + 0.011 * S);
  ctx.closePath();
  ctx.fillStyle = activeCol;
  ctx.fill();

  // Badge pill
  roundRectPath(badgeX - badgeW * 0.5, badgeY - badgeH * 0.5, badgeW, badgeH, 0.016 * S);
  ctx.fillStyle = '#141925';
  ctx.fill();
  ctx.lineWidth = Math.max(1, 0.0032 * S);
  ctx.strokeStyle = activeCol;
  ctx.stroke();

  // Reactive Vector Icon Inside Badge Based on Economic Pressure Zone
  ctx.save();
  ctx.translate(badgeX, badgeY);
  ctx.strokeStyle = activeCol;
  ctx.fillStyle = activeCol;
  ctx.lineWidth = Math.max(1, 0.004 * S);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  if (thermalLevel < 0.40) {
    // Cool / Deflation Zone: Calm flat horizontal wave / steady bars
    ctx.beginPath();
    ctx.moveTo(-0.020 * S, 0);
    ctx.quadraticCurveTo(-0.010 * S, -0.009 * S, 0, 0);
    ctx.quadraticCurveTo(0.010 * S, 0.009 * S, 0.020 * S, 0);
    ctx.stroke();
  } else if (thermalLevel > 0.68) {
    // Overheat / Inflation Zone: Alert exclamation mark + rising arrow accent
    ctx.beginPath();
    ctx.moveTo(-0.012 * S, -0.014 * S);
    ctx.lineTo(-0.012 * S, 0.004 * S);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(-0.012 * S, 0.014 * S, 0.003 * S, 0, Math.PI * 2);
    ctx.fill();

    // Upward spike arrow beside it
    ctx.beginPath();
    ctx.moveTo(0.012 * S, 0.014 * S);
    ctx.lineTo(0.012 * S, -0.014 * S);
    ctx.moveTo(0.003 * S, -0.004 * S);
    ctx.lineTo(0.012 * S, -0.014 * S);
    ctx.lineTo(0.021 * S, -0.004 * S);
    ctx.stroke();
  } else {
    // Optimal / Balanced Zone: Crisp vector checkmark
    ctx.beginPath();
    ctx.moveTo(-0.018 * S, 0.002 * S);
    ctx.lineTo(-0.004 * S, 0.014 * S);
    ctx.lineTo(0.018 * S, -0.012 * S);
    ctx.stroke();
  }

  ctx.restore();
  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const S = minSide;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const easeInOutCubic = (x) => {
    const v = clamp01(x);
    return v < 0.5 ? 4 * v * v * v : 1 - Math.pow(-2 * v + 2, 3) / 2;
  };
  const easeOutCubic = (x) => {
    const v = clamp01(x);
    return 1 - Math.pow(1 - v, 3);
  };
  const easeInOutSine = (x) => {
    const v = clamp01(x);
    return -(Math.cos(Math.PI * v) - 1) * 0.5;
  };
  const lerp = (a, b, k) => a + (b - a) * k;

  const hexToRgb = (hex) => {
    const h = hex.replace('#', '');
    return [
      parseInt(h.slice(0, 2), 16),
      parseInt(h.slice(2, 4), 16),
      parseInt(h.slice(4, 6), 16),
    ];
  };
  const lerpColor = (c1, c2, k) => {
    const tK = clamp01(k);
    const a = hexToRgb(c1);
    const b = hexToRgb(c2);
    const r = Math.round(lerp(a[0], b[0], tK));
    const g = Math.round(lerp(a[1], b[1], tK));
    const bl = Math.round(lerp(a[2], b[2], tK));
    return `rgb(${r},${g},${bl})`;
  };

  const roundRectPath = (x, y, w, h, r) => {
    const rad = Math.max(0, Math.min(r, w * 0.5, h * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  };

  // 1. Clean Modern Dark Aesthetic Gradient Background (Abyssal Slate-Blue, Zero Glow, Zero Borders)
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, '#030D17');
  bgGrad.addColorStop(0.5, '#071B2E');
  bgGrad.addColorStop(1, '#0B2742');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // 2. Global Seamless Motion Parameters Driven by t, loopT, currentScene, sceneProgress
  const loopNorm = loopT / duration;
  const sweepAngle = -Math.PI * 0.5 + loopNorm * Math.PI * 2 * 4; // Exact 4 smooth revolutions over 20s

  let volatilityLevel = 0; // 0 = calm aqua, 1 = peak volatility
  let shieldPower = 0; // 0 = off, 1 = active overhead dome & stabilized bull trend
  let shieldCheck = 0;
  let stabilityRatio = 0.42;
  let conduitFlow = 0.25;
  let candleTrend = 0; // 0 = calm baseline, 1 = stabilized bullish uptrend

  if (currentScene === 0) {
    // Scene 0 (0-5s): Radar calibration & calm baseline market scan
    volatilityLevel = easeInOutSine((sceneProgress - 0.35) / 0.65) * 0.35;
    shieldPower = 0;
    shieldCheck = 0;
    stabilityRatio = lerp(0.42, 0.48, easeInOutSine(sceneProgress));
    conduitFlow = 0.25 + 0.35 * easeInOutSine(sceneProgress);
    candleTrend = 0.15 * easeInOutSine(sceneProgress);
  } else if (currentScene === 1) {
    // Scene 1 (5-10s): Market volatility rises smoothly, alert indicators activate
    volatilityLevel = lerp(0.35, 1.0, easeInOutCubic(sceneProgress / 0.72));
    shieldPower = easeInOutCubic((sceneProgress - 0.70) / 0.30) * 0.35;
    shieldCheck = 0;
    stabilityRatio = lerp(0.48, 0.28, easeInOutSine(sceneProgress / 0.65));
    conduitFlow = 0.85;
    candleTrend = lerp(0.15, 0.0, easeInOutSine(sceneProgress / 0.5));
  } else if (currentScene === 2) {
    // Scene 2 (10-15s): Protective stabilizer dome activates, shield check verified, bull trend stabilized
    const stabK = easeInOutCubic(sceneProgress / 0.55);
    volatilityLevel = lerp(1.0, 0.05, stabK);
    shieldPower = lerp(0.35, 1.0, easeOutCubic(sceneProgress / 0.42));
    shieldCheck = easeInOutCubic((sceneProgress - 0.18) / 0.52);
    stabilityRatio = lerp(0.28, 0.96, stabK);
    conduitFlow = 0.92;
    candleTrend = lerp(0.0, 1.0, stabK);
  } else {
    // Scene 3 (15-20s): Controlled stand-down back to exact t = 0 baseline
    const resetK = easeInOutCubic(sceneProgress / 0.88);
    volatilityLevel = lerp(0.05, 0.0, resetK);
    shieldPower = lerp(1.0, 0.0, easeInOutCubic(sceneProgress / 0.72));
    shieldCheck = 1 - easeInOutCubic(sceneProgress / 0.36);
    stabilityRatio = lerp(0.96, 0.42, resetK);
    conduitFlow = lerp(0.92, 0.25, resetK);
    candleTrend = lerp(1.0, 0.0, resetK);
  }

  // 3. Grounding Pedestal Pill Beneath Radar Scope (Strictly Separated)
  ctx.save();
  const pedW = 0.42 * S;
  const pedH = 0.018 * S;
  const pedY = cy + 0.318 * S;
  roundRectPath(cx - pedW * 0.5, pedY, pedW, pedH, pedH * 0.5);
  ctx.fillStyle = '#030A13';
  ctx.fill();
  ctx.lineWidth = Math.max(1, 0.0022 * S);
  ctx.strokeStyle = '#154463';
  ctx.stroke();
  ctx.restore();

  // 4. Precision Conduit Buses (Strictly Clear of Radar Bezel +/-0.285*S and Cards +/-0.445*S)
  const drawConduit = (xStart, xEnd, active) => {
    ctx.save();
    const yRail = cy;
    const termR = 0.0075 * S;
    const railH = 0.009 * S;
    const padX = 0.011 * S;

    roundRectPath(xStart, yRail - railH * 0.5, xEnd - xStart, railH, railH * 0.5);
    ctx.fillStyle = '#051424';
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.002 * S);
    ctx.strokeStyle = '#164A6E';
    ctx.stroke();

    const activeAccent = volatilityLevel > 0.55 ? '#F59E0B' : shieldPower > 0.4 ? '#4ADE80' : '#22D3EE';

    [xStart, xEnd].forEach((tx) => {
      ctx.beginPath();
      ctx.arc(tx, yRail, termR, 0, Math.PI * 2);
      ctx.fillStyle = '#0A2238';
      ctx.fill();
      ctx.lineWidth = Math.max(1, 0.0024 * S);
      ctx.strokeStyle = active > 0.35 ? activeAccent : '#1D5E87';
      ctx.stroke();
    });

    const innerStart = xStart + padX;
    const innerEnd = xEnd - padX;
    const span = innerEnd - innerStart;
    if (span > 0 && active > 0.02) {
      ctx.save();
      roundRectPath(innerStart, yRail - railH * 0.42, span, railH * 0.84, railH * 0.42);
      ctx.clip();

      const pktW = 0.022 * S;
      const cycles = 4;
      for (let i = 0; i < 2; i++) {
        const ph = (loopNorm * cycles + i * 0.5) % 1;
        const px = innerStart - pktW + ph * (span + pktW);
        ctx.globalAlpha = clamp01(active * Math.sin(ph * Math.PI) * 1.2);
        roundRectPath(px, yRail - railH * 0.34, pktW, railH * 0.68, railH * 0.34);
        ctx.fillStyle = activeAccent;
        ctx.fill();
      }
      ctx.restore();
    }
    ctx.restore();
  };

  drawConduit(cx - 0.425 * S, cx - 0.308 * S, conduitFlow);
  drawConduit(cx + 0.308 * S, cx + 0.425 * S, conduitFlow);

  // 5. Left Telemetry Card — Volatility Meter & Market Signal Bars
  const drawLeftCard = () => {
    const cardW = 0.24 * S;
    const cardH = 0.34 * S;
    const cardX = cx - 0.565 * S - cardW * 0.5;
    const cardY = cy - cardH * 0.5;
    const cardR = 0.024 * S;

    ctx.save();
    roundRectPath(cardX, cardY, cardW, cardH, cardR);
    const cardGrad = ctx.createLinearGradient(cardX, cardY, cardX, cardY + cardH);
    cardGrad.addColorStop(0, '#0B2339');
    cardGrad.addColorStop(1, '#051321');
    ctx.fillStyle = cardGrad;
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.003 * S);
    ctx.strokeStyle = '#1B557A';
    ctx.stroke();

    // Top Half: Volatility Pressure Gauge Bar + Needle
    const mCx = cardX + cardW * 0.5;
    const mCy = cardY + 0.126 * S;
    const mR = 0.068 * S;
    const mLW = 0.013 * S;

    ctx.beginPath();
    ctx.arc(mCx, mCy, mR, Math.PI, Math.PI * 2);
    ctx.lineWidth = mLW;
    ctx.lineCap = 'round';
    ctx.strokeStyle = '#040E1A';
    ctx.stroke();

    const meterFill = clamp01(0.18 + volatilityLevel * 0.72);
    const meterColor = lerpColor('#22D3EE', '#FB7185', volatilityLevel);
    ctx.beginPath();
    ctx.arc(mCx, mCy, mR, Math.PI, Math.PI + Math.PI * meterFill);
    ctx.lineWidth = mLW;
    ctx.lineCap = 'round';
    ctx.strokeStyle = meterColor;
    ctx.stroke();

    // Gauge needle
    const nAng = Math.PI + Math.PI * meterFill;
    ctx.save();
    ctx.translate(mCx, mCy);
    ctx.rotate(nAng);
    ctx.beginPath();
    ctx.moveTo(-0.006 * S, -0.0035 * S);
    ctx.lineTo(mR * 0.72, 0);
    ctx.lineTo(-0.006 * S, 0.0035 * S);
    ctx.closePath();
    ctx.fillStyle = '#E0F2FE';
    ctx.fill();
    ctx.restore();

    ctx.beginPath();
    ctx.arc(mCx, mCy, 0.010 * S, 0, Math.PI * 2);
    ctx.fillStyle = meterColor;
    ctx.fill();

    // Divider
    const divY = cardY + 0.168 * S;
    roundRectPath(cardX + 0.036 * S, divY, cardW - 0.072 * S, 0.0025 * S, 0.00125 * S);
    ctx.fillStyle = '#154463';
    ctx.fill();

    // Bottom Half: 4 Signal Pulse Vertical Equalizer Bars
    const chartLeft = cardX + 0.032 * S;
    const chartW = cardW - 0.064 * S;
    const chartBot = cardY + 0.304 * S;
    const maxH = 0.106 * S;
    const bGap = 0.014 * S;
    const bW = (chartW - bGap * 3) / 4;
    const barColor = shieldPower > 0.4 ? '#4ADE80' : volatilityLevel > 0.55 ? '#F59E0B' : '#22D3EE';

    for (let i = 0; i < 4; i++) {
      const bx = chartLeft + i * (bW + bGap);
      roundRectPath(bx, chartBot - maxH, bW, maxH, bW * 0.35);
      ctx.fillStyle = '#040E1A';
      ctx.fill();

      const osc = 0.5 + 0.5 * Math.sin(loopNorm * Math.PI * 2 * 4 - i * 1.1);
      const val = clamp01(0.32 + 0.42 * osc + 0.22 * candleTrend);
      const bh = Math.max(bW, maxH * val);
      roundRectPath(bx, chartBot - bh, bW, bh, bW * 0.35);
      ctx.fillStyle = barColor;
      ctx.fill();
    }

    ctx.restore();
  };

  drawLeftCard();

  // 6. Right Telemetry Card — Volatility Shield & Stability Index
  const drawRightCard = () => {
    const cardW = 0.24 * S;
    const cardH = 0.34 * S;
    const cardX = cx + 0.565 * S - cardW * 0.5;
    const cardY = cy - cardH * 0.5;
    const cardR = 0.024 * S;

    ctx.save();
    roundRectPath(cardX, cardY, cardW, cardH, cardR);
    const cardGrad = ctx.createLinearGradient(cardX, cardY, cardX, cardY + cardH);
    cardGrad.addColorStop(0, '#0B2339');
    cardGrad.addColorStop(1, '#051321');
    ctx.fillStyle = cardGrad;
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.003 * S);
    ctx.strokeStyle = '#1B557A';
    ctx.stroke();

    // Top Half: Security Shield Badge
    const shCx = cardX + cardW * 0.5;
    const shCy = cardY + 0.096 * S;
    const shW = 0.084 * S;
    const shH = 0.094 * S;

    const traceShield = () => {
      ctx.beginPath();
      ctx.moveTo(shCx, shCy - shH * 0.5);
      ctx.lineTo(shCx + shW * 0.5, shCy - shH * 0.30);
      ctx.lineTo(shCx + shW * 0.44, shCy + shH * 0.12);
      ctx.quadraticCurveTo(shCx + shW * 0.34, shCy + shH * 0.38, shCx, shCy + shH * 0.52);
      ctx.quadraticCurveTo(shCx - shW * 0.34, shCy + shH * 0.38, shCx - shW * 0.44, shCy + shH * 0.12);
      ctx.lineTo(shCx - shW * 0.5, shCy - shH * 0.30);
      ctx.closePath();
    };

    traceShield();
    const shActive = shieldPower > 0.25;
    const shGrad = ctx.createLinearGradient(shCx, shCy - shH * 0.5, shCx, shCy + shH * 0.5);
    shGrad.addColorStop(0, shActive ? '#065F46' : '#0B2C47');
    shGrad.addColorStop(1, shActive ? '#064E3B' : '#061B2E');
    ctx.fillStyle = shGrad;
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.0032 * S);
    ctx.strokeStyle = shActive ? '#4ADE80' : '#22D3EE';
    ctx.stroke();

    if (shieldCheck > 0.01) {
      const p1 = { x: shCx - shW * 0.20, y: shCy + shH * 0.02 };
      const p2 = { x: shCx - shW * 0.03, y: shCy + shH * 0.17 };
      const p3 = { x: shCx + shW * 0.22, y: shCy - shH * 0.13 };

      const l1 = Math.hypot(p2.x - p1.x, p2.y - p1.y);
      const l2 = Math.hypot(p3.x - p2.x, p3.y - p2.y);
      const drawL = (l1 + l2) * clamp01(shieldCheck);

      ctx.beginPath();
      ctx.moveTo(p1.x, p1.y);
      if (drawL <= l1) {
        const k = drawL / l1;
        ctx.lineTo(lerp(p1.x, p2.x, k), lerp(p1.y, p2.y, k));
      } else {
        ctx.lineTo(p2.x, p2.y);
        const k = (drawL - l1) / l2;
        ctx.lineTo(lerp(p2.x, p3.x, k), lerp(p2.y, p3.y, k));
      }
      ctx.lineWidth = Math.max(1, 0.0052 * S);
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.strokeStyle = '#86EFAC';
      ctx.stroke();
    } else {
      ctx.beginPath();
      ctx.arc(shCx, shCy, 0.0085 * S, 0, Math.PI * 2);
      ctx.fillStyle = volatilityLevel > 0.5 ? '#F59E0B' : '#22D3EE';
      ctx.fill();
    }

    // Divider
    const divY = cardY + 0.176 * S;
    roundRectPath(cardX + 0.036 * S, divY, cardW - 0.072 * S, 0.0025 * S, 0.00125 * S);
    ctx.fillStyle = '#154463';
    ctx.fill();

    // Bottom Half: Stability Progress Ring + Trending Bar
    const rCx = cardX + cardW * 0.5;
    const rCy = cardY + 0.254 * S;
    const rRad = 0.048 * S;
    const rLW = 0.011 * S;

    ctx.beginPath();
    ctx.arc(rCx, rCy, rRad, 0, Math.PI * 2);
    ctx.lineWidth = rLW;
    ctx.strokeStyle = '#040E1A';
    ctx.stroke();

    const ringCol = shieldPower > 0.35 ? '#4ADE80' : lerpColor('#22D3EE', '#F59E0B', volatilityLevel);
    const startA = -Math.PI * 0.5;
    const endA = startA + Math.PI * 2 * clamp01(stabilityRatio);
    ctx.beginPath();
    ctx.arc(rCx, rCy, rRad, startA, endA);
    ctx.lineWidth = rLW;
    ctx.lineCap = 'round';
    ctx.strokeStyle = ringCol;
    ctx.stroke();

    // Clean inner percentage bar pulse
    const barW = 0.040 * S;
    const barH = 0.009 * S;
    roundRectPath(rCx - barW * 0.5, rCy - barH * 0.5, barW, barH, barH * 0.5);
    ctx.fillStyle = '#0A2238';
    ctx.fill();
    roundRectPath(rCx - barW * 0.5, rCy - barH * 0.5, Math.max(barH, barW * stabilityRatio), barH, barH * 0.5);
    ctx.fillStyle = ringCol;
    ctx.fill();

    ctx.restore();
  };

  drawRightCard();

  // 7. Hero Centerpiece — Circular Market Pulse Radar & Candlestick Shield
  const outerR = 0.285 * S;
  const innerR = 0.258 * S;

  // Outer Radar Housing Ring
  ctx.save();
  ctx.beginPath();
  ctx.arc(cx, cy, outerR, 0, Math.PI * 2);
  const bezelGrad = ctx.createLinearGradient(cx - outerR, cy - outerR, cx + outerR, cy + outerR);
  bezelGrad.addColorStop(0, '#103452');
  bezelGrad.addColorStop(1, '#081C2E');
  ctx.fillStyle = bezelGrad;
  ctx.fill();
  ctx.lineWidth = Math.max(1, 0.004 * S);
  ctx.strokeStyle = shieldPower > 0.4 ? '#4ADE80' : '#22D3EE';
  ctx.stroke();

  // 24 Crisp Radial Degree Ticks on Outer Bezel Ring
  for (let i = 0; i < 24; i++) {
    const a = (i / 24) * Math.PI * 2;
    const r1 = innerR + 0.007 * S;
    const r2 = outerR - 0.007 * S;
    ctx.beginPath();
    ctx.moveTo(cx + Math.cos(a) * r1, cy + Math.sin(a) * r1);
    ctx.lineTo(cx + Math.cos(a) * r2, cy + Math.sin(a) * r2);
    ctx.lineWidth = Math.max(1, (i % 6 === 0 ? 0.0032 : 0.0018) * S);
    ctx.strokeStyle = i % 6 === 0 ? '#67E8F9' : '#1E5C85';
    ctx.stroke();
  }

  // Clipped Radar Interior Scope
  ctx.save();
  ctx.beginPath();
  ctx.arc(cx, cy, innerR, 0, Math.PI * 2);
  ctx.fillStyle = '#04101C';
  ctx.fill();
  ctx.clip();

  // Concentric Range Circles & Crosshair Axis
  ctx.strokeStyle = '#0E2E4A';
  ctx.lineWidth = Math.max(1, 0.0018 * S);
  [0.090 * S, 0.165 * S, 0.230 * S].forEach((rr) => {
    ctx.beginPath();
    ctx.arc(cx, cy, rr, 0, Math.PI * 2);
    ctx.stroke();
  });

  ctx.beginPath();
  ctx.moveTo(cx - innerR, cy);
  ctx.lineTo(cx + innerR, cy);
  ctx.moveTo(cx, cy - innerR);
  ctx.lineTo(cx, cy + innerR);
  ctx.stroke();

  // Smooth 360° Radar Sweep Sector Wedge (Subtle translucent sweep behind foreground icons)
  const sectorSpan = 0.65;
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(cx, cy);
  ctx.arc(cx, cy, innerR, sweepAngle - sectorSpan, sweepAngle);
  ctx.closePath();
  const sweepCol = shieldPower > 0.4 ? 'rgba(74, 222, 128, 0.16)' : volatilityLevel > 0.55 ? 'rgba(245, 158, 11, 0.16)' : 'rgba(34, 211, 238, 0.16)';
  ctx.fillStyle = sweepCol;
  ctx.fill();

  // Crisp leading sweep beam
  ctx.beginPath();
  ctx.moveTo(cx, cy);
  ctx.lineTo(cx + Math.cos(sweepAngle) * innerR, cy + Math.sin(sweepAngle) * innerR);
  ctx.lineWidth = Math.max(1, 0.0026 * S);
  ctx.strokeStyle = shieldPower > 0.4 ? 'rgba(134, 239, 172, 0.55)' : 'rgba(103, 232, 249, 0.55)';
  ctx.stroke();
  ctx.restore();

  // 4 Quadrant Signal Target Nodes at Outer Diagonal Corners (Strict clearance from candles!)
  const nodeDist = 0.196 * S;
  const normAngle = (a) => ((a % (Math.PI * 2)) + Math.PI * 2) % (Math.PI * 2);
  const sweepNorm = normAngle(sweepAngle);
  [Math.PI * 0.25, Math.PI * 0.75, Math.PI * 1.25, Math.PI * 1.75].forEach((na) => {
    const nx = cx + Math.cos(na) * nodeDist;
    const ny = cy + Math.sin(na) * nodeDist;
    const delta = normAngle(sweepNorm - na);
    const ping = delta < 1.2 ? 1 - delta / 1.2 : 0;

    if (ping > 0.02) {
      ctx.save();
      ctx.globalAlpha = ping * 0.65;
      ctx.beginPath();
      ctx.arc(nx, ny, (0.009 + (1 - ping) * 0.016) * S, 0, Math.PI * 2);
      ctx.lineWidth = Math.max(1, 0.002 * S);
      ctx.strokeStyle = shieldPower > 0.4 ? '#4ADE80' : '#22D3EE';
      ctx.stroke();
      ctx.restore();
    }

    ctx.beginPath();
    ctx.arc(nx, ny, 0.0065 * S, 0, Math.PI * 2);
    ctx.fillStyle = ping > 0.35 ? '#E0F2FE' : '#1E6088';
    ctx.fill();
  });

  // Protective Overhead Shield Dome Arc (Strictly above candlestick tops: radius 0.172*S in upper sector!)
  if (shieldPower > 0.01) {
    ctx.save();
    const arcCenterY = cy + 0.022 * S;
    const arcR = 0.174 * S;
    const halfSpan = 0.78 * shieldPower; // Expands smoothly symmetrically around -PI/2
    const midA = -Math.PI * 0.5;

    ctx.beginPath();
    ctx.arc(cx, arcCenterY, arcR, midA - halfSpan, midA + halfSpan);
    ctx.lineWidth = Math.max(1, 0.0065 * S);
    ctx.lineCap = 'round';
    ctx.strokeStyle = '#4ADE80';
    ctx.stroke();

    // Inner parallel subtle shield arc
    ctx.beginPath();
    ctx.arc(cx, arcCenterY, arcR - 0.014 * S, midA - halfSpan * 0.75, midA + halfSpan * 0.75);
    ctx.lineWidth = Math.max(1, 0.0025 * S);
    ctx.strokeStyle = '#86EFAC';
    ctx.stroke();
    ctx.restore();
  }

  // 7 Crisp Candlestick Bars Strictly Centered in Safe Band (y in [cy - 0.105*S, cy + 0.105*S])
  const cCount = 7;
  const cSpacing = 0.044 * S;
  const cStartX = cx - ((cCount - 1) * cSpacing) * 0.5;
  const cW = 0.022 * S;

  // Baseline calm vs volatile vs bullish uptrend profiles (center Y offsets in S units)
  const calmTop = [-0.015, -0.032, -0.020, -0.042, -0.028, -0.048, -0.056];
  const calmBot = [0.036, 0.022, 0.032, 0.014, 0.025, 0.008, -0.002];

  const volTop = [-0.048, 0.010, -0.068, 0.018, -0.072, -0.015, -0.058];
  const volBot = [0.020, 0.075, 0.006, 0.082, 0.012, 0.065, 0.022];

  const bullTop = [0.012, -0.004, -0.018, -0.034, -0.050, -0.066, -0.084];
  const bullBot = [0.062, 0.046, 0.032, 0.018, 0.002, -0.012, -0.028];

  for (let i = 0; i < cCount; i++) {
    const x = cStartX + i * cSpacing;
    const harmonic = Math.sin(loopNorm * Math.PI * 2 * 4 + i * 0.9) * (0.005 + 0.007 * volatilityLevel);

    const tCalm = lerp(calmTop[i], bullTop[i], candleTrend);
    const bCalm = lerp(calmBot[i], bullBot[i], candleTrend);

    const yTop = cy + (lerp(tCalm, volTop[i], volatilityLevel) + harmonic) * S;
    const yBot = cy + (lerp(bCalm, volBot[i], volatilityLevel) + harmonic * 0.6) * S;

    const wickTop = yTop - 0.016 * S;
    const wickBot = yBot + 0.016 * S;

    const isBearVol = volatilityLevel > 0.45 && (i === 1 || i === 3 || i === 5);
    const candleCol = isBearVol
      ? lerpColor('#22D3EE', '#FB7185', clamp01((volatilityLevel - 0.35) / 0.5))
      : lerpColor('#22D3EE', '#4ADE80', candleTrend);

    // Crisp Wick
    ctx.beginPath();
    ctx.moveTo(x, wickTop);
    ctx.lineTo(x, wickBot);
    ctx.lineWidth = Math.max(1, 0.0028 * S);
    ctx.lineCap = 'round';
    ctx.strokeStyle = candleCol;
    ctx.stroke();

    // Crisp Rounded Candlestick Body
    const bodyH = Math.max(0.018 * S, yBot - yTop);
    roundRectPath(x - cW * 0.5, yTop, cW, bodyH, 0.005 * S);
    ctx.fillStyle = candleCol;
    ctx.fill();
  }

  ctx.restore(); // End radar circle clip

  // Crisp Interior Radar Rim Stroke Over Clipped Scope
  ctx.beginPath();
  ctx.arc(cx, cy, innerR, 0, Math.PI * 2);
  ctx.lineWidth = Math.max(1, 0.003 * S);
  ctx.strokeStyle = '#1E5E88';
  ctx.stroke();

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const S = minSide;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const easeInOutCubic = (x) => {
    const v = clamp01(x);
    return v < 0.5 ? 4 * v * v * v : 1 - Math.pow(-2 * v + 2, 3) / 2;
  };
  const easeOutCubic = (x) => {
    const v = clamp01(x);
    return 1 - Math.pow(1 - v, 3);
  };
  const easeInOutSine = (x) => {
    const v = clamp01(x);
    return -(Math.cos(Math.PI * v) - 1) * 0.5;
  };
  const lerp = (a, b, k) => a + (b - a) * k;

  const roundRectPath = (x, y, w, h, r) => {
    const rad = Math.max(0, Math.min(r, w * 0.5, h * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  };

  // 1. Clean Modern Dark Aesthetic Gradient Background (Deep Charcoal-Plum, Zero Glow, Zero Borders)
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, '#120810');
  bgGrad.addColorStop(0.5, '#1D0D1A');
  bgGrad.addColorStop(1, '#291325');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // 2. Global Seamless Motion Parameters Driven by t, loopT, currentScene, sceneProgress
  const loopNorm = loopT / duration;
  const wavePhase = loopNorm * Math.PI * 2 * 6;
  const exhaustOsc = Math.sin(loopNorm * Math.PI * 2 * 10);

  let fuelLevel = 0.28;
  let inflowStream = 0;
  let climbProgress = 0;
  let thrustIntensity = 0;
  let gaugeRatio = 0.22;
  let chartProgress = 0.20;
  let orbitRingRatio = 0.25;
  let railScroll = 0;
  let conduitFlow = 0.20;
  let tierActive = 0;

  if (currentScene === 0) {
    // Scene 0 (0-5s): Rocket poised cleanly on pad while crystal tank fuels from 28% -> 88%
    const fillK = easeInOutCubic((sceneProgress - 0.12) / 0.76);
    fuelLevel = lerp(0.28, 0.88, fillK);
    const stIn = easeOutCubic((sceneProgress - 0.08) / 0.16);
    const stOut = 1 - easeInOutCubic((sceneProgress - 0.78) / 0.16);
    inflowStream = clamp01(Math.min(stIn, stOut));
    climbProgress = 0;
    thrustIntensity = easeInOutCubic((sceneProgress - 0.84) / 0.16) * 0.35;
    gaugeRatio = lerp(0.22, 0.56, fillK);
    chartProgress = lerp(0.20, 0.45, fillK);
    orbitRingRatio = lerp(0.25, 0.48, fillK);
    railScroll = 0;
    conduitFlow = 0.22 + 0.55 * easeInOutSine(sceneProgress);
    tierActive = fillK * 1.4;
  } else if (currentScene === 1) {
    // Scene 1 (5-10s): Smooth proportional ignition & controlled ascent inside safe corridor
    const ascK = easeInOutCubic(sceneProgress);
    fuelLevel = lerp(0.88, 0.72, ascK);
    inflowStream = 0;
    climbProgress = ascK;
    thrustIntensity = lerp(0.35, 1.0, easeOutCubic(sceneProgress / 0.35));
    gaugeRatio = lerp(0.56, 0.92, ascK);
    chartProgress = lerp(0.45, 0.86, ascK);
    orbitRingRatio = lerp(0.48, 0.88, ascK);
    railScroll = ascK * 1.5; // Travels 1.5 rail units upward-to-downward
    conduitFlow = 0.85;
    tierActive = lerp(1.4, 2.8, ascK);
  } else if (currentScene === 2) {
    // Scene 2 (10-15s): High-altitude orbital cruise & peak ROI valuation milestone
    const cruiseWave = Math.sin(sceneProgress * Math.PI * 2);
    fuelLevel = 0.72 - 0.06 * easeInOutSine(sceneProgress);
    inflowStream = 0;
    climbProgress = 1 + 0.04 * cruiseWave;
    thrustIntensity = 0.92 + 0.08 * cruiseWave;
    gaugeRatio = lerp(0.92, 0.97, easeInOutSine(sceneProgress));
    chartProgress = lerp(0.86, 1.0, easeInOutCubic(sceneProgress / 0.65));
    orbitRingRatio = lerp(0.88, 1.0, easeInOutCubic(sceneProgress / 0.65));
    railScroll = 1.5 + sceneProgress * 1.5; // Reaches 3.0 integer cycles
    conduitFlow = 0.75 + 0.25 * Math.sin(sceneProgress * Math.PI);
    tierActive = 3.0;
  } else {
    // Scene 3 (15-20s): Smooth controlled descent, thruster taper, tank & gauges reset to t = 0
    const descK = easeInOutCubic(sceneProgress / 0.82);
    climbProgress = 1 - descK;
    thrustIntensity = (1 - easeInOutCubic((sceneProgress - 0.55) / 0.35)) * 0.92;
    fuelLevel = lerp(0.66, 0.28, easeInOutCubic((sceneProgress - 0.10) / 0.78));
    inflowStream = 0;
    gaugeRatio = lerp(0.97, 0.22, easeInOutCubic(sceneProgress / 0.88));
    chartProgress = lerp(1.0, 0.20, easeInOutCubic(sceneProgress / 0.88));
    orbitRingRatio = lerp(1.0, 0.25, easeInOutCubic(sceneProgress / 0.88));
    railScroll = 3.0 + easeInOutCubic(sceneProgress) * 1.0; // Total 4.0 exact integer cycles over 20s!
    conduitFlow = lerp(0.75, 0.22, easeInOutCubic(sceneProgress / 0.85));
    tierActive = lerp(3.0, 0, easeInOutCubic(sceneProgress / 0.82));
  }

  // 3. Precision Conduit Buses (Strictly Separated From Cards & Altitude Rails)
  const drawConduit = (xStart, xEnd, active) => {
    ctx.save();
    const yRail = cy;
    const termR = 0.0075 * S;
    const railH = 0.009 * S;
    const padX = 0.011 * S;

    roundRectPath(xStart, yRail - railH * 0.5, xEnd - xStart, railH, railH * 0.5);
    ctx.fillStyle = '#1B0D18';
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.002 * S);
    ctx.strokeStyle = '#6A2E4D';
    ctx.stroke();

    [xStart, xEnd].forEach((tx) => {
      ctx.beginPath();
      ctx.arc(tx, yRail, termR, 0, Math.PI * 2);
      ctx.fillStyle = '#2B1426';
      ctx.fill();
      ctx.lineWidth = Math.max(1, 0.0024 * S);
      ctx.strokeStyle = active > 0.4 ? '#FB923C' : '#8B3E62';
      ctx.stroke();
    });

    const innerStart = xStart + padX;
    const innerEnd = xEnd - padX;
    const span = innerEnd - innerStart;
    if (span > 0 && active > 0.02) {
      ctx.save();
      roundRectPath(innerStart, yRail - railH * 0.42, span, railH * 0.84, railH * 0.42);
      ctx.clip();

      const pktW = 0.022 * S;
      const cycles = 4; // Exact integer cycles over 20s
      for (let i = 0; i < 2; i++) {
        const ph = (loopNorm * cycles + i * 0.5) % 1;
        const px = innerStart - pktW + ph * (span + pktW);
        ctx.globalAlpha = clamp01(active * Math.sin(ph * Math.PI) * 1.2);
        roundRectPath(px, yRail - railH * 0.34, pktW, railH * 0.68, railH * 0.34);
        ctx.fillStyle = '#FBBF24';
        ctx.fill();
      }
      ctx.restore();
    }
    ctx.restore();
  };

  // Cards occupy [cx - 0.68*S, cx - 0.44*S] and [cx + 0.44*S, cx + 0.68*S]
  // Altitude rails occupy [cx +/- 0.181*S, cx +/- 0.195*S]
  drawConduit(cx - 0.422 * S, cx - 0.222 * S, conduitFlow);
  drawConduit(cx + 0.222 * S, cx + 0.422 * S, conduitFlow);

  // 4. Left Telemetry Card — ROI Velocity Speedometer & Tier Bars
  const drawLeftCard = () => {
    const cardW = 0.24 * S;
    const cardH = 0.34 * S;
    const cardX = cx - 0.56 * S - cardW * 0.5;
    const cardY = cy - cardH * 0.5;
    const cardR = 0.024 * S;

    ctx.save();
    roundRectPath(cardX, cardY, cardW, cardH, cardR);
    const cardGrad = ctx.createLinearGradient(cardX, cardY, cardX, cardY + cardH);
    cardGrad.addColorStop(0, '#2B1525');
    cardGrad.addColorStop(1, '#190B16');
    ctx.fillStyle = cardGrad;
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.003 * S);
    ctx.strokeStyle = '#6E3251';
    ctx.stroke();

    // Top Half: Half-Circle ROI Speedometer
    const dialCx = cardX + cardW * 0.5;
    const dialCy = cardY + 0.132 * S;
    const dialR = 0.072 * S;
    const dialLW = 0.014 * S;

    // Background arc
    ctx.beginPath();
    ctx.arc(dialCx, dialCy, dialR, Math.PI, Math.PI * 2);
    ctx.lineWidth = dialLW;
    ctx.lineCap = 'round';
    ctx.strokeStyle = '#120810';
    ctx.stroke();

    // Active Tangerine-to-Gold arc
    const needleAng = Math.PI + Math.PI * clamp01(gaugeRatio);
    const arcGrad = ctx.createLinearGradient(dialCx - dialR, dialCy, dialCx + dialR, dialCy);
    arcGrad.addColorStop(0, '#EA580C');
    arcGrad.addColorStop(0.55, '#F97316');
    arcGrad.addColorStop(1, '#FBBF24');

    ctx.beginPath();
    ctx.arc(dialCx, dialCy, dialR, Math.PI, needleAng);
    ctx.lineWidth = dialLW;
    ctx.lineCap = 'round';
    ctx.strokeStyle = arcGrad;
    ctx.stroke();

    // 7 Crisp Radial Scale Ticks inside dial
    for (let i = 0; i <= 6; i++) {
      const a = Math.PI + (i / 6) * Math.PI;
      const rIn = dialR - 0.022 * S;
      const rOut = dialR - 0.013 * S;
      ctx.beginPath();
      ctx.moveTo(dialCx + Math.cos(a) * rIn, dialCy + Math.sin(a) * rIn);
      ctx.lineTo(dialCx + Math.cos(a) * rOut, dialCy + Math.sin(a) * rOut);
      ctx.lineWidth = Math.max(1, 0.0022 * S);
      ctx.strokeStyle = i / 6 <= gaugeRatio ? '#FDE68A' : '#5E2B45';
      ctx.stroke();
    }

    // Precision Speedometer Needle
    ctx.save();
    ctx.translate(dialCx, dialCy);
    ctx.rotate(needleAng);
    ctx.beginPath();
    ctx.moveTo(-0.008 * S, -0.004 * S);
    ctx.lineTo(dialR * 0.72, 0);
    ctx.lineTo(-0.008 * S, 0.004 * S);
    ctx.closePath();
    ctx.fillStyle = '#FEF3C7';
    ctx.fill();
    ctx.restore();

    // Pivot Hub
    ctx.beginPath();
    ctx.arc(dialCx, dialCy, 0.011 * S, 0, Math.PI * 2);
    ctx.fillStyle = '#F97316';
    ctx.fill();
    ctx.beginPath();
    ctx.arc(dialCx, dialCy, 0.005 * S, 0, Math.PI * 2);
    ctx.fillStyle = '#FEF3C7';
    ctx.fill();

    // Divider line
    const divY = cardY + 0.172 * S;
    roundRectPath(cardX + 0.036 * S, divY, cardW - 0.072 * S, 0.0025 * S, 0.00125 * S);
    ctx.fillStyle = '#5B2843';
    ctx.fill();

    // Bottom Half: 3 ROI Milestone Horizontal Bars
    const barX = cardX + 0.032 * S;
    const barMaxW = cardW - 0.064 * S;
    const barH = 0.018 * S;
    const barGap = 0.018 * S;
    const barTop = cardY + 0.204 * S;
    const targetWidths = [0.58, 0.78, 1.0];

    for (let i = 0; i < 3; i++) {
      const by = barTop + i * (barH + barGap);
      roundRectPath(barX, by, barMaxW, barH, barH * 0.5);
      ctx.fillStyle = '#120810';
      ctx.fill();

      const localFill = clamp01(tierActive - i);
      if (localFill > 0.02) {
        const fw = Math.max(barH, barMaxW * targetWidths[i] * localFill);
        roundRectPath(barX, by, fw, barH, barH * 0.5);
        const bg = ctx.createLinearGradient(barX, by, barX + fw, by);
        bg.addColorStop(0, '#EA580C');
        bg.addColorStop(1, '#FBBF24');
        ctx.fillStyle = bg;
        ctx.fill();
      }
    }

    ctx.restore();
  };

  drawLeftCard();

  // 5. Right Telemetry Card — Growth Valuation Curve & Target Orbit Badge
  const drawRightCard = () => {
    const cardW = 0.24 * S;
    const cardH = 0.34 * S;
    const cardX = cx + 0.56 * S - cardW * 0.5;
    const cardY = cy - cardH * 0.5;
    const cardR = 0.024 * S;

    ctx.save();
    roundRectPath(cardX, cardY, cardW, cardH, cardR);
    const cardGrad = ctx.createLinearGradient(cardX, cardY, cardX, cardY + cardH);
    cardGrad.addColorStop(0, '#2B1525');
    cardGrad.addColorStop(1, '#190B16');
    ctx.fillStyle = cardGrad;
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.003 * S);
    ctx.strokeStyle = '#6E3251';
    ctx.stroke();

    // Top Half: Clipped Valuation Line Chart Box
    const chX = cardX + 0.028 * S;
    const chY = cardY + 0.028 * S;
    const chW = cardW - 0.056 * S;
    const chH = 0.120 * S;

    ctx.save();
    roundRectPath(chX, chY, chW, chH, 0.014 * S);
    ctx.fillStyle = '#120810';
    ctx.fill();
    ctx.clip();

    // Subtle horizontal grid lines
    ctx.strokeStyle = '#2F1529';
    ctx.lineWidth = Math.max(1, 0.0016 * S);
    for (let g = 1; g <= 3; g++) {
      const gy = chY + (g / 4) * chH;
      ctx.beginPath();
      ctx.moveTo(chX + 0.010 * S, gy);
      ctx.lineTo(chX + chW - 0.010 * S, gy);
      ctx.stroke();
    }

    // Progressive smooth exponential valuation curve
    const padX = 0.016 * S;
    const padY = 0.018 * S;
    const plotW = chW - padX * 2;
    const plotH = chH - padY * 2;
    const steps = 28;
    const maxStep = Math.max(1, Math.floor(steps * clamp01(chartProgress)));

    const getCurvePt = (u) => {
      const x = chX + padX + u * plotW;
      const val = Math.pow(u, 1.75);
      const y = chY + chH - padY - val * plotH;
      return { x, y };
    };

    // Area under curve
    ctx.beginPath();
    const p0 = getCurvePt(0);
    ctx.moveTo(p0.x, chY + chH - padY * 0.4);
    for (let i = 0; i <= maxStep; i++) {
      const u = (i / steps) * clamp01(chartProgress) / Math.max(0.0001, clamp01(chartProgress) > 0 ? 1 : 1);
      const exactU = (i / steps) * clamp01(chartProgress);
      const pt = getCurvePt(exactU);
      ctx.lineTo(pt.x, pt.y);
    }
    const endPt = getCurvePt(clamp01(chartProgress));
    ctx.lineTo(endPt.x, chY + chH - padY * 0.4);
    ctx.closePath();
    const areaGrad = ctx.createLinearGradient(chX, chY, chX, chY + chH);
    areaGrad.addColorStop(0, 'rgba(251, 146, 60, 0.38)');
    areaGrad.addColorStop(1, 'rgba(234, 88, 12, 0.03)');
    ctx.fillStyle = areaGrad;
    ctx.fill();

    // Curve stroke
    ctx.beginPath();
    for (let i = 0; i <= steps; i++) {
      const exactU = (i / steps) * clamp01(chartProgress);
      const pt = getCurvePt(exactU);
      if (i === 0) ctx.moveTo(pt.x, pt.y);
      else ctx.lineTo(pt.x, pt.y);
    }
    ctx.lineWidth = Math.max(1, 0.0036 * S);
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.strokeStyle = '#FBBF24';
    ctx.stroke();

    // Endpoint indicator dot
    ctx.beginPath();
    ctx.arc(endPt.x, endPt.y, 0.0055 * S, 0, Math.PI * 2);
    ctx.fillStyle = '#FEF3C7';
    ctx.fill();
    ctx.restore();

    // Divider line
    const divY = cardY + 0.172 * S;
    roundRectPath(cardX + 0.036 * S, divY, cardW - 0.072 * S, 0.0025 * S, 0.00125 * S);
    ctx.fillStyle = '#5B2843';
    ctx.fill();

    // Bottom Half: Target Orbit Progress Ring + Double Upward Chevron
    const ringCx = cardX + cardW * 0.5;
    const ringCy = cardY + 0.252 * S;
    const ringR = 0.050 * S;
    const ringLW = 0.011 * S;

    ctx.beginPath();
    ctx.arc(ringCx, ringCy, ringR, 0, Math.PI * 2);
    ctx.lineWidth = ringLW;
    ctx.strokeStyle = '#120810';
    ctx.stroke();

    const startA = -Math.PI * 0.5;
    const endA = startA + Math.PI * 2 * clamp01(orbitRingRatio);
    const ringGrad = ctx.createLinearGradient(ringCx - ringR, ringCy - ringR, ringCx + ringR, ringCy + ringR);
    ringGrad.addColorStop(0, '#EA580C');
    ringGrad.addColorStop(1, '#FDE68A');

    ctx.beginPath();
    ctx.arc(ringCx, ringCy, ringR, startA, endA);
    ctx.lineWidth = ringLW;
    ctx.lineCap = 'round';
    ctx.strokeStyle = ringGrad;
    ctx.stroke();

    // Double upward chevron inside ring
    ctx.save();
    ctx.translate(ringCx, ringCy);
    ctx.strokeStyle = '#FDE68A';
    ctx.lineWidth = Math.max(1, 0.0036 * S);
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    const cw = 0.016 * S;
    [-0.006 * S, 0.009 * S].forEach((cyOff) => {
      ctx.beginPath();
      ctx.moveTo(-cw, cyOff + 0.007 * S);
      ctx.lineTo(0, cyOff - 0.007 * S);
      ctx.lineTo(cw, cyOff + 0.007 * S);
      ctx.stroke();
    });
    ctx.restore();

    ctx.restore();
  };

  drawRightCard();

  // 6. Central Launch Corridor: Twin Vertical Altitude Milestone Rails + Launch Pad
  const drawAltitudeRails = () => {
    const railH = 0.38 * S;
    const railW = 0.014 * S;
    const railY = cy - railH * 0.5 - 0.02 * S;
    const trackSpacing = 0.048 * S;

    [-1, 1].forEach((side) => {
      const rx = cx + side * 0.188 * S - railW * 0.5;
      ctx.save();
      roundRectPath(rx, railY, railW, railH, railW * 0.5);
      ctx.fillStyle = '#180B16';
      ctx.fill();
      ctx.lineWidth = Math.max(1, 0.002 * S);
      ctx.strokeStyle = '#5B2843';
      ctx.stroke();

      // Clipped scrolling altitude ticks (exact integer cycles over 20s -> seamless loop)
      ctx.save();
      roundRectPath(rx + 0.002 * S, railY + 0.006 * S, railW - 0.004 * S, railH - 0.012 * S, (railW - 0.004 * S) * 0.5);
      ctx.clip();

      const tickOffset = (railScroll * trackSpacing) % trackSpacing;
      const numTicks = Math.ceil(railH / trackSpacing) + 2;
      for (let i = -1; i < numTicks; i++) {
        const ty = railY + i * trackSpacing + tickOffset;
        roundRectPath(rx + 0.003 * S, ty - 0.0035 * S, railW - 0.006 * S, 0.007 * S, 0.0035 * S);
        ctx.fillStyle = climbProgress > 0.25 ? '#FBBF24' : '#7C3658';
        ctx.fill();
      }
      ctx.restore();

      ctx.restore();
    });
  };

  drawAltitudeRails();

  // Launch Pedestal Platform (Strictly separated below rocket & exhaust at all frames)
  ctx.save();
  const padW = 0.30 * S;
  const padH = 0.022 * S;
  const padY = cy + 0.228 * S;
  roundRectPath(cx - padW * 0.5, padY, padW, padH, padH * 0.5);
  const padGrad = ctx.createLinearGradient(cx - padW * 0.5, padY, cx + padW * 0.5, padY);
  padGrad.addColorStop(0, '#271222');
  padGrad.addColorStop(0.5, '#3D1D36');
  padGrad.addColorStop(1, '#271222');
  ctx.fillStyle = padGrad;
  ctx.fill();
  ctx.lineWidth = Math.max(1, 0.0026 * S);
  ctx.strokeStyle = '#7C3658';
  ctx.stroke();

  // Pedestal status strip
  const stW = lerp(0.08 * S, 0.18 * S, clamp01(thrustIntensity));
  roundRectPath(cx - stW * 0.5, padY + 0.007 * S, stW, 0.008 * S, 0.004 * S);
  ctx.fillStyle = thrustIntensity > 0.25 ? '#FB923C' : '#6E3251';
  ctx.fill();
  ctx.restore();

  // 7. Hero Centerpiece — Rocket ROI Fuel Vehicle (Strict Proportions, Zero Cutoff)
  const liftY = -climbProgress * 0.11 * S;
  const rCx = cx;
  const rCy = cy - 0.008 * S + liftY;

  ctx.save();

  // A. Multi-Layer Flat-Vector Exhaust Plume (Strictly clamped clear above pedestal at all frames)
  if (thrustIntensity > 0.02) {
    const nozBottom = rCy + 0.168 * S;
    const availGap = Math.max(0, padY - 0.018 * S - nozBottom);
    const pulseScale = 1 + 0.06 * exhaustOsc;
    const maxFlameLen = Math.min(0.112 * S * clamp01(thrustIntensity), availGap / 1.06);
    const flameLen = maxFlameLen * pulseScale;
    const outerW = Math.min(0.044 * S * clamp01(thrustIntensity), 0.016 * S + flameLen * 0.26);

    // Outer Coral-Orange Flame Cone
    ctx.beginPath();
    ctx.moveTo(rCx - outerW, nozBottom);
    ctx.quadraticCurveTo(rCx - outerW * 0.65, nozBottom + flameLen * 0.65, rCx, nozBottom + flameLen);
    ctx.quadraticCurveTo(rCx + outerW * 0.65, nozBottom + flameLen * 0.65, rCx + outerW, nozBottom);
    ctx.closePath();
    const flGrad = ctx.createLinearGradient(rCx, nozBottom, rCx, nozBottom + flameLen);
    flGrad.addColorStop(0, '#EA580C');
    flGrad.addColorStop(1, '#F97316');
    ctx.fillStyle = flGrad;
    ctx.fill();

    // Middle Amber-Gold Flame Cone
    const midLen = flameLen * 0.72;
    const midW = outerW * 0.66;
    ctx.beginPath();
    ctx.moveTo(rCx - midW, nozBottom);
    ctx.quadraticCurveTo(rCx - midW * 0.55, nozBottom + midLen * 0.6, rCx, nozBottom + midLen);
    ctx.quadraticCurveTo(rCx + midW * 0.55, nozBottom + midLen * 0.6, rCx + midW, nozBottom);
    ctx.closePath();
    ctx.fillStyle = '#FBBF24';
    ctx.fill();

    // Inner Ivory Core Cone
    const inLen = flameLen * 0.44;
    const inW = outerW * 0.34;
    ctx.beginPath();
    ctx.moveTo(rCx - inW, nozBottom);
    ctx.quadraticCurveTo(rCx - inW * 0.45, nozBottom + inLen * 0.6, rCx, nozBottom + inLen);
    ctx.quadraticCurveTo(rCx + inW * 0.45, nozBottom + inLen * 0.6, rCx + inW, nozBottom);
    ctx.closePath();
    ctx.fillStyle = '#FEF3C7';
    ctx.fill();

    // 3 Crisp Exhaust Spark Pills (strictly inside corridor above pedestal)
    for (let sp = 0; sp < 3; sp++) {
      const spPhase = (loopNorm * 6 + sp * 0.333) % 1;
      const sx = rCx + (sp - 1) * 0.022 * S;
      const sy = nozBottom + flameLen * 0.6 + spPhase * 0.036 * S;
      if (sy < padY - 0.012 * S) {
        ctx.save();
        ctx.globalAlpha = clamp01(thrustIntensity * Math.sin(spPhase * Math.PI));
        ctx.beginPath();
        ctx.arc(sx, sy, 0.0042 * S, 0, Math.PI * 2);
        ctx.fillStyle = '#FDE68A';
        ctx.fill();
        ctx.restore();
      }
    }
  }

  // B. Symmetric Left & Right Rocket Fins (Crisp non-overlapping attachments cleanly joined at fuselage border)
  const bodyHalfW = 0.072 * S;
  const bodyTopY = rCy - 0.115 * S;
  const bodyBotY = rCy + 0.132 * S;
  const noseTipY = rCy - 0.195 * S;

  [-1, 1].forEach((side) => {
    ctx.beginPath();
    ctx.moveTo(rCx + side * bodyHalfW, rCy + 0.025 * S);
    ctx.quadraticCurveTo(rCx + side * (bodyHalfW + 0.052 * S), rCy + 0.068 * S, rCx + side * (bodyHalfW + 0.050 * S), bodyBotY + 0.018 * S);
    ctx.lineTo(rCx + side * (bodyHalfW + 0.012 * S), bodyBotY - 0.012 * S);
    ctx.lineTo(rCx + side * bodyHalfW, bodyBotY - 0.008 * S);
    ctx.closePath();
    ctx.fillStyle = '#EA580C';
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.0028 * S);
    ctx.strokeStyle = '#FB923C';
    ctx.stroke();
  });

  // C. Lower Thruster Nozzle Collar
  const nozTopW = 0.076 * S;
  const nozBotW = 0.098 * S;
  const nozTopY = bodyBotY;
  const nozBotY = rCy + 0.168 * S;
  ctx.beginPath();
  ctx.moveTo(rCx - nozTopW * 0.5, nozTopY);
  ctx.lineTo(rCx + nozTopW * 0.5, nozTopY);
  ctx.lineTo(rCx + nozBotW * 0.5, nozBotY);
  ctx.lineTo(rCx - nozBotW * 0.5, nozBotY);
  ctx.closePath();
  ctx.fillStyle = '#4A203A';
  ctx.fill();
  ctx.lineWidth = Math.max(1, 0.0028 * S);
  ctx.strokeStyle = '#9D4873';
  ctx.stroke();

  // D. Main Rocket Fuselage Silhouette (Pure 2D Layered Modern Flat Vector)
  const traceFuselage = () => {
    ctx.beginPath();
    ctx.moveTo(rCx, noseTipY);
    ctx.bezierCurveTo(
      rCx + bodyHalfW * 0.72,
      noseTipY + 0.042 * S,
      rCx + bodyHalfW,
      bodyTopY + 0.032 * S,
      rCx + bodyHalfW,
      bodyTopY + 0.075 * S
    );
    ctx.lineTo(rCx + bodyHalfW, bodyBotY - 0.016 * S);
    ctx.quadraticCurveTo(rCx + bodyHalfW, bodyBotY, rCx + bodyHalfW - 0.016 * S, bodyBotY);
    ctx.lineTo(rCx - bodyHalfW + 0.016 * S, bodyBotY);
    ctx.quadraticCurveTo(rCx - bodyHalfW, bodyBotY, rCx - bodyHalfW, bodyBotY - 0.016 * S);
    ctx.lineTo(rCx - bodyHalfW, bodyTopY + 0.075 * S);
    ctx.bezierCurveTo(
      rCx - bodyHalfW,
      bodyTopY + 0.032 * S,
      rCx - bodyHalfW * 0.72,
      noseTipY + 0.042 * S,
      rCx,
      noseTipY
    );
    ctx.closePath();
  };

  traceFuselage();
  const hullGrad = ctx.createLinearGradient(rCx - bodyHalfW, rCy, rCx + bodyHalfW, rCy);
  hullGrad.addColorStop(0, '#FFF7ED');
  hullGrad.addColorStop(0.55, '#FED7AA');
  hullGrad.addColorStop(1, '#FDBA74');
  ctx.fillStyle = hullGrad;
  ctx.fill();

  // Nose Cone Accent Tip Clipped Inside Fuselage
  ctx.save();
  traceFuselage();
  ctx.clip();
  ctx.fillStyle = '#EA580C';
  ctx.fillRect(rCx - bodyHalfW, noseTipY, bodyHalfW * 2, 0.068 * S);
  ctx.fillStyle = '#FB923C';
  ctx.fillRect(rCx - bodyHalfW, noseTipY + 0.062 * S, bodyHalfW * 2, 0.008 * S);
  ctx.restore();

  // Fuselage Clean Outer Border
  traceFuselage();
  ctx.lineWidth = Math.max(1, 0.0036 * S);
  ctx.strokeStyle = '#FB923C';
  ctx.stroke();

  // E. Recessed Crystal Fuel Tank Capsule Window Inside Rocket Fuselage
  const tankW = 0.088 * S;
  const tankH = 0.168 * S;
  const tankX = rCx - tankW * 0.5;
  const tankY = rCy - 0.062 * S;
  const tankR = tankW * 0.48;

  ctx.save();
  roundRectPath(tankX, tankY, tankW, tankH, tankR);
  ctx.fillStyle = '#140812';
  ctx.fill();
  ctx.clip();

  // Top internal valve nozzle
  const valW = 0.026 * S;
  const valH = 0.012 * S;
  roundRectPath(rCx - valW * 0.5, tankY - 0.002 * S, valW, valH, 0.004 * S);
  ctx.fillStyle = '#5B2843';
  ctx.fill();

  const fuelSurfaceBase = tankY + tankH * (1 - fuelLevel);
  const fuelAmp = (0.0045 + 0.0035 * inflowStream) * S;
  const getFuelY = (px) => {
    const nx = (px - tankX) / tankW;
    return fuelSurfaceBase + Math.sin(nx * Math.PI * 2 + wavePhase) * fuelAmp;
  };

  // Pouring inflow stream during Scene 0
  if (inflowStream > 0.01) {
    const sTop = tankY + valH - 0.002 * S;
    const sBot = getFuelY(rCx) + 0.006 * S;
    const sW = 0.010 * S * inflowStream;
    if (sBot > sTop) {
      ctx.fillStyle = '#FBBF24';
      ctx.fillRect(rCx - sW * 0.5, sTop, sW, sBot - sTop);
    }
  }

  // Back & Front Liquid Fuel Waves
  const fSteps = 20;
  ctx.beginPath();
  ctx.moveTo(tankX, tankY + tankH);
  for (let i = 0; i <= fSteps; i++) {
    const px = tankX + (i / fSteps) * tankW;
    const py = fuelSurfaceBase - 0.003 * S + Math.sin(((px - tankX) / tankW) * Math.PI * 2 - wavePhase + 1.2) * (fuelAmp * 0.8);
    ctx.lineTo(px, py);
  }
  ctx.lineTo(tankX + tankW, tankY + tankH);
  ctx.closePath();
  ctx.fillStyle = '#C2410C';
  ctx.fill();

  ctx.beginPath();
  ctx.moveTo(tankX, tankY + tankH);
  for (let i = 0; i <= fSteps; i++) {
    const px = tankX + (i / fSteps) * tankW;
    ctx.lineTo(px, getFuelY(px));
  }
  ctx.lineTo(tankX + tankW, tankY + tankH);
  ctx.closePath();
  const fGrad = ctx.createLinearGradient(rCx, fuelSurfaceBase, rCx, tankY + tankH);
  fGrad.addColorStop(0, '#FBBF24');
  fGrad.addColorStop(0.5, '#F97316');
  fGrad.addColorStop(1, '#EA580C');
  ctx.fillStyle = fGrad;
  ctx.fill();

  // Crisp crest line
  ctx.beginPath();
  for (let i = 0; i <= fSteps; i++) {
    const px = tankX + (i / fSteps) * tankW;
    const py = getFuelY(px);
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.lineWidth = Math.max(1, 0.0028 * S);
  ctx.strokeStyle = '#FEF3C7';
  ctx.stroke();

  // Rising golden fuel bubbles clipped cleanly inside liquid
  for (let b = 0; b < 5; b++) {
    const bProg = (loopNorm * 3 + b * 0.21) % 1;
    const bx = tankX + 0.022 * S + ((b * 0.011 * S) % (tankW - 0.044 * S));
    const topLim = getFuelY(bx) + 0.010 * S;
    const botLim = tankY + tankH - 0.010 * S;
    if (botLim > topLim) {
      const by = lerp(botLim, topLim, bProg);
      ctx.save();
      ctx.globalAlpha = Math.sin(bProg * Math.PI) * 0.75;
      ctx.beginPath();
      ctx.arc(bx, by, 0.0028 * S, 0, Math.PI * 2);
      ctx.fillStyle = '#FEF3C7';
      ctx.fill();
      ctx.restore();
    }
  }

  // Calibration tick markers on left side of glass window
  ctx.strokeStyle = 'rgba(254, 243, 199, 0.35)';
  ctx.lineWidth = Math.max(1, 0.0018 * S);
  for (let tk = 1; tk <= 4; tk++) {
    const ty = tankY + tankH - (tk / 5) * tankH;
    ctx.beginPath();
    ctx.moveTo(tankX + 0.008 * S, ty);
    ctx.lineTo(tankX + 0.018 * S, ty);
    ctx.stroke();
  }

  ctx.restore(); // End tank clip

  // Outer crystal window rim
  roundRectPath(tankX, tankY, tankW, tankH, tankR);
  ctx.lineWidth = Math.max(1, 0.003 * S);
  ctx.strokeStyle = '#9D4873';
  ctx.stroke();

  ctx.restore(); // End rocket group
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const S = minSide;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const easeInOutCubic = (x) => {
    const v = clamp01(x);
    return v < 0.5 ? 4 * v * v * v : 1 - Math.pow(-2 * v + 2, 3) / 2;
  };
  const easeOutCubic = (x) => {
    const v = clamp01(x);
    return 1 - Math.pow(1 - v, 3);
  };
  const easeInOutSine = (x) => {
    const v = clamp01(x);
    return -(Math.cos(Math.PI * v) - 1) * 0.5;
  };
  const lerp = (a, b, k) => a + (b - a) * k;

  const roundRectPath = (x, y, w, h, r) => {
    const rad = Math.max(0, Math.min(r, w * 0.5, h * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  };

  const drawDollarSign = (x, y, size, color, lw) => {
    ctx.save();
    ctx.translate(x, y);
    ctx.strokeStyle = color;
    ctx.lineWidth = lw;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.beginPath();
    ctx.moveTo(0, -size * 1.12);
    ctx.lineTo(0, size * 1.12);
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(size * 0.65, -size * 0.48);
    ctx.bezierCurveTo(size * 0.62, -size * 0.90, -size * 0.68, -size * 0.90, -size * 0.65, -size * 0.35);
    ctx.bezierCurveTo(-size * 0.62, 0, size * 0.65, 0, size * 0.65, size * 0.38);
    ctx.bezierCurveTo(size * 0.65, size * 0.90, -size * 0.65, size * 0.90, -size * 0.68, size * 0.48);
    ctx.stroke();
    ctx.restore();
  };

  // 1. Clean Modern Dark Aesthetic Gradient Background (Espresso Charcoal, Zero Glow, Zero Borders)
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, '#110D07');
  bgGrad.addColorStop(0.5, '#1B150B');
  bgGrad.addColorStop(1, '#261D0F');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // 2. Global Seamless Motion Parameters Driven by t, loopT, currentScene, sceneProgress
  const loopNorm = loopT / duration;
  const wavePhase = loopNorm * Math.PI * 2 * 6;

  let flowProgress = 0; // 0 -> 1 across Scenes 0-2
  let streamIntensity = 0;
  let flipAngle = 0; // 0 -> PI in Scene 3
  let curveProgress = 0.16;
  let ringRatio = 0.18;
  let tierProgress = 0.25;
  let conduitFlow = 0.25;

  if (currentScene === 0) {
    // Scene 0 (0-5s): Flow initiates smoothly; first compounding phase
    streamIntensity = easeOutCubic(sceneProgress / 0.16);
    flowProgress = lerp(0, 0.32, easeInOutSine(sceneProgress));
    curveProgress = lerp(0.16, 0.42, easeInOutSine(sceneProgress));
    ringRatio = lerp(0.18, 0.42, easeInOutSine(sceneProgress));
    tierProgress = lerp(0.25, 0.48, easeInOutSine(sceneProgress));
    conduitFlow = 0.35 + 0.45 * easeInOutSine(sceneProgress);
  } else if (currentScene === 1) {
    // Scene 1 (5-10s): Steady golden wealth transfer & exponential curve climb
    streamIntensity = 1;
    flowProgress = lerp(0.32, 0.70, easeInOutSine(sceneProgress));
    curveProgress = lerp(0.42, 0.76, easeInOutSine(sceneProgress));
    ringRatio = lerp(0.42, 0.74, easeInOutSine(sceneProgress));
    tierProgress = lerp(0.48, 0.78, easeInOutSine(sceneProgress));
    conduitFlow = 0.85;
  } else if (currentScene === 2) {
    // Scene 2 (10-15s): Peak accumulation & compound yield milestone
    streamIntensity = 1 - easeInOutCubic((sceneProgress - 0.84) / 0.16);
    flowProgress = lerp(0.70, 1.0, easeInOutCubic(sceneProgress / 0.88));
    curveProgress = lerp(0.76, 1.0, easeInOutCubic(sceneProgress / 0.75));
    ringRatio = lerp(0.74, 0.96, easeInOutCubic(sceneProgress / 0.75));
    tierProgress = lerp(0.78, 1.0, easeInOutCubic(sceneProgress / 0.75));
    conduitFlow = 0.85 + 0.15 * Math.sin(sceneProgress * Math.PI);
  } else {
    // Scene 3 (15-20s): Controlled 180-degree symmetric hourglass flip + telemetry reset
    streamIntensity = 0;
    flowProgress = 1;
    flipAngle = easeInOutCubic((sceneProgress - 0.12) / 0.76) * Math.PI;
    const resetK = easeInOutCubic((sceneProgress - 0.08) / 0.84);
    curveProgress = lerp(1.0, 0.16, resetK);
    ringRatio = lerp(0.96, 0.18, resetK);
    tierProgress = lerp(1.0, 0.25, resetK);
    conduitFlow = lerp(0.85, 0.35, resetK);
  }

  const upperBulbFill = lerp(0.84, 0.16, flowProgress);
  const lowerBulbFill = lerp(0.16, 0.84, flowProgress);

  // 3. Grounding Pedestal Pill (Strictly clear below max rotated corner reach 0.299*S)
  ctx.save();
  const pedW = 0.36 * S;
  const pedH = 0.018 * S;
  const pedY = cy + 0.340 * S;
  roundRectPath(cx - pedW * 0.5, pedY, pedW, pedH, pedH * 0.5);
  ctx.fillStyle = '#0B0804';
  ctx.fill();
  ctx.lineWidth = Math.max(1, 0.0022 * S);
  ctx.strokeStyle = '#5C431B';
  ctx.stroke();
  ctx.restore();

  // 4. Precision Conduit Buses (Strictly clear of rotated hourglass max radius 0.30*S and cards at +/-0.46*S)
  const drawConduit = (xStart, xEnd, active) => {
    ctx.save();
    const yRail = cy;
    const termR = 0.007 * S;
    const railH = 0.009 * S;
    const padX = 0.010 * S;

    roundRectPath(xStart, yRail - railH * 0.5, xEnd - xStart, railH, railH * 0.5);
    ctx.fillStyle = '#140F08';
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.002 * S);
    ctx.strokeStyle = '#5C431B';
    ctx.stroke();

    [xStart, xEnd].forEach((tx) => {
      ctx.beginPath();
      ctx.arc(tx, yRail, termR, 0, Math.PI * 2);
      ctx.fillStyle = '#241B0D';
      ctx.fill();
      ctx.lineWidth = Math.max(1, 0.0024 * S);
      ctx.strokeStyle = active > 0.4 ? '#FBBF24' : '#785723';
      ctx.stroke();
    });

    const innerStart = xStart + padX;
    const innerEnd = xEnd - padX;
    const span = innerEnd - innerStart;
    if (span > 0 && active > 0.02) {
      ctx.save();
      roundRectPath(innerStart, yRail - railH * 0.42, span, railH * 0.84, railH * 0.42);
      ctx.clip();

      const pktW = 0.020 * S;
      const cycles = 4; // Exact integer cycles over 20s
      for (let i = 0; i < 2; i++) {
        const ph = (loopNorm * cycles + i * 0.5) % 1;
        const px = innerStart - pktW + ph * (span + pktW);
        ctx.globalAlpha = clamp01(active * Math.sin(ph * Math.PI) * 1.2);
        roundRectPath(px, yRail - railH * 0.34, pktW, railH * 0.68, railH * 0.34);
        ctx.fillStyle = '#FDE68A';
        ctx.fill();
      }
      ctx.restore();
    }
    ctx.restore();
  };

  drawConduit(cx - 0.442 * S, cx - 0.338 * S, conduitFlow);
  drawConduit(cx + 0.338 * S, cx + 0.442 * S, conduitFlow);

  // 5. Left Telemetry Card — Compound Exponential Curve Chart
  const drawLeftCard = () => {
    const cardW = 0.24 * S;
    const cardH = 0.34 * S;
    const cardX = cx - 0.58 * S - cardW * 0.5;
    const cardY = cy - cardH * 0.5;
    const cardR = 0.024 * S;

    ctx.save();
    roundRectPath(cardX, cardY, cardW, cardH, cardR);
    const cardGrad = ctx.createLinearGradient(cardX, cardY, cardX, cardY + cardH);
    cardGrad.addColorStop(0, '#271E11');
    cardGrad.addColorStop(1, '#151008');
    ctx.fillStyle = cardGrad;
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.003 * S);
    ctx.strokeStyle = '#6A4E21';
    ctx.stroke();

    // Header row: circular Champagne Gold '$' emblem + clean header bars
    const badgeR = 0.024 * S;
    const badgeCx = cardX + 0.050 * S;
    const badgeCy = cardY + 0.052 * S;

    ctx.beginPath();
    ctx.arc(badgeCx, badgeCy, badgeR, 0, Math.PI * 2);
    ctx.fillStyle = '#452E0B';
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.0026 * S);
    ctx.strokeStyle = '#FBBF24';
    ctx.stroke();
    drawDollarSign(badgeCx, badgeCy, badgeR * 0.48, '#FEF3C7', Math.max(1, 0.0036 * S));

    roundRectPath(cardX + 0.090 * S, badgeCy - 0.011 * S, 0.104 * S, 0.009 * S, 0.0045 * S);
    ctx.fillStyle = '#FDE68A';
    ctx.fill();
    roundRectPath(cardX + 0.090 * S, badgeCy + 0.005 * S, 0.068 * S, 0.007 * S, 0.0035 * S);
    ctx.fillStyle = '#785927';
    ctx.fill();

    // Clipped Exponential Growth Curve Box
    const chX = cardX + 0.026 * S;
    const chY = cardY + 0.100 * S;
    const chW = cardW - 0.052 * S;
    const chH = 0.172 * S;

    ctx.save();
    roundRectPath(chX, chY, chW, chH, 0.016 * S);
    ctx.fillStyle = '#0F0B06';
    ctx.fill();
    ctx.clip();

    // Subtle horizontal grid lines
    ctx.strokeStyle = '#2B2111';
    ctx.lineWidth = Math.max(1, 0.0018 * S);
    for (let g = 1; g <= 3; g++) {
      const gy = chY + (g / 4) * chH;
      ctx.beginPath();
      ctx.moveTo(chX + 0.010 * S, gy);
      ctx.lineTo(chX + chW - 0.010 * S, gy);
      ctx.stroke();
    }

    // Exponential curve plotting (y ~ u^2.3)
    const padX = 0.016 * S;
    const padY = 0.020 * S;
    const plotW = chW - padX * 2;
    const plotH = chH - padY * 2;
    const steps = 32;
    const curU = clamp01(curveProgress);

    const getPt = (u) => ({
      x: chX + padX + u * plotW,
      y: chY + chH - padY - Math.pow(u, 2.3) * plotH,
    });

    ctx.beginPath();
    const firstPt = getPt(0);
    ctx.moveTo(firstPt.x, chY + chH - padY * 0.45);
    for (let i = 0; i <= steps; i++) {
      const pt = getPt((i / steps) * curU);
      ctx.lineTo(pt.x, pt.y);
    }
    const lastPt = getPt(curU);
    ctx.lineTo(lastPt.x, chY + chH - padY * 0.45);
    ctx.closePath();
    const areaG = ctx.createLinearGradient(chX, chY, chX, chY + chH);
    areaG.addColorStop(0, 'rgba(251, 191, 36, 0.35)');
    areaG.addColorStop(1, 'rgba(180, 83, 9, 0.04)');
    ctx.fillStyle = areaG;
    ctx.fill();

    ctx.beginPath();
    for (let i = 0; i <= steps; i++) {
      const pt = getPt((i / steps) * curU);
      if (i === 0) ctx.moveTo(pt.x, pt.y);
      else ctx.lineTo(pt.x, pt.y);
    }
    ctx.lineWidth = Math.max(1, 0.0038 * S);
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.strokeStyle = '#FBBF24';
    ctx.stroke();

    // Milestone nodes along exponential curve
    [0.35, 0.68, 0.96].forEach((mU) => {
      if (curU >= mU) {
        const mp = getPt(mU);
        ctx.beginPath();
        ctx.arc(mp.x, mp.y, 0.005 * S, 0, Math.PI * 2);
        ctx.fillStyle = '#FFFBEB';
        ctx.fill();
      }
    });

    ctx.beginPath();
    ctx.arc(lastPt.x, lastPt.y, 0.006 * S, 0, Math.PI * 2);
    ctx.fillStyle = '#FDE68A';
    ctx.fill();

    ctx.restore();

    // Bottom status track
    const bX = cardX + 0.028 * S;
    const bY = cardY + 0.294 * S;
    const bW = cardW - 0.056 * S;
    const bH = 0.012 * S;
    roundRectPath(bX, bY, bW, bH, bH * 0.5);
    ctx.fillStyle = '#0F0B06';
    ctx.fill();
    roundRectPath(bX, bY, Math.max(bH, bW * curU), bH, bH * 0.5);
    ctx.fillStyle = '#FBBF24';
    ctx.fill();

    ctx.restore();
  };

  drawLeftCard();

  // 6. Right Telemetry Card — Compounding Ring & Yield Tier Bars
  const drawRightCard = () => {
    const cardW = 0.24 * S;
    const cardH = 0.34 * S;
    const cardX = cx + 0.58 * S - cardW * 0.5;
    const cardY = cy - cardH * 0.5;
    const cardR = 0.024 * S;

    ctx.save();
    roundRectPath(cardX, cardY, cardW, cardH, cardR);
    const cardGrad = ctx.createLinearGradient(cardX, cardY, cardX, cardY + cardH);
    cardGrad.addColorStop(0, '#271E11');
    cardGrad.addColorStop(1, '#151008');
    ctx.fillStyle = cardGrad;
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.003 * S);
    ctx.strokeStyle = '#6A4E21';
    ctx.stroke();

    // Top Half: Circular Compound Yield Ring
    const ringCx = cardX + cardW * 0.5;
    const ringCy = cardY + 0.104 * S;
    const ringR = 0.058 * S;
    const ringLW = 0.013 * S;
    const startA = -Math.PI * 0.5;
    const endA = startA + Math.PI * 2 * clamp01(ringRatio);

    ctx.beginPath();
    ctx.arc(ringCx, ringCy, ringR, 0, Math.PI * 2);
    ctx.lineWidth = ringLW;
    ctx.strokeStyle = '#0F0B06';
    ctx.stroke();

    const rGrad = ctx.createLinearGradient(ringCx - ringR, ringCy - ringR, ringCx + ringR, ringCy + ringR);
    rGrad.addColorStop(0, '#D97706');
    rGrad.addColorStop(0.5, '#FBBF24');
    rGrad.addColorStop(1, '#FEF3C7');

    ctx.beginPath();
    ctx.arc(ringCx, ringCy, ringR, startA, endA);
    ctx.lineWidth = ringLW;
    ctx.lineCap = 'round';
    ctx.strokeStyle = rGrad;
    ctx.stroke();

    // Tip marker dot
    ctx.beginPath();
    ctx.arc(ringCx + Math.cos(endA) * ringR, ringCy + Math.sin(endA) * ringR, 0.0082 * S, 0, Math.PI * 2);
    ctx.fillStyle = '#FFFBEB';
    ctx.fill();

    // Plus / Compound Cross Emblem Inside Ring
    ctx.save();
    ctx.translate(ringCx, ringCy);
    ctx.strokeStyle = '#FDE68A';
    ctx.lineWidth = Math.max(1, 0.0044 * S);
    ctx.lineCap = 'round';
    const pl = 0.018 * S;
    ctx.beginPath();
    ctx.moveTo(-pl, 0);
    ctx.lineTo(pl, 0);
    ctx.moveTo(0, -pl);
    ctx.lineTo(0, pl);
    ctx.stroke();
    ctx.restore();

    // Divider line
    const divY = cardY + 0.186 * S;
    roundRectPath(cardX + 0.036 * S, divY, cardW - 0.072 * S, 0.0025 * S, 0.00125 * S);
    ctx.fillStyle = '#5B431B';
    ctx.fill();

    // Bottom Half: 3 Compounding Tier Bars (Principal, Yield, Reinvested)
    const barX = cardX + 0.030 * S;
    const barW = cardW - 0.060 * S;
    const barH = 0.016 * S;
    const barGap = 0.015 * S;
    const barStart = cardY + 0.214 * S;
    const weights = [0.48, 0.74, 1.0];

    for (let i = 0; i < 3; i++) {
      const by = barStart + i * (barH + barGap);
      roundRectPath(barX, by, barW, barH, barH * 0.5);
      ctx.fillStyle = '#0F0B06';
      ctx.fill();

      const fillFrac = clamp01(weights[i] * tierProgress);
      const fw = Math.max(barH, barW * fillFrac);
      roundRectPath(barX, by, fw, barH, barH * 0.5);
      const bg = ctx.createLinearGradient(barX, by, barX + fw, by);
      bg.addColorStop(0, '#D97706');
      bg.addColorStop(1, '#FDE68A');
      ctx.fillStyle = bg;
      ctx.fill();
    }

    ctx.restore();
  };

  drawRightCard();

  // 7. Hero Centerpiece — Symmetric Precision Hourglass With World-Gravity Liquid Physics
  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate(flipAngle);

  // Dimensions (strictly top-bottom and left-right symmetric!)
  const capW = 0.300 * S;
  const capH = 0.026 * S;
  const capDist = 0.233 * S; // cap centers at +/-0.246*S -> outer corners +/-0.259*S
  const pillarX = 0.130 * S;
  const pillarW = 0.018 * S;
  const bulbHalfW = 0.102 * S;
  const bulbEndY = 0.233 * S; // flush against inner edge of top/bottom caps
  const neckHalfW = 0.013 * S;

  // A. Outer Vertical Support Pillars (Strictly clear of curved glass outer wall 0.102*S)
  [-1, 1].forEach((side) => {
    const px = side * pillarX - pillarW * 0.5;
    const py = -capDist;
    const ph = capDist * 2;
    roundRectPath(px, py, pillarW, ph, pillarW * 0.35);
    const pGrad = ctx.createLinearGradient(px, 0, px + pillarW, 0);
    pGrad.addColorStop(0, '#785319');
    pGrad.addColorStop(0.5, '#D97706');
    pGrad.addColorStop(1, '#92400E');
    ctx.fillStyle = pGrad;
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.002 * S);
    ctx.strokeStyle = '#FBBF24';
    ctx.stroke();
  });

  // B. Symmetric Bulb Path Builder (dir = -1 for Upper Chamber, +1 for Lower Chamber)
  const traceBulbChamber = (dir) => {
    const endY = dir * bulbEndY;
    const neckY = dir * 0.005 * S;
    ctx.beginPath();
    ctx.moveTo(-bulbHalfW, endY);
    ctx.lineTo(bulbHalfW, endY);
    ctx.bezierCurveTo(
      bulbHalfW,
      endY - dir * 0.115 * S,
      neckHalfW * 1.45,
      neckY + dir * 0.048 * S,
      neckHalfW,
      neckY
    );
    ctx.lineTo(-neckHalfW, neckY);
    ctx.bezierCurveTo(
      -neckHalfW * 1.45,
      neckY + dir * 0.048 * S,
      -bulbHalfW,
      endY - dir * 0.115 * S,
      -bulbHalfW,
      endY
    );
    ctx.closePath();
  };

  // Sample world-space Y min/max of a bulb at current flipAngle so liquid stays 100% gravity-leveled!
  const getWorldYBounds = (dir, theta) => {
    const endY = dir * bulbEndY;
    const neckY = dir * 0.005 * S;
    const centerY = dir * 0.119 * S;
    const cosT = Math.cos(theta);
    const sinT = Math.sin(theta);

    const evalCubic = (p0, p1, p2, p3, u) => {
      const m = 1 - u;
      return m * m * m * p0 + 3 * m * m * u * p1 + 3 * m * u * u * p2 + u * u * u * p3;
    };

    let minWY = Infinity;
    let maxWY = -Infinity;
    const samples = 14;
    for (let s = 0; s <= samples; s++) {
      const u = s / samples;
      const rx = evalCubic(bulbHalfW, bulbHalfW, neckHalfW * 1.45, neckHalfW, u);
      const ry = evalCubic(endY, endY - dir * 0.115 * S, neckY + dir * 0.048 * S, neckY, u) - centerY;
      [-rx, rx].forEach((px) => {
        const wy = px * sinT + ry * cosT;
        if (wy < minWY) minWY = wy;
        if (wy > maxWY) maxWY = wy;
      });
    }
    return { minWY, maxWY, centerY };
  };

  // Draw Crystal Bulb + Gravity-Leveled Golden Wealth Fluid
  const drawBulb = (dir, fillRatio, isReceivingStream) => {
    ctx.save();
    traceBulbChamber(dir);
    ctx.fillStyle = '#0D0A05';
    ctx.fill();
    ctx.clip();

    const { minWY, maxWY, centerY } = getWorldYBounds(dir, flipAngle);
    const spanY = maxWY - minWY;
    const surfY = lerp(maxWY, minWY, clamp01(fillRatio));

    // Rotate into world-gravity coordinate space around this bulb's center!
    ctx.save();
    ctx.translate(0, centerY);
    ctx.rotate(-flipAngle);

    // Falling golden wealth stream inside lower receiving chamber (when hourglass is upright)
    if (isReceivingStream && streamIntensity > 0.01 && Math.abs(flipAngle) < 0.08) {
      const streamTop = -centerY + 0.004 * S;
      const streamBot = surfY + 0.008 * S;
      const stW = 0.010 * S * streamIntensity;
      if (streamBot > streamTop) {
        ctx.beginPath();
        const stSteps = 16;
        for (let i = 0; i <= stSteps; i++) {
          const k = i / stSteps;
          const sy = lerp(streamTop, streamBot, k);
          const sway = Math.sin(k * Math.PI * 3 - wavePhase * 1.4) * 0.0018 * S * streamIntensity;
          const hw = stW * (0.52 - 0.12 * Math.sin(k * Math.PI * 0.5));
          if (i === 0) ctx.moveTo(-hw + sway, sy);
          else ctx.lineTo(-hw + sway, sy);
        }
        for (let i = stSteps; i >= 0; i--) {
          const k = i / stSteps;
          const sy = lerp(streamTop, streamBot, k);
          const sway = Math.sin(k * Math.PI * 3 - wavePhase * 1.4) * 0.0018 * S * streamIntensity;
          const hw = stW * (0.52 - 0.12 * Math.sin(k * Math.PI * 0.5));
          ctx.lineTo(hw + sway, sy);
        }
        ctx.closePath();
        ctx.fillStyle = '#FDE68A';
        ctx.fill();
      }
    }

    // Smooth liquid surface wave across world-horizontal axis
    const waveHalfW = 0.18 * S;
    const waveAmp = (0.0032 + (isReceivingStream ? 0.0028 * streamIntensity : 0)) * S;
    const wSteps = 26;

    // Back wave
    ctx.beginPath();
    ctx.moveTo(-waveHalfW, maxWY + 0.05 * S);
    for (let i = 0; i <= wSteps; i++) {
      const wx = lerp(-waveHalfW, waveHalfW, i / wSteps);
      const wy = surfY - 0.0025 * S + Math.sin((wx / waveHalfW) * Math.PI * 2 - wavePhase + 1.1) * (waveAmp * 0.8);
      ctx.lineTo(wx, wy);
    }
    ctx.lineTo(waveHalfW, maxWY + 0.05 * S);
    ctx.closePath();
    ctx.fillStyle = '#B45309';
    ctx.fill();

    // Front golden wave
    ctx.beginPath();
    ctx.moveTo(-waveHalfW, maxWY + 0.05 * S);
    for (let i = 0; i <= wSteps; i++) {
      const wx = lerp(-waveHalfW, waveHalfW, i / wSteps);
      const wy = surfY + Math.sin((wx / waveHalfW) * Math.PI * 2 + wavePhase) * waveAmp;
      ctx.lineTo(wx, wy);
    }
    ctx.lineTo(waveHalfW, maxWY + 0.05 * S);
    ctx.closePath();
    const lGrad = ctx.createLinearGradient(0, surfY, 0, maxWY + 0.01 * S);
    lGrad.addColorStop(0, '#FBBF24');
    lGrad.addColorStop(0.55, '#D97706');
    lGrad.addColorStop(1, '#92400E');
    ctx.fillStyle = lGrad;
    ctx.fill();

    // Crisp bright crest highlight
    ctx.beginPath();
    for (let i = 0; i <= wSteps; i++) {
      const wx = lerp(-waveHalfW, waveHalfW, i / wSteps);
      const wy = surfY + Math.sin((wx / waveHalfW) * Math.PI * 2 + wavePhase) * waveAmp;
      if (i === 0) ctx.moveTo(wx, wy);
      else ctx.lineTo(wx, wy);
    }
    ctx.lineWidth = Math.max(1, 0.0028 * S);
    ctx.strokeStyle = '#FEF3C7';
    ctx.stroke();

    // Subtle rising golden shimmer motes strictly inside liquid region
    if (spanY > 0.04 * S) {
      for (let m = 0; m < 4; m++) {
        const mProg = (loopNorm * 3 + m * 0.25) % 1;
        const mx = (-0.045 + m * 0.030) * S;
        const mTop = surfY + 0.012 * S;
        const mBot = maxWY - 0.012 * S;
        if (mBot > mTop) {
          const my = lerp(mBot, mTop, mProg);
          ctx.save();
          ctx.globalAlpha = Math.sin(mProg * Math.PI) * 0.72;
          ctx.beginPath();
          ctx.arc(mx, my, 0.0026 * S, 0, Math.PI * 2);
          ctx.fillStyle = '#FFFBEB';
          ctx.fill();
          ctx.restore();
        }
      }
    }

    ctx.restore(); // End world-gravity space
    ctx.restore(); // End bulb clip

    // Crisp Glass Chamber Rim Outline
    traceBulbChamber(dir);
    ctx.lineWidth = Math.max(1, 0.0032 * S);
    ctx.strokeStyle = '#F59E0B';
    ctx.stroke();
  };

  drawBulb(-1, upperBulbFill, false);
  drawBulb(1, lowerBulbFill, true);

  // C. Sleek Central Waist Collar Ring Around Glass Neck
  const waistW = 0.052 * S;
  const waistH = 0.014 * S;
  roundRectPath(-waistW * 0.5, -waistH * 0.5, waistW, waistH, waistH * 0.45);
  ctx.fillStyle = '#B45309';
  ctx.fill();
  ctx.lineWidth = Math.max(1, 0.0024 * S);
  ctx.strokeStyle = '#FDE68A';
  ctx.stroke();

  // D. Symmetric Top & Bottom End Caps
  [-1, 1].forEach((dir) => {
    const capTop = dir < 0 ? -capDist - capH : capDist;
    roundRectPath(-capW * 0.5, capTop, capW, capH, capH * 0.45);
    const cGrad = ctx.createLinearGradient(-capW * 0.5, capTop, capW * 0.5, capTop);
    cGrad.addColorStop(0, '#92400E');
    cGrad.addColorStop(0.5, '#F59E0B');
    cGrad.addColorStop(1, '#92400E');
    ctx.fillStyle = cGrad;
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.0028 * S);
    ctx.strokeStyle = '#FDE68A';
    ctx.stroke();

    // Clean decorative center accent bar on cap
    roundRectPath(-0.054 * S, capTop + capH * 0.34, 0.108 * S, capH * 0.32, capH * 0.16);
    ctx.fillStyle = '#452607';
    ctx.fill();
  });

  ctx.restore(); // End rotated hourglass assembly
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const S = minSide;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const easeInOutCubic = (x) => {
    const v = clamp01(x);
    return v < 0.5 ? 4 * v * v * v : 1 - Math.pow(-2 * v + 2, 3) / 2;
  };
  const easeOutCubic = (x) => {
    const v = clamp01(x);
    return 1 - Math.pow(1 - v, 3);
  };
  const easeInOutSine = (x) => {
    const v = clamp01(x);
    return -(Math.cos(Math.PI * v) - 1) * 0.5;
  };
  const lerp = (a, b, k) => a + (b - a) * k;

  const roundRectPath = (x, y, w, h, r) => {
    const rad = Math.max(0, Math.min(r, w * 0.5, h * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  };

  const drawDollarSign = (x, y, size, color, lw) => {
    ctx.save();
    ctx.translate(x, y);
    ctx.strokeStyle = color;
    ctx.lineWidth = lw;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.beginPath();
    ctx.moveTo(0, -size * 1.12);
    ctx.lineTo(0, size * 1.12);
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(size * 0.65, -size * 0.48);
    ctx.bezierCurveTo(size * 0.62, -size * 0.90, -size * 0.68, -size * 0.90, -size * 0.65, -size * 0.35);
    ctx.bezierCurveTo(-size * 0.62, 0, size * 0.65, 0, size * 0.65, size * 0.38);
    ctx.bezierCurveTo(size * 0.65, size * 0.90, -size * 0.65, size * 0.90, -size * 0.68, size * 0.48);
    ctx.stroke();
    ctx.restore();
  };

  // 1. Clean Modern Dark Aesthetic Gradient Background (Zero Glow, Zero Borders)
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, '#040817');
  bgGrad.addColorStop(0.5, '#081330');
  bgGrad.addColorStop(1, '#0D1F49');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // 2. Timeline Motion Curves Driven by t, loopT, currentScene, sceneProgress
  const loopNorm = loopT / duration;
  const gentleBreath = Math.sin(loopNorm * Math.PI * 2 * 5);

  let phoneMorph = 0;
  let uiReveal = 0;
  let tileStagger = [0, 0, 0];
  let railProgress = 0;
  let satScales = [0, 0, 0, 0]; // [Banknotes, Card, Shield, Coins]
  let railFlowIntensity = 0;
  let activeStep = 0;
  let cardSheenPos = -0.4;
  let nfcPulse = 0;
  let shieldCheck = 0;
  let coinDrop = 0;
  let balanceBarFill = 0.55;

  if (currentScene === 0) {
    // Scene 0 (0-5s): Fintech Core smoothly expands into Smartphone + UI initializes + rails extend
    phoneMorph = easeInOutCubic(sceneProgress / 0.28);
    uiReveal = easeInOutCubic((sceneProgress - 0.14) / 0.28);
    for (let i = 0; i < 3; i++) {
      tileStagger[i] = easeOutCubic((sceneProgress - (0.30 + i * 0.08)) / 0.22);
    }
    railProgress = easeInOutCubic((sceneProgress - 0.66) / 0.30);
    balanceBarFill = lerp(0.32, 0.62, easeInOutCubic((sceneProgress - 0.24) / 0.60));
  } else if (currentScene === 1) {
    // Scene 1 (5-10s): Staggered deployment of all 4 separated financial modules
    phoneMorph = 1;
    uiReveal = 1;
    tileStagger = [1, 1, 1];
    railProgress = 1;
    railFlowIntensity = easeInOutSine(sceneProgress);
    satScales[0] = easeOutCubic((sceneProgress - 0.05) / 0.28);
    satScales[1] = easeOutCubic((sceneProgress - 0.20) / 0.28);
    satScales[2] = easeOutCubic((sceneProgress - 0.35) / 0.28);
    satScales[3] = easeOutCubic((sceneProgress - 0.50) / 0.30);
    coinDrop = easeOutCubic((sceneProgress - 0.55) / 0.38);
    balanceBarFill = lerp(0.62, 0.80, easeInOutSine(sceneProgress));
    nfcPulse = clamp01((sceneProgress - 0.30) / 0.65) * 0.5;
    activeStep = Math.floor(sceneProgress * 2.99);
  } else if (currentScene === 2) {
    // Scene 2 (10-15s): Synchronized fintech ecosystem activity
    phoneMorph = 1;
    uiReveal = 1;
    tileStagger = [1, 1, 1];
    railProgress = 1;
    satScales = [1, 1, 1, 1];
    coinDrop = 1;
    railFlowIntensity = 0.85 + 0.15 * Math.sin(sceneProgress * Math.PI * 2);
    shieldCheck = easeInOutCubic((sceneProgress - 0.06) / 0.45);
    cardSheenPos = lerp(-0.35, 1.35, easeInOutSine(clamp01((sceneProgress - 0.12) / 0.70)));
    nfcPulse = 0.5 + 0.5 * Math.sin(sceneProgress * Math.PI * 2 * 2);
    balanceBarFill = lerp(0.80, 0.94, easeInOutSine(sceneProgress));
    activeStep = sceneProgress * 3;
  } else {
    // Scene 3 (15-20s): Clean reverse deactivation back to exact Fintech Core at t = 20
    phoneMorph = 1 - easeInOutCubic((sceneProgress - 0.72) / 0.28);
    uiReveal = 1 - easeInOutCubic((sceneProgress - 0.56) / 0.24);
    for (let i = 0; i < 3; i++) {
      tileStagger[i] = 1 - easeInOutCubic((sceneProgress - (0.44 + i * 0.04)) / 0.18);
    }
    shieldCheck = 1 - easeInOutCubic(sceneProgress / 0.26);
    satScales[3] = 1 - easeInOutCubic((sceneProgress - 0.08) / 0.24);
    satScales[2] = 1 - easeInOutCubic((sceneProgress - 0.14) / 0.24);
    satScales[1] = 1 - easeInOutCubic((sceneProgress - 0.20) / 0.24);
    satScales[0] = 1 - easeInOutCubic((sceneProgress - 0.26) / 0.24);
    coinDrop = satScales[3];
    railProgress = 1 - easeInOutCubic((sceneProgress - 0.42) / 0.24);
    railFlowIntensity = lerp(0.85, 0, easeInOutCubic(sceneProgress / 0.38));
    balanceBarFill = lerp(0.94, 0.32, easeInOutCubic(sceneProgress / 0.55));
    activeStep = 0;
  }

  // 3. Grounding Pedestal Pill Beneath Smartphone (Never touches phone bezel)
  ctx.save();
  const pedW = lerp(0.14 * S, 0.28 * S, phoneMorph);
  const pedH = 0.018 * S;
  const pedY = lerp(cy + 0.115 * S, cy + 0.312 * S, phoneMorph);
  roundRectPath(cx - pedW * 0.5, pedY, pedW, pedH, pedH * 0.5);
  ctx.fillStyle = '#030816';
  ctx.fill();
  ctx.lineWidth = Math.max(1, 0.002 * S);
  ctx.strokeStyle = '#18346E';
  ctx.stroke();
  ctx.restore();

  // 4. Orthogonal Connector Rails Between Smartphone Ports (+/-0.160*S) & Satellite Ports (+/-0.285*S)
  if (railProgress > 0.005) {
    const rails = [
      { sx: cx - 0.160 * S, ex: cx - 0.285 * S, y: cy - 0.145 * S, dir: -1 },
      { sx: cx + 0.160 * S, ex: cx + 0.285 * S, y: cy - 0.145 * S, dir: 1 },
      { sx: cx - 0.160 * S, ex: cx - 0.285 * S, y: cy + 0.145 * S, dir: -1 },
      { sx: cx + 0.160 * S, ex: cx + 0.285 * S, y: cy + 0.145 * S, dir: 1 },
    ];

    rails.forEach((rail, idx) => {
      ctx.save();
      const curEx = lerp(rail.sx, rail.ex, railProgress);
      const trackX = Math.min(rail.sx, curEx);
      const trackW = Math.abs(curEx - rail.sx);
      const trackH = 0.008 * S;

      // Base rail track
      roundRectPath(trackX, rail.y - trackH * 0.5, trackW, trackH, trackH * 0.5);
      ctx.fillStyle = '#112554';
      ctx.fill();
      ctx.lineWidth = Math.max(1, 0.0018 * S);
      ctx.strokeStyle = '#2563EB';
      ctx.stroke();

      // Anchor nodes with crisp air gap from both Smartphone & Satellite borders
      const nodeR = 0.007 * S;
      ctx.beginPath();
      ctx.arc(rail.sx, rail.y, nodeR, 0, Math.PI * 2);
      ctx.fillStyle = '#0B1A3D';
      ctx.fill();
      ctx.lineWidth = Math.max(1, 0.0022 * S);
      ctx.strokeStyle = '#38BDF8';
      ctx.stroke();

      if (railProgress > 0.25) {
        ctx.beginPath();
        ctx.arc(curEx, rail.y, nodeR, 0, Math.PI * 2);
        ctx.fillStyle = '#0B1A3D';
        ctx.fill();
        ctx.strokeStyle = '#38BDF8';
        ctx.stroke();
      }

      // Clipped signal packet traveling along rail
      if (railFlowIntensity > 0.02 && trackW > 0.03 * S) {
        ctx.save();
        roundRectPath(trackX + 0.008 * S, rail.y - trackH * 0.4, Math.max(0, trackW - 0.016 * S), trackH * 0.8, trackH * 0.4);
        ctx.clip();

        const pktW = 0.024 * S;
        const speedCycles = 4; // Exact integer over 20s
        for (let p = 0; p < 2; p++) {
          const ph = (loopNorm * speedCycles + p * 0.5 + idx * 0.125) % 1;
          const posNorm = rail.dir > 0 ? ph : 1 - ph;
          const px = trackX - pktW + posNorm * (trackW + pktW);
          ctx.globalAlpha = clamp01(railFlowIntensity * Math.sin(ph * Math.PI) * 1.2);
          roundRectPath(px, rail.y - trackH * 0.35, pktW, trackH * 0.7, trackH * 0.35);
          ctx.fillStyle = '#7DD3FC';
          ctx.fill();
        }
        ctx.restore();
      }

      ctx.restore();
    });
  }

  // 5. Center Hero Core / Fintech Smartphone
  const phoneW = lerp(0.14 * S, 0.27 * S, phoneMorph);
  const phoneH = lerp(0.14 * S, 0.54 * S, phoneMorph);
  const phoneR = lerp(0.034 * S, 0.036 * S, phoneMorph);
  const phoneX = cx - phoneW * 0.5;
  const phoneY = cy - phoneH * 0.5;

  // Compact Core Subtle Breathing Ring (only visible while core is compact, well inside empty center)
  if (phoneMorph < 0.85) {
    ctx.save();
    const coreRingAlpha = clamp01(1 - phoneMorph * 1.25);
    const ringExp = 0.088 * S + (0.014 * S) * (0.5 + 0.5 * gentleBreath);
    ctx.globalAlpha = coreRingAlpha * 0.55;
    roundRectPath(cx - ringExp, cy - ringExp, ringExp * 2, ringExp * 2, 0.040 * S);
    ctx.lineWidth = Math.max(1, 0.0028 * S);
    ctx.strokeStyle = '#38BDF8';
    ctx.stroke();
    ctx.restore();
  }

  // Smartphone Outer Chassis
  ctx.save();
  roundRectPath(phoneX, phoneY, phoneW, phoneH, phoneR);
  const chassisGrad = ctx.createLinearGradient(phoneX, phoneY, phoneX + phoneW, phoneY + phoneH);
  chassisGrad.addColorStop(0, '#172E66');
  chassisGrad.addColorStop(0.5, '#10214B');
  chassisGrad.addColorStop(1, '#0B1736');
  ctx.fillStyle = chassisGrad;
  ctx.fill();

  ctx.lineWidth = Math.max(1, 0.004 * S);
  ctx.strokeStyle = '#38BDF8';
  ctx.stroke();

  // Compact Core Emblem (crossfades smoothly with UI so screen is never blank)
  if (uiReveal < 0.99) {
    ctx.save();
    ctx.globalAlpha = clamp01(1 - uiReveal * 1.15);
    const embR = 0.036 * S;
    ctx.beginPath();
    ctx.arc(cx, cy, embR, 0, Math.PI * 2);
    ctx.fillStyle = '#07112B';
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.003 * S);
    ctx.strokeStyle = '#60A5FA';
    ctx.stroke();
    drawDollarSign(cx, cy, 0.015 * S, '#38BDF8', Math.max(1, 0.0035 * S));
    ctx.restore();
  }

  // Expanded Smartphone Screen & Internal Mobile Fintech UI
  if (uiReveal > 0.01) {
    const scrPadX = 0.014 * S;
    const scrPadY = 0.016 * S;
    const scrX = phoneX + scrPadX;
    const scrY = phoneY + scrPadY;
    const scrW = Math.max(0.01 * S, phoneW - scrPadX * 2);
    const scrH = Math.max(0.01 * S, phoneH - scrPadY * 2);
    const scrR = 0.024 * S;

    ctx.save();
    roundRectPath(scrX, scrY, scrW, scrH, scrR);
    ctx.clip();

    // Screen deep background
    ctx.fillStyle = '#060E24';
    ctx.fillRect(scrX, scrY, scrW, scrH);

    ctx.globalAlpha = clamp01(uiReveal);

    // Top Speaker Notch Pill
    const notchW = 0.068 * S;
    const notchH = 0.010 * S;
    roundRectPath(cx - notchW * 0.5, scrY + 0.014 * S, notchW, notchH, notchH * 0.5);
    ctx.fillStyle = '#112452';
    ctx.fill();

    const contentPad = 0.016 * S;
    const contentW = scrW - contentPad * 2;
    const contentX = scrX + contentPad;

    // UI Section 1: Top Balance Card
    const balY = scrY + 0.040 * S + (1 - uiReveal) * 0.016 * S;
    const balH = 0.122 * S;
    roundRectPath(contentX, balY, contentW, balH, 0.016 * S);
    const balGrad = ctx.createLinearGradient(contentX, balY, contentX + contentW, balY + balH);
    balGrad.addColorStop(0, '#0284C7');
    balGrad.addColorStop(1, '#06B6D4');
    ctx.fillStyle = balGrad;
    ctx.fill();

    // Balance card inner badge & crisp geometric bars
    const cBadgeCx = contentX + 0.036 * S;
    const cBadgeCy = balY + 0.046 * S;
    ctx.beginPath();
    ctx.arc(cBadgeCx, cBadgeCy, 0.020 * S, 0, Math.PI * 2);
    ctx.fillStyle = '#0C4A6E';
    ctx.fill();
    drawDollarSign(cBadgeCx, cBadgeCy, 0.0095 * S, '#BAE6FD', Math.max(1, 0.0026 * S));

    roundRectPath(contentX + 0.070 * S, balY + 0.032 * S, 0.112 * S, 0.011 * S, 0.0055 * S);
    ctx.fillStyle = '#F0F9FF';
    ctx.fill();
    roundRectPath(contentX + 0.070 * S, balY + 0.052 * S, 0.074 * S, 0.008 * S, 0.004 * S);
    ctx.fillStyle = '#BAE6FD';
    ctx.fill();

    // Balance Card Bottom Progress Bar
    const bTrackX = contentX + 0.018 * S;
    const bTrackY = balY + 0.088 * S;
    const bTrackW = contentW - 0.036 * S;
    const bTrackH = 0.012 * S;
    roundRectPath(bTrackX, bTrackY, bTrackW, bTrackH, bTrackH * 0.5);
    ctx.fillStyle = '#075985';
    ctx.fill();

    roundRectPath(bTrackX, bTrackY, Math.max(bTrackH, bTrackW * clamp01(balanceBarFill)), bTrackH, bTrackH * 0.5);
    ctx.fillStyle = '#E0F2FE';
    ctx.fill();

    // UI Section 2: 3 Quick-Action Tiles (Aligned identically to contentW)
    const tileY = scrY + 0.180 * S;
    const tileGap = 0.014 * S;
    const tileS = (contentW - tileGap * 2) / 3;

    for (let i = 0; i < 3; i++) {
      const sc = tileStagger[i];
      if (sc <= 0.01) continue;
      const tCx = contentX + i * (tileS + tileGap) + tileS * 0.5;
      const tCy = tileY + tileS * 0.5;
      const isHighlighted = currentScene === 2 && Math.floor(activeStep) === i;

      ctx.save();
      ctx.translate(tCx, tCy);
      ctx.scale(sc, sc);

      roundRectPath(-tileS * 0.5, -tileS * 0.5, tileS, tileS, 0.013 * S);
      ctx.fillStyle = isHighlighted ? '#13316D' : '#0B1A3D';
      ctx.fill();
      ctx.lineWidth = Math.max(1, 0.0022 * S);
      ctx.strokeStyle = isHighlighted ? '#38BDF8' : '#1E3A8A';
      ctx.stroke();

      // Clean distinct icon inside each tile
      ctx.strokeStyle = i === 0 ? '#38BDF8' : i === 1 ? '#60A5FA' : '#34D399';
      ctx.lineWidth = Math.max(1, 0.0026 * S);
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      const ic = tileS * 0.24;

      if (i === 0) {
        // Transfer arrows
        ctx.beginPath();
        ctx.moveTo(-ic, -ic * 0.35);
        ctx.lineTo(ic, -ic * 0.35);
        ctx.moveTo(ic * 0.45, -ic * 0.80);
        ctx.lineTo(ic, -ic * 0.35);
        ctx.lineTo(ic * 0.45, ic * 0.10);

        ctx.moveTo(ic, ic * 0.45);
        ctx.lineTo(-ic, ic * 0.45);
        ctx.moveTo(-ic * 0.45, ic * 0.0);
        ctx.lineTo(-ic, ic * 0.45);
        ctx.lineTo(-ic * 0.45, ic * 0.90);
        ctx.stroke();
      } else if (i === 1) {
        // Card mini icon
        roundRectPath(-ic * 1.05, -ic * 0.72, ic * 2.1, ic * 1.44, ic * 0.28);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(-ic * 1.0, -ic * 0.18);
        ctx.lineTo(ic * 1.0, -ic * 0.18);
        ctx.stroke();
      } else {
        // 3 mini vertical bars
        ctx.fillStyle = '#34D399';
        const bw = ic * 0.44;
        const heights = [0.65, 1.05, 1.45];
        for (let b = 0; b < 3; b++) {
          const bx = -ic * 0.92 + b * (bw + ic * 0.26);
          const bh = ic * heights[b];
          roundRectPath(bx, ic * 0.85 - bh, bw, bh, bw * 0.35);
          ctx.fill();
        }
      }

      ctx.restore();
    }

    // UI Section 3: Bottom Transaction Ledger (3 Clean Rows)
    const ledY = scrY + 0.258 * S;
    const ledH = scrH - 0.276 * S;
    roundRectPath(contentX, ledY, contentW, ledH, 0.016 * S);
    ctx.fillStyle = '#091533';
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.002 * S);
    ctx.strokeStyle = '#17306B';
    ctx.stroke();

    const rowColors = ['#10B981', '#38BDF8', '#F59E0B'];
    const rowPad = 0.014 * S;
    const rowGap = 0.012 * S;
    const rowH = (ledH - rowPad * 2 - rowGap * 2) / 3;
    const rowW = contentW - rowPad * 2;

    for (let r = 0; r < 3; r++) {
      const rx = contentX + rowPad;
      const ry = ledY + rowPad + r * (rowH + rowGap);
      const isRowActive = currentScene === 2 && Math.floor(activeStep) === r;

      roundRectPath(rx, ry, rowW, rowH, 0.010 * S);
      ctx.fillStyle = isRowActive ? '#122B62' : '#0D1E46';
      ctx.fill();

      // Status dot
      ctx.beginPath();
      ctx.arc(rx + 0.022 * S, ry + rowH * 0.5, 0.009 * S, 0, Math.PI * 2);
      ctx.fillStyle = rowColors[r];
      ctx.fill();

      // Label bars
      const barW1 = (0.068 - r * 0.008) * S;
      roundRectPath(rx + 0.042 * S, ry + rowH * 0.32, barW1, 0.007 * S, 0.0035 * S);
      ctx.fillStyle = '#CBD5E1';
      ctx.fill();
      roundRectPath(rx + 0.042 * S, ry + rowH * 0.58, 0.042 * S, 0.005 * S, 0.0025 * S);
      ctx.fillStyle = '#3B5998';
      ctx.fill();

      // Right amount pill
      roundRectPath(rx + rowW - 0.052 * S, ry + rowH * 0.36, 0.038 * S, 0.012 * S, 0.006 * S);
      ctx.fillStyle = rowColors[r];
      ctx.fill();
    }

    ctx.restore(); // End clipped screen
  }
  ctx.restore(); // End phone chassis

  // 6. Four Cleanly Separated Satellite Financial Modules

  // Satellite 1 (Top-Left): Layered Banknotes Stack
  const drawBanknotesSatellite = (scale) => {
    if (scale <= 0.01) return;
    const bx = cx - 0.415 * S;
    const by = cy - 0.145 * S;
    const noteW = 0.190 * S;
    const noteH = 0.102 * S;

    ctx.save();
    ctx.translate(bx, by);
    ctx.scale(scale, scale);

    // Synchronized stepped upper note ledges with crisp air gaps (zero overlap)
    const fy = 0.014 * S;
    const frontTop = -noteH * 0.5 + fy;
    const breathShift = 0.0022 * S * gentleBreath;
    const ledgeH = 0.009 * S;
    const ledgeGap = 0.0045 * S;

    const ledges = [
      { dy: frontTop - ledgeGap * 2 - ledgeH * 2 - breathShift, wScale: 0.80, fill: '#047857', stroke: '#34D399' },
      { dy: frontTop - ledgeGap - ledgeH - breathShift * 0.5, wScale: 0.90, fill: '#059669', stroke: '#6EE7B7' },
    ];
    ledges.forEach((lay) => {
      const lw = noteW * lay.wScale;
      roundRectPath(-lw * 0.5, lay.dy, lw, ledgeH, ledgeH * 0.45);
      ctx.fillStyle = lay.fill;
      ctx.fill();
      ctx.lineWidth = Math.max(1, 0.002 * S);
      ctx.strokeStyle = lay.stroke;
      ctx.stroke();
    });

    // Main front banknote
    roundRectPath(-noteW * 0.5, frontTop, noteW, noteH, 0.014 * S);
    const noteGrad = ctx.createLinearGradient(-noteW * 0.5, fy - noteH * 0.5, noteW * 0.5, fy + noteH * 0.5);
    noteGrad.addColorStop(0, '#10B981');
    noteGrad.addColorStop(1, '#059669');
    ctx.fillStyle = noteGrad;
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.003 * S);
    ctx.strokeStyle = '#6EE7B7';
    ctx.stroke();

    // Inner clean border rectangle
    const pad = 0.010 * S;
    roundRectPath(-noteW * 0.5 + pad, -noteH * 0.5 + fy + pad, noteW - pad * 2, noteH - pad * 2, 0.008 * S);
    ctx.lineWidth = Math.max(1, 0.002 * S);
    ctx.strokeStyle = '#A7F3D0';
    ctx.stroke();

    // Center circular seal + crisp '$'
    ctx.beginPath();
    ctx.arc(0, fy, 0.025 * S, 0, Math.PI * 2);
    ctx.fillStyle = '#064E3B';
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.0022 * S);
    ctx.strokeStyle = '#6EE7B7';
    ctx.stroke();
    drawDollarSign(0, fy, 0.012 * S, '#ECFDF5', Math.max(1, 0.0028 * S));

    // Corner decorative dots
    [-1, 1].forEach((sx) => {
      ctx.beginPath();
      ctx.arc(sx * (noteW * 0.5 - 0.024 * S), fy, 0.005 * S, 0, Math.PI * 2);
      ctx.fillStyle = '#A7F3D0';
      ctx.fill();
    });

    ctx.restore();
  };

  // Satellite 2 (Top-Right): Smart Payment Card
  const drawCardSatellite = (scale) => {
    if (scale <= 0.01) return;
    const kx = cx + 0.415 * S;
    const ky = cy - 0.145 * S;
    const cW = 0.204 * S;
    const cH = 0.126 * S;
    const cR = 0.016 * S;

    ctx.save();
    ctx.translate(kx, ky);
    ctx.scale(scale, scale);

    roundRectPath(-cW * 0.5, -cH * 0.5, cW, cH, cR);
    ctx.save();
    ctx.clip();

    const cardGrad = ctx.createLinearGradient(-cW * 0.5, -cH * 0.5, cW * 0.5, cH * 0.5);
    cardGrad.addColorStop(0, '#2563EB');
    cardGrad.addColorStop(0.55, '#0284C7');
    cardGrad.addColorStop(1, '#0EA5E9');
    ctx.fillStyle = cardGrad;
    ctx.fillRect(-cW * 0.5, -cH * 0.5, cW, cH);

    // Subtle geometric accent arc clipped inside card
    ctx.beginPath();
    ctx.arc(cW * 0.38, cH * 0.45, cW * 0.42, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(255, 255, 255, 0.09)';
    ctx.fill();

    // Diagonal light sheen sweep
    if (cardSheenPos > -0.3 && cardSheenPos < 1.3) {
      const shX = lerp(-cW * 0.85, cW * 0.85, cardSheenPos);
      ctx.save();
      ctx.translate(shX, 0);
      ctx.rotate(0.45);
      ctx.fillStyle = 'rgba(224, 242, 254, 0.26)';
      ctx.fillRect(-0.018 * S, -cH, 0.036 * S, cH * 2);
      ctx.restore();
    }

    // Gold EMV Chip
    const chipX = -cW * 0.5 + 0.022 * S;
    const chipY = -cH * 0.5 + 0.028 * S;
    const chipW = 0.034 * S;
    const chipH = 0.026 * S;
    roundRectPath(chipX, chipY, chipW, chipH, 0.005 * S);
    ctx.fillStyle = '#FBBF24';
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.0018 * S);
    ctx.strokeStyle = '#FEF3C7';
    ctx.stroke();

    // Chip internal cross traces
    ctx.beginPath();
    ctx.moveTo(chipX + chipW * 0.35, chipY);
    ctx.lineTo(chipX + chipW * 0.35, chipY + chipH);
    ctx.moveTo(chipX + chipW * 0.65, chipY);
    ctx.lineTo(chipX + chipW * 0.65, chipY + chipH);
    ctx.moveTo(chipX, chipY + chipH * 0.5);
    ctx.lineTo(chipX + chipW, chipY + chipH * 0.5);
    ctx.strokeStyle = '#B45309';
    ctx.lineWidth = Math.max(1, 0.0014 * S);
    ctx.stroke();

    // Animated Contactless NFC Arcs (Upper Right)
    const nfcX = cW * 0.5 - 0.034 * S;
    const nfcY = -cH * 0.5 + 0.038 * S;
    for (let w = 0; w < 3; w++) {
      const waveActive = clamp01(nfcPulse * 1.4 - w * 0.25);
      ctx.beginPath();
      ctx.arc(nfcX, nfcY, (0.009 + w * 0.0065) * S, -0.75, 0.75);
      ctx.lineWidth = Math.max(1, 0.0024 * S);
      ctx.lineCap = 'round';
      ctx.strokeStyle = waveActive > 0.3 ? '#F0F9FF' : 'rgba(240, 249, 255, 0.45)';
      ctx.stroke();
    }

    // Crisp Masked Number Dot Groups (Lower Row)
    const dotY = cH * 0.5 - 0.024 * S;
    for (let g = 0; g < 3; g++) {
      const gx = -cW * 0.5 + 0.024 * S + g * 0.044 * S;
      for (let d = 0; d < 4; d++) {
        ctx.beginPath();
        ctx.arc(gx + d * 0.0075 * S, dotY, 0.0026 * S, 0, Math.PI * 2);
        ctx.fillStyle = '#E0F2FE';
        ctx.fill();
      }
    }

    // Bottom right twin status bars
    roundRectPath(cW * 0.5 - 0.048 * S, dotY - 0.005 * S, 0.028 * S, 0.010 * S, 0.005 * S);
    ctx.fillStyle = '#FBBF24';
    ctx.fill();

    ctx.restore(); // End card clip

    // Crisp Outer Card Border
    roundRectPath(-cW * 0.5, -cH * 0.5, cW, cH, cR);
    ctx.lineWidth = Math.max(1, 0.003 * S);
    ctx.strokeStyle = '#7DD3FC';
    ctx.stroke();

    ctx.restore();
  };

  // Satellite 3 (Bottom-Left): Cyber Security Circuit Shield
  const drawShieldSatellite = (scale) => {
    if (scale <= 0.01) return;
    const sx = cx - 0.415 * S;
    const sy = cy + 0.145 * S;
    const shW = 0.138 * S;
    const shH = 0.160 * S;

    ctx.save();
    ctx.translate(sx, sy);
    ctx.scale(scale, scale);

    // Side non-touching crisp circuit ticks (strictly 0.016*S outside shield edge)
    [-1, 1].forEach((dir) => {
      const lineX1 = dir * (shW * 0.5 + 0.014 * S);
      const lineX2 = dir * (shW * 0.5 + 0.032 * S);
      ctx.beginPath();
      ctx.moveTo(lineX1, -0.016 * S);
      ctx.lineTo(lineX2, -0.016 * S);
      ctx.moveTo(lineX1, 0.016 * S);
      ctx.lineTo(lineX2 - dir * 0.006 * S, 0.016 * S);
      ctx.lineWidth = Math.max(1, 0.0025 * S);
      ctx.lineCap = 'round';
      ctx.strokeStyle = shieldCheck > 0.2 ? '#38BDF8' : '#1E40AF';
      ctx.stroke();

      ctx.beginPath();
      ctx.arc(lineX2, -0.016 * S, 0.0035 * S, 0, Math.PI * 2);
      ctx.fillStyle = shieldCheck > 0.2 ? '#7DD3FC' : '#2563EB';
      ctx.fill();
    });

    const traceShield = (wScale, hScale) => {
      const w = shW * wScale;
      const h = shH * hScale;
      ctx.beginPath();
      ctx.moveTo(0, -h * 0.5);
      ctx.lineTo(w * 0.5, -h * 0.30);
      ctx.lineTo(w * 0.44, h * 0.12);
      ctx.quadraticCurveTo(w * 0.34, h * 0.38, 0, h * 0.52);
      ctx.quadraticCurveTo(-w * 0.34, h * 0.38, -w * 0.44, h * 0.12);
      ctx.lineTo(-w * 0.5, -h * 0.30);
      ctx.closePath();
    };

    // Main shield body
    traceShield(1, 1);
    const shGrad = ctx.createLinearGradient(0, -shH * 0.5, 0, shH * 0.5);
    shGrad.addColorStop(0, '#0284C7');
    shGrad.addColorStop(1, '#0C4A6E');
    ctx.fillStyle = shGrad;
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.0035 * S);
    ctx.strokeStyle = '#7DD3FC';
    ctx.stroke();

    // Inner recessed shield
    traceShield(0.76, 0.76);
    ctx.fillStyle = '#082F49';
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.002 * S);
    ctx.strokeStyle = '#38BDF8';
    ctx.stroke();

    // Animated Checkmark
    if (shieldCheck > 0.01) {
      const p1 = { x: -shW * 0.19, y: shH * 0.01 };
      const p2 = { x: -shW * 0.03, y: shH * 0.15 };
      const p3 = { x: shW * 0.21, y: -shH * 0.12 };

      const l1 = Math.hypot(p2.x - p1.x, p2.y - p1.y);
      const l2 = Math.hypot(p3.x - p2.x, p3.y - p2.y);
      const drawL = (l1 + l2) * clamp01(shieldCheck);

      ctx.beginPath();
      ctx.moveTo(p1.x, p1.y);
      if (drawL <= l1) {
        const k = drawL / l1;
        ctx.lineTo(lerp(p1.x, p2.x, k), lerp(p1.y, p2.y, k));
      } else {
        ctx.lineTo(p2.x, p2.y);
        const k = (drawL - l1) / l2;
        ctx.lineTo(lerp(p2.x, p3.x, k), lerp(p2.y, p3.y, k));
      }
      ctx.lineWidth = Math.max(1, 0.006 * S);
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.strokeStyle = '#6EE7B7';
      ctx.stroke();
    } else {
      ctx.beginPath();
      ctx.arc(0, 0, 0.010 * S, 0, Math.PI * 2);
      ctx.fillStyle = '#38BDF8';
      ctx.fill();
    }

    ctx.restore();
  };

  // Satellite 4 (Bottom-Right): Gold Coin Yield Stacks + Medallion (Zero Overlapping)
  const drawCoinsSatellite = (scale) => {
    if (scale <= 0.01) return;
    const gx = cx + 0.415 * S;
    const gy = cy + 0.145 * S;

    ctx.save();
    ctx.translate(gx, gy);
    ctx.scale(scale, scale);

    const baseW = 0.224 * S;
    const baseH = 0.007 * S;
    const baseY = 0.072 * S;

    // Clean baseline platform
    roundRectPath(-baseW * 0.5, baseY, baseW, baseH, baseH * 0.5);
    ctx.fillStyle = '#1E3A8A';
    ctx.fill();

    // Two distinct parallel stacks + front medallion column (symmetric margins, zero overlap)
    const stackW = 0.054 * S;
    const coinH = 0.019 * S;
    const coinGap = 0.005 * S;
    const col1X = -0.101 * S;
    const col2X = col1X + stackW + 0.015 * S;

    const drawStack = (sx, count, startDelay) => {
      for (let c = 0; c < count; c++) {
        const dropK = easeOutCubic((coinDrop - (startDelay + c * 0.06)) / 0.35);
        if (dropK <= 0.01) continue;
        const restY = baseY - 0.005 * S - coinH - c * (coinH + coinGap);
        const curY = restY - (1 - dropK) * 0.022 * S;

        ctx.save();
        ctx.globalAlpha = clamp01(dropK * 1.3);
        roundRectPath(sx, curY, stackW, coinH, coinH * 0.42);
        const cg = ctx.createLinearGradient(sx, curY, sx + stackW, curY);
        cg.addColorStop(0, '#D97706');
        cg.addColorStop(0.5, '#FBBF24');
        cg.addColorStop(1, '#F59E0B');
        ctx.fillStyle = cg;
        ctx.fill();
        ctx.lineWidth = Math.max(1, 0.0018 * S);
        ctx.strokeStyle = '#FDE68A';
        ctx.stroke();

        // Top crisp specular bar inside coin
        roundRectPath(sx + 0.010 * S, curY + 0.0045 * S, stackW - 0.020 * S, 0.0035 * S, 0.00175 * S);
        ctx.fillStyle = '#FEF3C7';
        ctx.fill();
        ctx.restore();
      }
    };

    drawStack(col1X, 3, 0.0);
    drawStack(col2X, 5, 0.14);

    // Column 3: Circular Gold '$' Medallion resting cleanly on right end of baseline
    const medR = 0.032 * S;
    const medX = col2X + stackW + 0.015 * S + medR;
    const medDrop = easeOutCubic((coinDrop - 0.35) / 0.45);
    if (medDrop > 0.01) {
      const medRestY = baseY - 0.005 * S - medR;
      const medY = medRestY - (1 - medDrop) * 0.024 * S;
      ctx.save();
      ctx.globalAlpha = clamp01(medDrop * 1.2);
      ctx.beginPath();
      ctx.arc(medX, medY, medR, 0, Math.PI * 2);
      const mg = ctx.createLinearGradient(medX - medR, medY - medR, medX + medR, medY + medR);
      mg.addColorStop(0, '#FDE68A');
      mg.addColorStop(0.5, '#F59E0B');
      mg.addColorStop(1, '#B45309');
      ctx.fillStyle = mg;
      ctx.fill();
      ctx.lineWidth = Math.max(1, 0.0024 * S);
      ctx.strokeStyle = '#FEF3C7';
      ctx.stroke();

      ctx.beginPath();
      ctx.arc(medX, medY, medR * 0.76, 0, Math.PI * 2);
      ctx.fillStyle = '#D97706';
      ctx.fill();

      drawDollarSign(medX, medY, medR * 0.38, '#FEF3C7', Math.max(1, 0.0028 * S));
      ctx.restore();
    }

    ctx.restore();
  };

  drawBanknotesSatellite(satScales[0]);
  drawCardSatellite(satScales[1]);
  drawShieldSatellite(satScales[2]);
  drawCoinsSatellite(satScales[3]);
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const S = minSide;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const easeInOutCubic = (x) => {
    const v = clamp01(x);
    return v < 0.5 ? 4 * v * v * v : 1 - Math.pow(-2 * v + 2, 3) / 2;
  };
  const easeOutCubic = (x) => {
    const v = clamp01(x);
    return 1 - Math.pow(1 - v, 3);
  };
  const easeInOutSine = (x) => {
    const v = clamp01(x);
    return -(Math.cos(Math.PI * v) - 1) * 0.5;
  };
  const lerp = (a, b, k) => a + (b - a) * k;

  const roundRectPath = (x, y, w, h, r) => {
    const rad = Math.max(0, Math.min(r, w * 0.5, h * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  };

  // 1. Clean Modern Dark Aesthetic Gradient Background (Zero Glow, Zero Borders)
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, '#030E10');
  bgGrad.addColorStop(0.52, '#071B1F');
  bgGrad.addColorStop(1, '#0B272D');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // 2. Global Seamless Motion Parameters Driven by t, loopT, currentScene, sceneProgress
  const loopNorm = loopT / duration;
  const wavePhase = loopNorm * Math.PI * 2 * 6;
  const ambientPulse = 0.5 + 0.5 * Math.sin(loopNorm * Math.PI * 2 * 4);

  // Dial angle: 0 -> 2*PI in Scene 0, holds at 2*PI in Scenes 1-2, returns 2*PI -> 4*PI in Scene 3
  let dialAngle = 0;
  let dialTickProgress = 0;
  let boltRetract = 0;
  let lockReady = 0;
  let doorOpen = 0;
  let liquidFill = 0.30;
  let streamIntensity = 0;
  let gaugeRatio = 0.28;
  let shieldCheckProgress = 0;
  let inflowActivity = 0.22;
  let conduitLeftFlow = 0;
  let conduitRightFlow = 0;

  if (currentScene === 0) {
    // Scene 0 (0-5s): Combination dial spin, tick illumination, bolt retraction
    const dialT = easeInOutCubic(sceneProgress / 0.72);
    dialAngle = dialT * Math.PI * 2;
    dialTickProgress = clamp01(sceneProgress / 0.70);
    lockReady = easeInOutCubic((sceneProgress - 0.55) / 0.22);
    boltRetract = easeInOutCubic((sceneProgress - 0.68) / 0.28);
    doorOpen = 0;
    liquidFill = 0.30;
    streamIntensity = 0;
    gaugeRatio = 0.28;
    shieldCheckProgress = 0;
    inflowActivity = 0.22 + 0.12 * easeInOutSine(sceneProgress);
    conduitLeftFlow = 0.25 * easeInOutSine(sceneProgress);
    conduitRightFlow = 0.10;
  } else if (currentScene === 1) {
    // Scene 1 (5-10s): Door slides open cleanly, liquid pours & rises, left inflow active
    dialAngle = Math.PI * 2;
    dialTickProgress = 1;
    lockReady = 1;
    boltRetract = 1;
    doorOpen = easeInOutCubic(sceneProgress / 0.32);
    const fillEase = easeInOutCubic((sceneProgress - 0.18) / 0.76);
    liquidFill = lerp(0.30, 0.80, fillEase);
    const streamIn = easeOutCubic((sceneProgress - 0.14) / 0.16);
    const streamOut = 1 - easeInOutCubic((sceneProgress - 0.80) / 0.16);
    streamIntensity = clamp01(Math.min(streamIn, streamOut));
    gaugeRatio = lerp(0.28, 0.92, fillEase);
    shieldCheckProgress = 0;
    inflowActivity = 0.34 + 0.66 * Math.sin(clamp01((sceneProgress - 0.10) / 0.85) * Math.PI);
    conduitLeftFlow = 0.25 + 0.75 * easeInOutSine(clamp01(sceneProgress / 0.30));
    conduitRightFlow = lerp(0.10, 0.65, fillEase);
  } else if (currentScene === 2) {
    // Scene 2 (10-15s): Vault tank sustained, shield check verified, right telemetry active
    dialAngle = Math.PI * 2;
    dialTickProgress = 1;
    lockReady = 1;
    boltRetract = 1;
    doorOpen = 1;
    liquidFill = 0.80 + 0.014 * Math.sin(sceneProgress * Math.PI * 2);
    streamIntensity = 0;
    gaugeRatio = lerp(0.92, 0.96, easeInOutSine(sceneProgress));
    shieldCheckProgress = easeInOutCubic((sceneProgress - 0.10) / 0.55);
    inflowActivity = 0.36 + 0.12 * Math.sin(sceneProgress * Math.PI * 2);
    conduitLeftFlow = 0.45;
    conduitRightFlow = 0.65 + 0.35 * Math.sin(sceneProgress * Math.PI);
  } else {
    // Scene 3 (15-20s): Controlled drainage, smooth door seal, bolt engagement, dial reset
    const drainEase = easeInOutCubic(sceneProgress / 0.52);
    liquidFill = lerp(0.80, 0.30, drainEase);
    gaugeRatio = lerp(0.96, 0.28, drainEase);
    shieldCheckProgress = 1 - easeInOutCubic(sceneProgress / 0.32);
    doorOpen = 1 - easeInOutCubic((sceneProgress - 0.32) / 0.34);
    boltRetract = 1 - easeInOutCubic((sceneProgress - 0.64) / 0.20);
    lockReady = 1 - easeInOutCubic((sceneProgress - 0.66) / 0.24);
    const resetDial = easeInOutCubic((sceneProgress - 0.68) / 0.32);
    dialAngle = Math.PI * 2 + resetDial * Math.PI * 2;
    dialTickProgress = 1 - easeInOutCubic((sceneProgress - 0.68) / 0.30);
    streamIntensity = 0;
    inflowActivity = lerp(0.36, 0.22, easeInOutSine(sceneProgress));
    conduitLeftFlow = lerp(0.45, 0.0, easeInOutCubic(sceneProgress / 0.55));
    conduitRightFlow = lerp(0.65, 0.10, easeInOutCubic(sceneProgress / 0.70));
  }

  // 3. Grounding Pedestal Pill Beneath Vault (Strict Separation Gap)
  ctx.save();
  const pedW = 0.44 * S;
  const pedH = 0.020 * S;
  const pedY = cy + 0.312 * S;
  roundRectPath(cx - pedW * 0.5, pedY, pedW, pedH, pedH * 0.5);
  ctx.fillStyle = '#040F12';
  ctx.fill();
  ctx.lineWidth = Math.max(1, 0.0022 * S);
  ctx.strokeStyle = '#18434B';
  ctx.stroke();
  ctx.restore();

  // 4. Precision Conduit Buses Connecting Left Card -> Vault -> Right Card (Strictly Non-Touching)
  const drawConduit = (xStart, xEnd, flowActive, reverseGlowDir) => {
    ctx.save();
    const yRail = cy;
    const termR = 0.0075 * S;
    const railH = 0.009 * S;
    const padX = 0.011 * S;

    // Outer recessed track
    roundRectPath(xStart, yRail - railH * 0.5, xEnd - xStart, railH, railH * 0.5);
    ctx.fillStyle = '#07181C';
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.002 * S);
    ctx.strokeStyle = '#1B4952';
    ctx.stroke();

    // Terminal anchor dots cleanly aligned with clear air gap from cards & vault
    [xStart, xEnd].forEach((tx) => {
      ctx.beginPath();
      ctx.arc(tx, yRail, termR, 0, Math.PI * 2);
      ctx.fillStyle = '#0F2E34';
      ctx.fill();
      ctx.lineWidth = Math.max(1, 0.0024 * S);
      ctx.strokeStyle = flowActive > 0.2 ? '#10B981' : '#25606B';
      ctx.stroke();
    });

    // Clipped animated signal packets inside track
    const innerStart = xStart + padX;
    const innerEnd = xEnd - padX;
    const span = innerEnd - innerStart;
    if (span > 0 && flowActive > 0.02) {
      ctx.save();
      roundRectPath(innerStart, yRail - railH * 0.42, span, railH * 0.84, railH * 0.42);
      ctx.clip();

      const packetCount = 3;
      const packetW = 0.024 * S;
      const cycleSpeed = 4; // Exact integer cycles over 20s for seamless loop
      for (let i = 0; i < packetCount; i++) {
        const phase = (loopNorm * cycleSpeed + i / packetCount) % 1;
        const dirPhase = reverseGlowDir ? 1 - phase : phase;
        const px = innerStart - packetW + dirPhase * (span + packetW);
        const fadeEdge = Math.sin(dirPhase * Math.PI);
        ctx.globalAlpha = clamp01(flowActive * fadeEdge * 1.15);
        roundRectPath(px, yRail - railH * 0.34, packetW, railH * 0.68, railH * 0.34);
        ctx.fillStyle = '#34D399';
        ctx.fill();
      }
      ctx.restore();
    }
    ctx.restore();
  };

  drawConduit(cx - 0.422 * S, cx - 0.273 * S, conduitLeftFlow, false);
  drawConduit(cx + 0.273 * S, cx + 0.422 * S, conduitRightFlow, false);

  // 5. Left Telemetry Module — Cashflow Inflow Card
  const drawLeftCard = () => {
    const cardW = 0.24 * S;
    const cardH = 0.34 * S;
    const cardX = cx - 0.56 * S - cardW * 0.5;
    const cardY = cy - cardH * 0.5;
    const cardR = 0.024 * S;

    ctx.save();
    roundRectPath(cardX, cardY, cardW, cardH, cardR);
    const cardGrad = ctx.createLinearGradient(cardX, cardY, cardX, cardY + cardH);
    cardGrad.addColorStop(0, '#0E292F');
    cardGrad.addColorStop(1, '#08191D');
    ctx.fillStyle = cardGrad;
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.003 * S);
    ctx.strokeStyle = '#205660';
    ctx.stroke();

    // Header row: circular emerald '$' medallion + clean structural label bars
    const badgeR = 0.024 * S;
    const badgeCx = cardX + 0.050 * S;
    const badgeCy = cardY + 0.052 * S;

    ctx.beginPath();
    ctx.arc(badgeCx, badgeCy, badgeR, 0, Math.PI * 2);
    ctx.fillStyle = '#064E3B';
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.0026 * S);
    ctx.strokeStyle = '#10B981';
    ctx.stroke();

    // Vector '$' symbol (crisp pure geometric paths)
    ctx.save();
    ctx.translate(badgeCx, badgeCy);
    ctx.strokeStyle = '#A7F3D0';
    ctx.lineWidth = Math.max(1, 0.0036 * S);
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    const dR = badgeR * 0.48;
    ctx.beginPath();
    ctx.moveTo(0, -dR * 1.15);
    ctx.lineTo(0, dR * 1.15);
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(dR * 0.68, -dR * 0.48);
    ctx.bezierCurveTo(dR * 0.65, -dR * 0.92, -dR * 0.72, -dR * 0.92, -dR * 0.68, -dR * 0.36);
    ctx.bezierCurveTo(-dR * 0.64, 0, dR * 0.68, 0, dR * 0.68, dR * 0.40);
    ctx.bezierCurveTo(dR * 0.68, dR * 0.92, -dR * 0.68, dR * 0.92, -dR * 0.72, dR * 0.48);
    ctx.stroke();
    ctx.restore();

    // Header clean bars centered vertically on badgeCy
    roundRectPath(cardX + 0.090 * S, badgeCy - 0.011 * S, 0.104 * S, 0.009 * S, 0.0045 * S);
    ctx.fillStyle = '#94A3B8';
    ctx.fill();
    roundRectPath(cardX + 0.090 * S, badgeCy + 0.005 * S, 0.068 * S, 0.007 * S, 0.0035 * S);
    ctx.fillStyle = '#2B6874';
    ctx.fill();

    // Middle Row: 4 Equalizer Cashflow Bars
    const chartLeft = cardX + 0.032 * S;
    const chartW = cardW - 0.064 * S;
    const chartBottom = cardY + 0.242 * S;
    const maxBarH = 0.120 * S;
    const barCount = 4;
    const barGap = 0.016 * S;
    const barW = (chartW - barGap * (barCount - 1)) / barCount;

    // Baseline
    roundRectPath(chartLeft, chartBottom + 0.008 * S, chartW, 0.004 * S, 0.002 * S);
    ctx.fillStyle = '#18434C';
    ctx.fill();

    const baseProfile = [0.42, 0.66, 0.85, 0.58];
    for (let i = 0; i < barCount; i++) {
      const bx = chartLeft + i * (barW + barGap);
      // Track slot
      roundRectPath(bx, chartBottom - maxBarH, barW, maxBarH, barW * 0.32);
      ctx.fillStyle = '#07161A';
      ctx.fill();

      const osc = 0.08 * Math.sin(loopNorm * Math.PI * 2 * 4 - i * 1.15);
      const level = clamp01(baseProfile[i] * (0.45 + 0.55 * inflowActivity) + osc);
      const bh = Math.max(barW, maxBarH * level);
      const by = chartBottom - bh;

      roundRectPath(bx, by, barW, bh, barW * 0.32);
      const barGrad = ctx.createLinearGradient(bx, by, bx, chartBottom);
      barGrad.addColorStop(0, '#34D399');
      barGrad.addColorStop(1, '#059669');
      ctx.fillStyle = barGrad;
      ctx.fill();
    }

    // Bottom Row: Horizontal Liquidity Rate Track
    const trackX = cardX + 0.030 * S;
    const trackY = cardY + 0.286 * S;
    const trackW = cardW - 0.060 * S;
    const trackH = 0.014 * S;
    roundRectPath(trackX, trackY, trackW, trackH, trackH * 0.5);
    ctx.fillStyle = '#07161A';
    ctx.fill();

    const fillW = Math.max(trackH, trackW * gaugeRatio);
    roundRectPath(trackX, trackY, fillW, trackH, trackH * 0.5);
    const trackGrad = ctx.createLinearGradient(trackX, trackY, trackX + fillW, trackY);
    trackGrad.addColorStop(0, '#059669');
    trackGrad.addColorStop(1, '#6EE7B7');
    ctx.fillStyle = trackGrad;
    ctx.fill();

    ctx.restore();
  };

  drawLeftCard();

  // 6. Right Telemetry Module — Liquidity Ring Gauge & Security Shield
  const drawRightCard = () => {
    const cardW = 0.24 * S;
    const cardH = 0.34 * S;
    const cardX = cx + 0.56 * S - cardW * 0.5;
    const cardY = cy - cardH * 0.5;
    const cardR = 0.024 * S;

    ctx.save();
    roundRectPath(cardX, cardY, cardW, cardH, cardR);
    const cardGrad = ctx.createLinearGradient(cardX, cardY, cardX, cardY + cardH);
    cardGrad.addColorStop(0, '#0E292F');
    cardGrad.addColorStop(1, '#08191D');
    ctx.fillStyle = cardGrad;
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.003 * S);
    ctx.strokeStyle = '#205660';
    ctx.stroke();

    // Top Half: Circular Liquidity Gauge Ring
    const ringCx = cardX + cardW * 0.5;
    const ringCy = cardY + 0.104 * S;
    const ringR = 0.058 * S;
    const ringLW = 0.013 * S;
    const startA = -Math.PI * 0.5;
    const endA = startA + Math.PI * 2 * clamp01(gaugeRatio);

    ctx.beginPath();
    ctx.arc(ringCx, ringCy, ringR, 0, Math.PI * 2);
    ctx.lineWidth = ringLW;
    ctx.strokeStyle = '#07161A';
    ctx.stroke();

    const ringGrad = ctx.createLinearGradient(ringCx - ringR, ringCy - ringR, ringCx + ringR, ringCy + ringR);
    ringGrad.addColorStop(0, '#059669');
    ringGrad.addColorStop(0.5, '#10B981');
    ringGrad.addColorStop(1, '#6EE7B7');

    ctx.beginPath();
    ctx.arc(ringCx, ringCy, ringR, startA, endA);
    ctx.lineWidth = ringLW;
    ctx.lineCap = 'round';
    ctx.strokeStyle = ringGrad;
    ctx.stroke();

    // Tip marker dot
    const tipX = ringCx + Math.cos(endA) * ringR;
    const tipY = ringCy + Math.sin(endA) * ringR;
    ctx.beginPath();
    ctx.arc(tipX, tipY, 0.0085 * S, 0, Math.PI * 2);
    ctx.fillStyle = '#ECFDF5';
    ctx.fill();

    // Inside ring: Crisp upward growth arrow icon
    ctx.save();
    ctx.translate(ringCx, ringCy);
    ctx.strokeStyle = '#6EE7B7';
    ctx.lineWidth = Math.max(1, 0.004 * S);
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    const arrS = 0.022 * S;
    ctx.beginPath();
    ctx.moveTo(0, arrS * 0.78);
    ctx.lineTo(0, -arrS * 0.78);
    ctx.moveTo(-arrS * 0.62, -arrS * 0.15);
    ctx.lineTo(0, -arrS * 0.78);
    ctx.lineTo(arrS * 0.62, -arrS * 0.15);
    ctx.stroke();
    ctx.restore();

    // Divider line
    const divY = cardY + 0.190 * S;
    roundRectPath(cardX + 0.040 * S, divY, cardW - 0.080 * S, 0.0025 * S, 0.00125 * S);
    ctx.fillStyle = '#18444D';
    ctx.fill();

    // Bottom Half: Security Shield Badge with Animated Trim-Path Checkmark
    const shCx = cardX + cardW * 0.5;
    const shCy = cardY + 0.256 * S;
    const shW = 0.078 * S;
    const shH = 0.088 * S;

    const drawShieldPath = () => {
      ctx.beginPath();
      ctx.moveTo(shCx, shCy - shH * 0.5);
      ctx.lineTo(shCx + shW * 0.5, shCy - shH * 0.30);
      ctx.lineTo(shCx + shW * 0.44, shCy + shH * 0.10);
      ctx.quadraticCurveTo(shCx + shW * 0.34, shCy + shH * 0.38, shCx, shCy + shH * 0.52);
      ctx.quadraticCurveTo(shCx - shW * 0.34, shCy + shH * 0.38, shCx - shW * 0.44, shCy + shH * 0.10);
      ctx.lineTo(shCx - shW * 0.5, shCy - shH * 0.30);
      ctx.closePath();
    };

    drawShieldPath();
    const shGrad = ctx.createLinearGradient(shCx, shCy - shH * 0.5, shCx, shCy + shH * 0.5);
    shGrad.addColorStop(0, shieldCheckProgress > 0.2 ? '#0B5E46' : '#0D2930');
    shGrad.addColorStop(1, shieldCheckProgress > 0.2 ? '#063B2C' : '#081B1F');
    ctx.fillStyle = shGrad;
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.0032 * S);
    ctx.strokeStyle = shieldCheckProgress > 0.2 ? '#34D399' : '#25616D';
    ctx.stroke();

    // Animated Vector Checkmark inside Shield
    if (shieldCheckProgress > 0.01) {
      const p1 = { x: shCx - shW * 0.22, y: shCy + shH * 0.02 };
      const p2 = { x: shCx - shW * 0.04, y: shCy + shH * 0.18 };
      const p3 = { x: shCx + shW * 0.24, y: shCy - shH * 0.14 };

      const seg1Len = Math.hypot(p2.x - p1.x, p2.y - p1.y);
      const seg2Len = Math.hypot(p3.x - p2.x, p3.y - p2.y);
      const totalLen = seg1Len + seg2Len;
      const drawnLen = totalLen * clamp01(shieldCheckProgress);

      ctx.beginPath();
      ctx.moveTo(p1.x, p1.y);
      if (drawnLen <= seg1Len) {
        const k = drawnLen / seg1Len;
        ctx.lineTo(lerp(p1.x, p2.x, k), lerp(p1.y, p2.y, k));
      } else {
        ctx.lineTo(p2.x, p2.y);
        const k = (drawnLen - seg1Len) / seg2Len;
        ctx.lineTo(lerp(p2.x, p3.x, k), lerp(p2.y, p3.y, k));
      }
      ctx.lineWidth = Math.max(1, 0.0052 * S);
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.strokeStyle = '#A7F3D0';
      ctx.stroke();
    } else {
      // Clean resting keyhole indicator dot when unverified
      ctx.beginPath();
      ctx.arc(shCx, shCy, 0.008 * S, 0, Math.PI * 2);
      ctx.fillStyle = '#25616D';
      ctx.fill();
    }

    ctx.restore();
  };

  drawRightCard();

  // 7. Hero Centerpiece — Precision Bank Vault
  const vaultW = 0.51 * S;
  const vaultH = 0.55 * S;
  const vaultX = cx - vaultW * 0.5;
  const vaultY = cy - vaultH * 0.5;
  const vaultR = 0.044 * S;

  // Outer Vault Chassis
  ctx.save();
  roundRectPath(vaultX, vaultY, vaultW, vaultH, vaultR);
  const chassisGrad = ctx.createLinearGradient(vaultX, vaultY, vaultX, vaultY + vaultH);
  chassisGrad.addColorStop(0, '#163A42');
  chassisGrad.addColorStop(0.5, '#102C32');
  chassisGrad.addColorStop(1, '#0B2025');
  ctx.fillStyle = chassisGrad;
  ctx.fill();

  ctx.lineWidth = Math.max(1, 0.0045 * S);
  ctx.strokeStyle = '#2D6B77';
  ctx.stroke();

  // Inner Chassis Bevel Ring (strictly spaced inside outer frame)
  const bevelPad = 0.020 * S;
  roundRectPath(
    vaultX + bevelPad,
    vaultY + bevelPad,
    vaultW - bevelPad * 2,
    vaultH - bevelPad * 2,
    vaultR - bevelPad * 0.45
  );
  ctx.lineWidth = Math.max(1, 0.002 * S);
  ctx.strokeStyle = '#1E4C55';
  ctx.stroke();

  // 4 Precision Corner Chassis Rivets (strictly inside frame margin)
  const rivetOffX = vaultW * 0.5 - 0.038 * S;
  const rivetOffY = vaultH * 0.5 - 0.038 * S;
  const rivetR = 0.009 * S;
  [
    [-1, -1],
    [1, -1],
    [-1, 1],
    [1, 1],
  ].forEach(([sx, sy]) => {
    const rx = cx + sx * rivetOffX;
    const ry = cy + sy * rivetOffY;
    ctx.beginPath();
    ctx.arc(rx, ry, rivetR, 0, Math.PI * 2);
    ctx.fillStyle = '#091A1E';
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.002 * S);
    ctx.strokeStyle = '#2A636E';
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(rx, ry, rivetR * 0.4, 0, Math.PI * 2);
    ctx.fillStyle = '#4A8E9B';
    ctx.fill();
  });

  // Inner Vault Aperture (Window Chamber)
  const winW = 0.37 * S;
  const winH = 0.41 * S;
  const winX = cx - winW * 0.5;
  const winY = cy - winH * 0.5;
  const winR = 0.026 * S;

  // Clip strictly to Inner Vault Aperture
  ctx.save();
  roundRectPath(winX, winY, winW, winH, winR);
  ctx.clip();

  // Layer A: Crystal Liquid Liquidity Tank
  ctx.fillStyle = '#051215';
  ctx.fillRect(winX, winY, winW, winH);

  // Clean calibration scale ticks along inner glass edges (left & right, clear of liquid bubbles)
  ctx.save();
  ctx.strokeStyle = 'rgba(110, 231, 183, 0.28)';
  ctx.lineWidth = Math.max(1, 0.0022 * S);
  const tickCount = 7;
  for (let i = 1; i <= tickCount; i++) {
    const ty = winY + winH - (i / (tickCount + 1)) * winH;
    const tLen = i % 2 === 0 ? 0.018 * S : 0.011 * S;
    ctx.beginPath();
    ctx.moveTo(winX + 0.012 * S, ty);
    ctx.lineTo(winX + 0.012 * S + tLen, ty);
    ctx.moveTo(winX + winW - 0.012 * S, ty);
    ctx.lineTo(winX + winW - 0.012 * S - tLen, ty);
    ctx.stroke();
  }
  ctx.restore();

  // Top inflow stream (active cleanly during Scene 1 fill)
  const baseLiquidY = winY + winH * (1 - liquidFill);
  const waveAmp = (0.009 + 0.007 * streamIntensity) * S;
  const getFrontWaveY = (px) => {
    const nx = (px - winX) / winW;
    return (
      baseLiquidY +
      Math.sin(nx * Math.PI * 2.5 + wavePhase) * waveAmp +
      Math.cos(nx * Math.PI * 4.5 - wavePhase * 0.5) * (waveAmp * 0.35)
    );
  };
  const getBackWaveY = (px) => {
    const nx = (px - winX) / winW;
    return (
      baseLiquidY -
      0.004 * S +
      Math.sin(nx * Math.PI * 2.5 - wavePhase + 1.4) * (waveAmp * 0.85)
    );
  };

  // Nozzle Housing at Top of Tank
  const nozW = 0.064 * S;
  const nozH = 0.018 * S;
  roundRectPath(cx - nozW * 0.5, winY - 0.002 * S, nozW, nozH, 0.006 * S);
  ctx.fillStyle = '#19424A';
  ctx.fill();
  ctx.lineWidth = Math.max(1, 0.002 * S);
  ctx.strokeStyle = '#2E727F';
  ctx.stroke();

  // Pouring Stream from Nozzle into Rising Surface
  if (streamIntensity > 0.01) {
    const streamTop = winY + nozH - 0.002 * S;
    const streamBot = getFrontWaveY(cx) + 0.010 * S;
    const streamW = 0.022 * S * streamIntensity;
    if (streamBot > streamTop) {
      ctx.beginPath();
      const steps = 18;
      for (let i = 0; i <= steps; i++) {
        const k = i / steps;
        const sy = lerp(streamTop, streamBot, k);
        const sway = Math.sin(k * Math.PI * 3 - wavePhase * 1.5) * 0.003 * S * streamIntensity;
        const halfW = streamW * (0.52 - 0.14 * Math.sin(k * Math.PI * 0.5));
        if (i === 0) ctx.moveTo(cx - halfW + sway, sy);
        else ctx.lineTo(cx - halfW + sway, sy);
      }
      for (let i = steps; i >= 0; i--) {
        const k = i / steps;
        const sy = lerp(streamTop, streamBot, k);
        const sway = Math.sin(k * Math.PI * 3 - wavePhase * 1.5) * 0.003 * S * streamIntensity;
        const halfW = streamW * (0.52 - 0.14 * Math.sin(k * Math.PI * 0.5));
        ctx.lineTo(cx + halfW + sway, sy);
      }
      ctx.closePath();
      const stGrad = ctx.createLinearGradient(cx, streamTop, cx, streamBot);
      stGrad.addColorStop(0, '#6EE7B7');
      stGrad.addColorStop(1, '#10B981');
      ctx.fillStyle = stGrad;
      ctx.fill();
    }
  }

  // Back Liquid Wave
  const waveSteps = 32;
  ctx.beginPath();
  ctx.moveTo(winX, winY + winH);
  for (let i = 0; i <= waveSteps; i++) {
    const px = winX + (i / waveSteps) * winW;
    ctx.lineTo(px, getBackWaveY(px));
  }
  ctx.lineTo(winX + winW, winY + winH);
  ctx.closePath();
  ctx.fillStyle = '#065F46';
  ctx.fill();

  // Front Liquid Wave
  ctx.beginPath();
  ctx.moveTo(winX, winY + winH);
  for (let i = 0; i <= waveSteps; i++) {
    const px = winX + (i / waveSteps) * winW;
    ctx.lineTo(px, getFrontWaveY(px));
  }
  ctx.lineTo(winX + winW, winY + winH);
  ctx.closePath();
  const liqGrad = ctx.createLinearGradient(cx, baseLiquidY, cx, winY + winH);
  liqGrad.addColorStop(0, '#10B981');
  liqGrad.addColorStop(0.45, '#059669');
  liqGrad.addColorStop(1, '#064E3B');
  ctx.fillStyle = liqGrad;
  ctx.fill();

  // Crisp Crest Highlight Line on Front Wave
  ctx.beginPath();
  for (let i = 0; i <= waveSteps; i++) {
    const px = winX + (i / waveSteps) * winW;
    const py = getFrontWaveY(px);
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.lineWidth = Math.max(1, 0.004 * S);
  ctx.strokeStyle = '#6EE7B7';
  ctx.stroke();

  // Rising Precision Bubbles Strictly Inside Liquid Body
  const bubbleCount = 9;
  for (let i = 0; i < bubbleCount; i++) {
    const cycles = (i % 2) + 2; // 2 or 3 exact loops in 20s
    const prog = (loopNorm * cycles + i * 0.137) % 1;
    const bx = winX + 0.048 * S + ((i * 0.0365 * S) % (winW - 0.096 * S));
    const swayX = bx + Math.sin(prog * Math.PI * 2 + i) * 0.007 * S;
    const surfaceAtX = getFrontWaveY(swayX);
    const botY = winY + winH - 0.015 * S;
    const topY = surfaceAtX + 0.016 * S;
    if (botY > topY) {
      const by = lerp(botY, topY, prog);
      const bRad = (0.0038 + (i % 3) * 0.0018) * S;
      const alpha = Math.sin(prog * Math.PI) * 0.72;
      ctx.save();
      ctx.globalAlpha = clamp01(alpha);
      ctx.beginPath();
      ctx.arc(swayX, by, bRad, 0, Math.PI * 2);
      ctx.fillStyle = '#A7F3D0';
      ctx.fill();
      ctx.restore();
    }
  }

  // Subtle Vertical Glass Specular Highlight Strips inside Aperture
  ctx.save();
  ctx.globalAlpha = 0.09;
  roundRectPath(winX + 0.014 * S, winY + 0.022 * S, 0.010 * S, winH - 0.044 * S, 0.005 * S);
  ctx.fillStyle = '#E2F8F3';
  ctx.fill();
  ctx.restore();

  // Layer B: Sliding Precision Armored Vault Door (Clipped cleanly inside Aperture)
  const doorSlideX = -doorOpen * (winW + 0.01 * S);
  if (doorOpen < 0.999) {
    ctx.save();
    ctx.translate(doorSlideX, 0);

    // Door body
    const doorGrad = ctx.createLinearGradient(winX, winY, winX + winW, winY + winH);
    doorGrad.addColorStop(0, '#1B444D');
    doorGrad.addColorStop(0.55, '#123138');
    doorGrad.addColorStop(1, '#0C2227');
    ctx.fillStyle = doorGrad;
    ctx.fillRect(winX, winY, winW, winH);

    // Door interior recessed panel lines (strictly enclosing bolts & dial without touching)
    const dPad = 0.012 * S;
    roundRectPath(winX + dPad, winY + dPad, winW - dPad * 2, winH - dPad * 2, 0.018 * S);
    ctx.lineWidth = Math.max(1, 0.0022 * S);
    ctx.strokeStyle = '#2B6874';
    ctx.stroke();

    // 4 Precision Horizontal Locking Bolts (Strictly between dPad and dialOuterR with zero line crossing)
    const boltW = 0.026 * S;
    const boltH = 0.020 * S;
    const boltSlotW = 0.044 * S;
    const boltSlide = boltRetract * 0.014 * S;
    [-1, 1].forEach((sy) => {
      const by = cy + sy * 0.115 * S - boltH * 0.5;

      // Left bolt housing & bolt
      const leftSlotX = winX + 0.022 * S;
      roundRectPath(leftSlotX, by - 0.004 * S, boltSlotW, boltH + 0.008 * S, 0.006 * S);
      ctx.fillStyle = '#07171B';
      ctx.fill();

      roundRectPath(leftSlotX + 0.003 * S + boltSlide, by, boltW, boltH, 0.005 * S);
      ctx.fillStyle = lockReady > 0.5 ? '#34D399' : '#94A3B8';
      ctx.fill();

      // Right bolt housing & bolt
      const rightSlotX = winX + winW - 0.022 * S - boltSlotW;
      roundRectPath(rightSlotX, by - 0.004 * S, boltSlotW, boltH + 0.008 * S, 0.006 * S);
      ctx.fillStyle = '#07171B';
      ctx.fill();

      roundRectPath(rightSlotX + boltSlotW - 0.003 * S - boltW - boltSlide, by, boltW, boltH, 0.005 * S);
      ctx.fillStyle = lockReady > 0.5 ? '#34D399' : '#94A3B8';
      ctx.fill();
    });

    // Central Combination Dial Assembly
    const dialOuterR = 0.098 * S;
    const dialPlateR = 0.070 * S;

    // Dial base socket
    ctx.beginPath();
    ctx.arc(cx, cy, dialOuterR, 0, Math.PI * 2);
    ctx.fillStyle = '#07181C';
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.003 * S);
    ctx.strokeStyle = '#29636E';
    ctx.stroke();

    // 12 Crisp Radial Tick Markers Around Dial Rim
    const tickTotal = 12;
    for (let i = 0; i < tickTotal; i++) {
      const ang = -Math.PI * 0.5 + (i / tickTotal) * Math.PI * 2;
      const litThreshold = i / tickTotal;
      const isLit = dialTickProgress > litThreshold;
      const r1 = dialPlateR + 0.008 * S;
      const r2 = dialOuterR - 0.008 * S;
      ctx.beginPath();
      ctx.moveTo(cx + Math.cos(ang) * r1, cy + Math.sin(ang) * r1);
      ctx.lineTo(cx + Math.cos(ang) * r2, cy + Math.sin(ang) * r2);
      ctx.lineWidth = Math.max(1, 0.0036 * S);
      ctx.lineCap = 'round';
      ctx.strokeStyle = isLit ? '#34D399' : '#25535C';
      ctx.stroke();
    }

    // Rotating Dial Wheel
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(dialAngle);

    ctx.beginPath();
    ctx.arc(0, 0, dialPlateR, 0, Math.PI * 2);
    const wheelGrad = ctx.createLinearGradient(-dialPlateR, -dialPlateR, dialPlateR, dialPlateR);
    wheelGrad.addColorStop(0, '#E2E8F0');
    wheelGrad.addColorStop(1, '#64748B');
    ctx.fillStyle = wheelGrad;
    ctx.fill();

    // Inner Dial Recess
    ctx.beginPath();
    ctx.arc(0, 0, dialPlateR * 0.78, 0, Math.PI * 2);
    ctx.fillStyle = '#113037';
    ctx.fill();

    // 3 Crisp Symmetric Spoke Grips
    for (let s = 0; s < 3; s++) {
      const sa = (s * Math.PI * 2) / 3 - Math.PI * 0.5;
      ctx.save();
      ctx.rotate(sa);
      roundRectPath(-0.0065 * S, -dialPlateR * 0.72, 0.013 * S, dialPlateR * 0.44, 0.0065 * S);
      ctx.fillStyle = s === 0 ? '#34D399' : '#CBD5E1';
      ctx.fill();
      ctx.restore();
    }

    // Central Lock Status Core
    ctx.beginPath();
    ctx.arc(0, 0, 0.022 * S, 0, Math.PI * 2);
    ctx.fillStyle = '#07181C';
    ctx.fill();
    ctx.lineWidth = Math.max(1, 0.003 * S);
    ctx.strokeStyle = lockReady > 0.5 ? '#34D399' : '#94A3B8';
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(0, 0, 0.009 * S, 0, Math.PI * 2);
    ctx.fillStyle = lockReady > 0.5 ? '#10B981' : '#64748B';
    ctx.fill();

    ctx.restore();
    ctx.restore();
  }

  ctx.restore(); // End inner aperture clip

  // Crisp Inner Aperture Bevel Frame Over Clipped Window
  roundRectPath(winX, winY, winW, winH, winR);
  ctx.lineWidth = Math.max(1, 0.005 * S);
  ctx.strokeStyle = '#2B6773';
  ctx.stroke();

  // Top Subtle Status Indicator Bar on Vault Header Bezel
  const topBarW = 0.14 * S;
  const topBarH = 0.010 * S;
  const topBarY = vaultY + 0.030 * S;
  roundRectPath(cx - topBarW * 0.5, topBarY, topBarW, topBarH, topBarH * 0.5);
  ctx.fillStyle = '#07181C';
  ctx.fill();

  const statusFillW = lerp(0.03 * S, topBarW, 0.35 + 0.65 * Math.max(lockReady, ambientPulse * 0.35));
  roundRectPath(cx - statusFillW * 0.5, topBarY, statusFillW, topBarH, topBarH * 0.5);
  ctx.fillStyle = doorOpen > 0.5 ? '#34D399' : '#10B981';
  ctx.fill();

  ctx.restore();
}
